module cg_generic_fifo_sync_cnt_Chisel(
  input        clk_i,
               rst_ni,
               incr_wptr_i,
               incr_rptr_i,
  output [1:0] wptr_o,
               rptr_o
);

  wire       _rptr_q_T = ~rst_ni;
  reg  [1:0] wptr_q;
  reg  [1:0] rptr_q;
  always @(posedge clk_i or posedge _rptr_q_T) begin
    if (_rptr_q_T) begin
      wptr_q <= 2'h0;
      rptr_q <= 2'h0;
    end
    else begin
      if (incr_wptr_i & wptr_q[0])
        wptr_q <= {~(wptr_q[1]), 1'h0};
      else if (incr_wptr_i)
        wptr_q <= wptr_q + 2'h1;
      if (incr_rptr_i & rptr_q[0])
        rptr_q <= {~(rptr_q[1]), 1'h0};
      else if (incr_rptr_i)
        rptr_q <= rptr_q + 2'h1;
    end
  end  
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif  
    initial begin
      if (_rptr_q_T) begin
        wptr_q = 2'h0;
        rptr_q = 2'h0;
      end
    end  
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif  
  `endif  
  assign wptr_o = wptr_q;
  assign rptr_o = rptr_q;
endmodule


