module FifoE52W1R_2(
  input          clock,
                 reset,
                 io_push_i_i0,
                 io_push_i_i1,
                 io_pop_i,
                 io_flush_i,
                 io_valid_i_i0,
                 io_valid_i_i1,
  input  [141:0] io_data_i_i0,
                 io_data_i_i1,
  output         io_valid_o,
  output [141:0] io_data_o,
  output         io_empty_o,
                 io_full_o,
                 io_almost_full_o
);

  wire              _fifoValid_q_T_1 = ~reset;
  reg               fifoValid_q_0;
  reg               fifoValid_q_1;
  reg               fifoValid_q_2;
  reg               fifoValid_q_3;
  wire              _fifoData_q_T_1 = ~reset;
  reg  [141:0]      fifoData_q_0;
  reg  [141:0]      fifoData_q_1;
  reg  [141:0]      fifoData_q_2;
  reg  [141:0]      fifoData_q_3;
  wire              _fifo_wPtr_T_1 = ~reset;
  reg               fifo_wPtr_flag;
  reg  [1:0]        fifo_wPtr_bits;
  wire              _fifo_rPtr_T_1 = ~reset;
  reg               fifo_rPtr_flag;
  reg  [1:0]        fifo_rPtr_bits;
  wire              _GEN = io_push_i_i0 & io_push_i_i1;
  wire              _GEN_0 = fifo_wPtr_bits == 2'h0;
  wire              _GEN_1 = fifo_wPtr_bits == 2'h1;
  wire              _GEN_2 = fifo_wPtr_bits == 2'h2;
  wire [1:0]        _GEN_3 = fifo_wPtr_bits + 2'h1;
  wire              _GEN_4 = _GEN_3 == 2'h0;
  wire              _GEN_5 = _GEN_3 == 2'h1;
  wire              _GEN_6 = _GEN_3 == 2'h2;
  wire              _GEN_7 = io_push_i_i1 & _GEN_0;
  wire              _GEN_8 = io_push_i_i1 & _GEN_1;
  wire              _GEN_9 = io_push_i_i1 & _GEN_2;
  wire              _GEN_10 = io_push_i_i1 & (&fifo_wPtr_bits);
  wire              _GEN_11 = io_pop_i & (&fifo_rPtr_bits);
  wire              _fifo_Full_d_T_1 = fifo_wPtr_bits == fifo_rPtr_bits;
  wire              fifo_Full_d = fifo_wPtr_flag != fifo_rPtr_flag & _fifo_Full_d_T_1;
  wire [3:0]        _GEN_12 =
    {{fifoValid_q_3}, {fifoValid_q_2}, {fifoValid_q_1}, {fifoValid_q_0}};
  wire [3:0][141:0] _GEN_13 =
    {{fifoData_q_3}, {fifoData_q_2}, {fifoData_q_1}, {fifoData_q_0}};
  wire              _GEN_14 = _GEN_0 ? io_valid_i_i0 : fifoValid_q_0;
  wire              _GEN_15 = _GEN_1 ? io_valid_i_i0 : fifoValid_q_1;
  wire              _GEN_16 = _GEN_2 ? io_valid_i_i0 : fifoValid_q_2;
  wire              _GEN_17 = (&fifo_wPtr_bits) ? io_valid_i_i0 : fifoValid_q_3;
  always @(posedge clock or posedge _fifoValid_q_T_1) begin
    if (_fifoValid_q_T_1) begin
      fifoValid_q_0 <= 1'h0;
      fifoValid_q_1 <= 1'h0;
      fifoValid_q_2 <= 1'h0;
      fifoValid_q_3 <= 1'h0;
    end
    else begin
      fifoValid_q_0 <=
        ~(io_flush_i | io_pop_i & fifo_rPtr_bits == 2'h0)
        & (_GEN
             ? (_GEN_4 ? io_valid_i_i1 : _GEN_14)
             : io_push_i_i0 ? _GEN_14 : _GEN_7 ? io_valid_i_i1 : fifoValid_q_0);
      fifoValid_q_1 <=
        ~(io_flush_i | io_pop_i & fifo_rPtr_bits == 2'h1)
        & (_GEN
             ? (_GEN_5 ? io_valid_i_i1 : _GEN_15)
             : io_push_i_i0 ? _GEN_15 : _GEN_8 ? io_valid_i_i1 : fifoValid_q_1);
      fifoValid_q_2 <=
        ~(io_flush_i | io_pop_i & fifo_rPtr_bits == 2'h2)
        & (_GEN
             ? (_GEN_6 ? io_valid_i_i1 : _GEN_16)
             : io_push_i_i0 ? _GEN_16 : _GEN_9 ? io_valid_i_i1 : fifoValid_q_2);
      fifoValid_q_3 <=
        ~(io_flush_i | _GEN_11)
        & (_GEN
             ? ((&_GEN_3) ? io_valid_i_i1 : _GEN_17)
             : io_push_i_i0 ? _GEN_17 : _GEN_10 ? io_valid_i_i1 : fifoValid_q_3);
    end
  end  
  always @(posedge clock or posedge _fifoData_q_T_1) begin
    if (_fifoData_q_T_1) begin
      fifoData_q_0 <= 142'h0;
      fifoData_q_1 <= 142'h0;
      fifoData_q_2 <= 142'h0;
      fifoData_q_3 <= 142'h0;
    end
    else if (_GEN) begin
      if (_GEN_4)
        fifoData_q_0 <= io_data_i_i1;
      else if (_GEN_0)
        fifoData_q_0 <= io_data_i_i0;
