module ReplaceUnit(
  input        clock,
               reset,
               io_hit_i_0_flag,
  input  [3:0] io_hit_i_0_valid,
  input  [7:0] io_hit_i_0_index,
  input        io_hit_i_1_flag,
  input  [3:0] io_hit_i_1_valid,
  input  [7:0] io_hit_i_1_index,
  input        io_hit_i_2_flag,
  input  [3:0] io_hit_i_2_valid,
  input  [7:0] io_hit_i_2_index,
  input        io_replace_i_flag,
  input  [7:0] io_replace_i_index,
  output       io_replaceWay_o_0,
               io_replaceWay_o_1,
               io_replaceWay_o_2,
               io_replaceWay_o_3
);

  wire [1:0] _u_PLRU_io_replace_way;
  wire [3:0] _GEN = 4'h1 << _u_PLRU_io_replace_way;
  PLRU_1 u_PLRU (
    .clock                      (clock),
    .reset                      (reset),
    .io_hitted_req_0_valid      (io_hit_i_0_flag),
    .io_hitted_req_0_hitted_way
      ({|(io_hit_i_0_valid[3:2]), io_hit_i_0_valid[3] | io_hit_i_0_valid[1]}),
    .io_hitted_req_0_index      (io_hit_i_0_index[4:0]),
    .io_hitted_req_1_valid      (io_hit_i_1_flag),
    .io_hitted_req_1_hitted_way
      ({|(io_hit_i_1_valid[3:2]), io_hit_i_1_valid[3] | io_hit_i_1_valid[1]}),
    .io_hitted_req_1_index      (io_hit_i_1_index[4:0]),
    .io_hitted_req_2_valid      (io_hit_i_2_flag),
    .io_hitted_req_2_hitted_way
      ({|(io_hit_i_2_valid[3:2]), io_hit_i_2_valid[3] | io_hit_i_2_valid[1]}),
    .io_hitted_req_2_index      (io_hit_i_2_index[4:0]),
    .io_missed_req_0_valid      (io_replace_i_flag),
    .io_missed_req_0_index      (io_replace_i_index[4:0]),
    .io_replace_way             (_u_PLRU_io_replace_way)
  );
  assign io_replaceWay_o_0 = _GEN[0];
  assign io_replaceWay_o_1 = _GEN[1];
  assign io_replaceWay_o_2 = _GEN[2];
  assign io_replaceWay_o_3 = _GEN[3];
endmodule


