module axi_flash_axim_arbiter(
  output        io_axi_in_ar_ready,
  input         io_axi_in_ar_valid,
  input  [3:0]  io_axi_in_ar_bits_id,
  input  [63:0] io_axi_in_ar_bits_addr,
  input  [7:0]  io_axi_in_ar_bits_len,
  input  [2:0]  io_axi_in_ar_bits_size,
  input  [1:0]  io_axi_in_ar_bits_burst,
  input         io_axi_in_ar_bits_lock,
  input  [3:0]  io_axi_in_ar_bits_cache,
  input  [2:0]  io_axi_in_ar_bits_prot,
  input         io_axi_in_r_ready,
  output        io_axi_in_r_valid,
  output [3:0]  io_axi_in_r_bits_id,
  output [63:0] io_axi_in_r_bits_data,
  output [1:0]  io_axi_in_r_bits_resp,
  output        io_axi_in_r_bits_last,
  input         io_axi_out1_ar_ready,
  output        io_axi_out1_ar_valid,
  output [3:0]  io_axi_out1_ar_bits_id,
  output [63:0] io_axi_out1_ar_bits_addr,
  output [7:0]  io_axi_out1_ar_bits_len,
  output [2:0]  io_axi_out1_ar_bits_size,
  output [1:0]  io_axi_out1_ar_bits_burst,
  output        io_axi_out1_ar_bits_lock,
  output [3:0]  io_axi_out1_ar_bits_cache,
  output [2:0]  io_axi_out1_ar_bits_prot,
  output        io_axi_out1_r_ready,
  input         io_axi_out1_r_valid,
  input  [3:0]  io_axi_out1_r_bits_id,
  input  [63:0] io_axi_out1_r_bits_data,
  input  [1:0]  io_axi_out1_r_bits_resp,
  input         io_axi_out1_r_bits_last,
                io_axi_out2_ar_ready,
  output        io_axi_out2_ar_valid,
  output [3:0]  io_axi_out2_ar_bits_id,
  output [63:0] io_axi_out2_ar_bits_addr,
  output [7:0]  io_axi_out2_ar_bits_len,
  output [2:0]  io_axi_out2_ar_bits_size,
  output [1:0]  io_axi_out2_ar_bits_burst,
  output        io_axi_out2_ar_bits_lock,
  output [3:0]  io_axi_out2_ar_bits_cache,
  output [2:0]  io_axi_out2_ar_bits_prot,
  output        io_axi_out2_r_ready,
  input         io_axi_out2_r_valid,
  input  [3:0]  io_axi_out2_r_bits_id,
  input  [63:0] io_axi_out2_r_bits_data,
  input  [1:0]  io_axi_out2_r_bits_resp,
  input         io_axi_out2_r_bits_last,
  input  [63:0] io_slave0_base,
                io_slave0_high,
  input         io_arb_sel,
  output        io_r_flag_o
);

  wire       ar_decoded =
    io_axi_in_ar_bits_addr >= io_slave0_base & io_axi_in_ar_bits_addr < io_slave0_high;
  wire [1:0] m_axi_rvalid_combined = {io_axi_out1_r_valid, io_axi_out2_r_valid};
  wire       _GEN = m_axi_rvalid_combined == 2'h0;
  wire       _GEN_0 = m_axi_rvalid_combined == 2'h1;
  wire       _GEN_1 = m_axi_rvalid_combined == 2'h2;
  wire [1:0] temp_sig =
    io_axi_in_r_ready
      ? (io_arb_sel
           ? (_GEN | _GEN_0 ? 2'h1 : _GEN_1 ? 2'h2 : {1'h0, &m_axi_rvalid_combined})
           : _GEN ? 2'h2 : _GEN_0 ? 2'h1 : {_GEN_1 | (&m_axi_rvalid_combined), 1'h0})
      : 2'h0;
  assign io_axi_in_ar_ready = ar_decoded ? io_axi_out1_ar_ready : io_axi_out2_ar_ready;
  assign io_axi_in_r_valid = temp_sig[0] ? io_axi_out2_r_valid : io_axi_out1_r_valid;
  assign io_axi_in_r_bits_id =
    temp_sig[0] ? io_axi_out2_r_bits_id : io_axi_out1_r_bits_id;
  assign io_axi_in_r_bits_data =
    temp_sig[0] ? io_axi_out2_r_bits_data : io_axi_out1_r_bits_data;
  assign io_axi_in_r_bits_resp =
    temp_sig[0] ? io_axi_out2_r_bits_resp : io_axi_out1_r_bits_resp;
  assign io_axi_in_r_bits_last =
    temp_sig[0] ? io_axi_out2_r_bits_last : io_axi_out1_r_bits_last;
  assign io_axi_out1_ar_valid = ar_decoded & io_axi_in_ar_valid;
  assign io_axi_out1_ar_bits_id = ar_decoded ? io_axi_in_ar_bits_id : 4'h0;
  assign io_axi_out1_ar_bits_addr = ar_decoded ? io_axi_in_ar_bits_addr : 64'h0;
  assign io_axi_out1_ar_bits_len = ar_decoded ? io_axi_in_ar_bits_len : 8'h0;
  assign io_axi_out1_ar_bits_size = ar_decoded ? io_axi_in_ar_bits_size : 3'h0;
  assign io_axi_out1_ar_bits_burst = ar_decoded ? io_axi_in_ar_bits_burst : 2'h0;
  assign io_axi_out1_ar_bits_lock = ar_decoded & io_axi_in_ar_bits_lock;
  assign io_axi_out1_ar_bits_cache = ar_decoded ? io_axi_in_ar_bits_cache : 4'h0;
  assign io_axi_out1_ar_bits_prot = ar_decoded ? io_axi_in_ar_bits_prot : 3'h0;
  assign io_axi_out1_r_ready = temp_sig[1];
  assign io_axi_out2_ar_valid = ~ar_decoded & io_axi_in_ar_valid;
  assign io_axi_out2_ar_bits_id = ar_decoded ? 4'h0 : io_axi_in_ar_bits_id;
  assign io_axi_out2_ar_bits_addr = ar_decoded ? 64'h0 : io_axi_in_ar_bits_addr;
  assign io_axi_out2_ar_bits_len = ar_decoded ? 8'h0 : io_axi_in_ar_bits_len;
  assign io_axi_out2_ar_bits_size = ar_decoded ? 3'h0 : io_axi_in_ar_bits_size;
  assign io_axi_out2_ar_bits_burst = ar_decoded ? 2'h0 : io_axi_in_ar_bits_burst;
  assign io_axi_out2_ar_bits_lock = ~ar_decoded & io_axi_in_ar_bits_lock;
  assign io_axi_out2_ar_bits_cache = ar_decoded ? 4'h0 : io_axi_in_ar_bits_cache;
  assign io_axi_out2_ar_bits_prot = ar_decoded ? 3'h0 : io_axi_in_ar_bits_prot;
  assign io_axi_out2_r_ready = temp_sig[0];
  assign io_r_flag_o = temp_sig[0];
endmodule


