module dm_sba_Chisel(
  input         clk_i,
                rst_ni,
  output        master_req_o,
  output [63:0] master_add_o,
  output        master_we_o,
  output [63:0] master_wdata_o,
  output [7:0]  master_be_o,
  input         master_gnt_i,
                master_r_valid_i,
  input  [63:0] master_r_rdata_i,
                sbaddress_i,
  input         sbaddress_write_valid_i,
                sbreadonaddr_i,
  output [63:0] sbaddress_o,
  input         sbautoincrement_i,
  input  [2:0]  sbaccess_i,
  input         sbreadondata_i,
  input  [63:0] sbdata_i,
  input         sbdata_read_valid_i,
                sbdata_write_valid_i,
  output [63:0] sbdata_o,
  output        sbdata_valid_o,
                sbbusy_o,
                sberror_valid_o,
  output [2:0]  sberror_o
);

  wire [2:0] be_idx;
  wire       _state_q_T = ~rst_ni;
  reg  [2:0] state_q;
  wire       _GEN = sbaccess_i == 3'h0;
  wire       _GEN_0 = sbaccess_i == 3'h1;
  wire       _GEN_1 = sbaccess_i == 3'h2;
  wire       _GEN_2 = sbaccess_i == 3'h3;
  wire       _GEN_3 = _GEN_0 | _GEN_1;
  wire       be_mask_0 =
    _GEN ? be_idx == 3'h0 : _GEN_3 ? sbaddress_i[2:1] == 2'h0 : _GEN_2;
  wire       be_mask_1 =
    _GEN ? be_idx == 3'h1 : _GEN_3 ? sbaddress_i[2:1] == 2'h1 : _GEN_2;
  wire       be_mask_2 =
    _GEN ? be_idx == 3'h2 : _GEN_3 ? sbaddress_i[2:1] == 2'h2 : _GEN_2;
  wire       be_mask_3 = _GEN ? be_idx == 3'h3 : _GEN_3 ? (&(sbaddress_i[2:1])) : _GEN_2;
  wire       _GEN_4 = ~_GEN_0 & ~_GEN_1 & _GEN_2;
  wire       be_mask_4 = _GEN ? be_idx == 3'h4 : _GEN_4;
  wire       be_mask_5 = _GEN ? be_idx == 3'h5 : _GEN_4;
  wire       be_mask_6 = _GEN ? be_idx == 3'h6 : _GEN_4;
  wire       be_mask_7 = _GEN ? (&be_idx) : _GEN_4;
  assign be_idx = sbaddress_i[2:0];
  wire       _GEN_5 = state_q == 3'h0;
  wire       _GEN_6 = state_q == 3'h1;
  wire       _GEN_7 = state_q == 3'h2;
  wire       _GEN_8 = state_q == 3'h3;
  wire [7:0] _GEN_9 = {5'h0, sbaccess_i};
  wire       _GEN_10 = master_r_valid_i & sbautoincrement_i;
  wire       _GEN_11 = state_q == 3'h4;
  wire       _GEN_12 = sbaccess_i[2] & (|state_q);
  always @(posedge clk_i or posedge _state_q_T) begin
    if (_state_q_T)
      state_q <= 3'h0;
    else if (_GEN_12)
      state_q <= 3'h0;
    else if (_GEN_5) begin
      if (sbdata_read_valid_i & sbreadondata_i)
        state_q <= 3'h1;
      else if (sbdata_write_valid_i)
        state_q <= 3'h2;
      else if (sbaddress_write_valid_i & sbreadonaddr_i)
        state_q <= 3'h1;
    end
    else if (_GEN_6) begin
      if (master_gnt_i)
        state_q <= 3'h3;
    end
    else if (_GEN_7) begin
      if (master_gnt_i)
        state_q <= 3'h4;
    end
    else if ((_GEN_8 | _GEN_11) & master_r_valid_i)
      state_q <= 3'h0;
  end  
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif  
    initial begin
      if (_state_q_T)
        state_q = 3'h0;
    end  
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif  
  `endif  
  assign master_req_o = ~(_GEN_12 | _GEN_5) & (_GEN_6 | _GEN_7);
  assign master_add_o = sbaddress_i;
  assign master_we_o = ~(_GEN_5 | _GEN_6) & _GEN_7;
  assign master_wdata_o = sbdata_i;
  assign master_be_o =
    _GEN_5
      ? 8'h0
      : _GEN_6
          ? {be_mask_7,
             be_mask_6,
             be_mask_5,
             be_mask_4,
             be_mask_3,
             be_mask_2,
             be_mask_1,
             be_mask_0}
          : _GEN_7
              ? {be_mask_7,
                 be_mask_6,
                 be_mask_5,
                 be_mask_4,
                 be_mask_3,
                 be_mask_2,
                 be_mask_1,
                 be_mask_0}
              : 8'h0;
  assign sbaddress_o =
    _GEN_5 | _GEN_6 | _GEN_7
      ? sbaddress_i
      : _GEN_8
          ? (_GEN_10 ? sbaddress_i + {56'h0, 8'h1 << _GEN_9} : sbaddress_i)
          : _GEN_11 & _GEN_10 ? sbaddress_i + {56'h0, 8'h1 << _GEN_9} : sbaddress_i;
  assign sbdata_o = master_r_rdata_i;
  assign sbdata_valid_o = master_r_valid_i;
  assign sbbusy_o = |state_q;
  assign sberror_valid_o = _GEN_12;
  assign sberror_o = _GEN_12 ? 3'h3 : 3'h0;
endmodule


module csrr(
  input        clock,
               reset,
  input  [5:0] wr_data_i,
  input        wr_en_i,
  output [5:0] rd_data_o
);

  wire       _rdata_q_T_1 = ~reset;
  reg  [5:0] rdata_q;
  always @(posedge clock or posedge _rdata_q_T_1) begin
    if (_rdata_q_T_1)
      rdata_q <= 6'h0;
    else if (wr_en_i)
      rdata_q <= wr_data_i;
  end  
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif  
    initial begin
      if (_rdata_q_T_1)
        rdata_q = 6'h0;
    end  
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif  
  `endif  
  assign rd_data_o = rdata_q;
endmodule


