module chisel_dmi_jtag_tap(
  input  tck_i,
         tms_i,
         trst_ni,
         td_i,
  output td_o,
         tdo_oe_o,
         tck_o,
         trst_no,
         update_o,
         capture_o,
         shift_o,
         tdi_o,
         dtmcs_select_o,
  input  dtmcs_tdo_i,
  output dmi_select_o,
  input  dmi_tdo_i
);

  wire             update_ir;
  wire             _tdo_oe_o_q_T = ~trst_ni;
  reg  [3:0]       tap_state_q;
  reg  [4:0]       jtag_ir_shift_q;
  reg  [4:0]       jtag_ir_q;
  wire [4:0]       jtag_ir_d = update_ir ? jtag_ir_shift_q : jtag_ir_q;
  wire             _GEN = tap_state_q == 4'h0;
  reg  [31:0]      idcode_q;
  reg              bypass_q;
  wire             _GEN_0 = jtag_ir_q == 5'h0;
  wire             _GEN_1 = jtag_ir_q == 5'h1;
  wire             idcode_select = ~_GEN_0 & _GEN_1;
  wire             _GEN_2 = jtag_ir_q == 5'h10;
  wire             _GEN_3 = jtag_ir_q == 5'h11;
  wire             bypass_select = _GEN_0 | ~(_GEN_1 | _GEN_2 | _GEN_3) & (&jtag_ir_q);
  reg              td_o_q;
  reg              tdo_oe_o_q;
  wire             tck_n = ~tck_i;
  wire             _GEN_4 = tap_state_q == 4'h1;
  wire             _GEN_5 = tap_state_q == 4'h2;
  wire             _GEN_6 = tap_state_q == 4'h3;
  wire             capture_dr = ~(_GEN | _GEN_4 | _GEN_5) & _GEN_6;
  wire             _GEN_7 = tap_state_q == 4'h4;
  wire             shift_dr = ~(_GEN | _GEN_4 | _GEN_5 | _GEN_6) & _GEN_7;
  wire             _GEN_8 = tap_state_q == 4'h5;
  wire             _GEN_9 = tap_state_q == 4'h6;
  wire             _GEN_10 = tap_state_q == 4'h7;
  wire             _GEN_11 = tap_state_q == 4'h8;
  wire             _GEN_12 = tap_state_q == 4'h9;
  wire             _GEN_13 = tap_state_q == 4'hA;
  wire             _GEN_14 = tap_state_q == 4'hB;
  wire             shift_ir =
    ~(_GEN | _GEN_4 | _GEN_5 | _GEN_6 | _GEN_7 | _GEN_8 | _GEN_9 | _GEN_10 | _GEN_11
      | _GEN_12 | _GEN_13) & _GEN_14;
  assign update_ir =
    ~(_GEN | _GEN_4 | _GEN_5 | _GEN_6 | _GEN_7 | _GEN_8 | _GEN_9 | _GEN_10 | _GEN_11
      | _GEN_12 | _GEN_13 | _GEN_14 | tap_state_q == 4'hC | tap_state_q == 4'hD
      | tap_state_q == 4'hE) & (&tap_state_q);
  wire [15:0][3:0] _GEN_15 =
    {{tms_i ? 4'h2 : 4'h1},
     {{1'h1, tms_i, 2'h3}},
     {tms_i ? 4'hE : 4'hD},
     {{2'h3, tms_i, 1'h1}},
     {tms_i ? 4'hC : 4'hB},
     {tms_i ? 4'hC : 4'hB},
     {tms_i ? 4'h0 : 4'hA},
     {tms_i ? 4'h2 : 4'h1},
     {tms_i ? 4'h8 : 4'h4},
     {{3'h3, tms_i}},
     {tms_i ? 4'h8 : 4'h6},
     {{3'h2, tms_i}},
     {{3'h2, tms_i}},
     {tms_i ? 4'h9 : 4'h3},
     {tms_i ? 4'h2 : 4'h1},
     {{3'h0, ~tms_i}}};
  always @(posedge tck_i or posedge _tdo_oe_o_q_T) begin
    if (_tdo_oe_o_q_T) begin
      tap_state_q <= 4'h0;
      jtag_ir_shift_q <= 5'h0;
      jtag_ir_q <= 5'h1;
      idcode_q <= 32'h14535FFD;
      bypass_q <= 1'h0;
    end
    else begin
      tap_state_q <= _GEN_15[tap_state_q];
      if (~(_GEN | _GEN_4 | _GEN_5 | _GEN_6 | _GEN_7 | _GEN_8 | _GEN_9 | _GEN_10 | _GEN_11
            | _GEN_12) & _GEN_13)
        jtag_ir_shift_q <= 5'h1;
      else if (shift_ir)
        jtag_ir_shift_q <= {td_i, jtag_ir_shift_q[4:1]};
      jtag_ir_q <= _GEN ? 5'h1 : jtag_ir_d;
      if (shift_dr & idcode_select)
        idcode_q <= {td_i, idcode_q[31:1]};
      else if (capture_dr & idcode_select)
        idcode_q <= 32'h14535FFD;
      bypass_q <=
        shift_dr & bypass_select ? td_i : ~(capture_dr & bypass_select) & bypass_q;
    end
  end  
  always @(posedge tck_n or posedge _tdo_oe_o_q_T) begin
    if (_tdo_oe_o_q_T) begin
      td_o_q <= 1'h0;
      tdo_oe_o_q <= 1'h0;
    end
    else begin
      td_o_q <=
        shift_ir
          ? jtag_ir_shift_q[0]
          : _GEN_1 ? idcode_q[0] : _GEN_2 ? dtmcs_tdo_i : _GEN_3 ? dmi_tdo_i : bypass_q;
      tdo_oe_o_q <= shift_ir | shift_dr;
    end
  end  
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif  
    initial begin
      if (_tdo_oe_o_q_T) begin
        tap_state_q = 4'h0;
        jtag_ir_shift_q = 5'h0;
        jtag_ir_q = 5'h1;
        idcode_q = 32'h14535FFD;
        bypass_q = 1'h0;
        td_o_q = 1'h0;
        tdo_oe_o_q = 1'h0;
      end
    end  
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif  
  `endif  
  assign td_o = td_o_q;
  assign tdo_oe_o = tdo_oe_o_q;
  assign tck_o = tck_i;
  assign trst_no = trst_ni;
  assign update_o =
    ~(_GEN | _GEN_4 | _GEN_5 | _GEN_6 | _GEN_7 | _GEN_8 | _GEN_9 | _GEN_10) & _GEN_11;
  assign capture_o = capture_dr;
  assign shift_o = shift_dr;
  assign tdi_o = td_i;
  assign dtmcs_select_o = ~(_GEN_0 | _GEN_1) & _GEN_2;
  assign dmi_select_o = ~(_GEN_0 | _GEN_1 | _GEN_2) & _GEN_3;
endmodule


