  );
  LsuTcmRangeCheck u_lsuDtcmCheck (
    .io_config_i_startAddr (io_config_i_dtcm_startAddr),
    .io_config_i_size      (io_config_i_dtcm_size),
    .io_addr_i             (io_lsu_req_i_address),
    .io_in_range_o         (_u_lsuDtcmCheck_io_in_range_o),
