  );
  LsuConfigRangeCheck_7 u_lsuFlashCheck (
    .io_config_i_startAddr (io_config_i_flash_startAddr),
    .io_config_i_size      (io_config_i_flash_size),
    .io_addr_i             (io_lsu_req_i_address),
