  );
  LsuConfigRangeCheck u_LsuClicCheck (
    .io_config_i_startAddr ({io_config_i_llpp_startAddr[51:7], 7'h50}),
    .io_config_i_size      (5'h8),
    .io_addr_i             (io_lsu_req_i_address),
    .io_in_range_o         (_u_LsuClicCheck_io_in_range_o)
  );
  LsuConfigRangeCheck u_LsuDebugCheck (
    .io_config_i_startAddr ({io_config_i_llpp_startAddr[51:7], 7'h40}),
