  always @(posedge clock or posedge _rdata_q_T_1) begin
    if (_rdata_q_T_1)
      rdata_q <= 4'hF;
    else if (wr_en_i)
      rdata_q <= wr_data_i;
  end  
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif  
    initial begin
      if (_rdata_q_T_1)
        rdata_q = 4'hF;
    end  
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif  
  `endif  
  assign rd_data_o = rdata_q;
endmodule


module CSA3_2(
  input  [9:0] io_in_0,
               io_in_1,
               io_in_2,
  output [9:0] io_out_0,
               io_out_1
);

  wire a_xor_b = io_in_0[0] ^ io_in_1[0];
  wire a_xor_b_1 = io_in_0[1] ^ io_in_1[1];
  wire a_xor_b_2 = io_in_0[2] ^ io_in_1[2];
  wire a_xor_b_3 = io_in_0[3] ^ io_in_1[3];
  wire a_xor_b_4 = io_in_0[4] ^ io_in_1[4];
  wire a_xor_b_5 = io_in_0[5] ^ io_in_1[5];
  wire a_xor_b_6 = io_in_0[6] ^ io_in_1[6];
  wire a_xor_b_7 = io_in_0[7] ^ io_in_1[7];
  wire a_xor_b_8 = io_in_0[8] ^ io_in_1[8];
  wire a_xor_b_9 = io_in_0[9] ^ io_in_1[9];
  assign io_out_0 =
    {a_xor_b_9 ^ io_in_2[9],
     a_xor_b_8 ^ io_in_2[8],
     a_xor_b_7 ^ io_in_2[7],
     a_xor_b_6 ^ io_in_2[6],
     a_xor_b_5 ^ io_in_2[5],
     a_xor_b_4 ^ io_in_2[4],
     a_xor_b_3 ^ io_in_2[3],
     a_xor_b_2 ^ io_in_2[2],
     a_xor_b_1 ^ io_in_2[1],
     a_xor_b ^ io_in_2[0]};
  assign io_out_1 =
    {io_in_0[9] & io_in_1[9] | a_xor_b_9 & io_in_2[9],
     io_in_0[8] & io_in_1[8] | a_xor_b_8 & io_in_2[8],
     io_in_0[7] & io_in_1[7] | a_xor_b_7 & io_in_2[7],
     io_in_0[6] & io_in_1[6] | a_xor_b_6 & io_in_2[6],
     io_in_0[5] & io_in_1[5] | a_xor_b_5 & io_in_2[5],
     io_in_0[4] & io_in_1[4] | a_xor_b_4 & io_in_2[4],
     io_in_0[3] & io_in_1[3] | a_xor_b_3 & io_in_2[3],
     io_in_0[2] & io_in_1[2] | a_xor_b_2 & io_in_2[2],
     io_in_0[1] & io_in_1[1] | a_xor_b_1 & io_in_2[1],
     io_in_0[0] & io_in_1[0] | a_xor_b & io_in_2[0]};
endmodule


module chisel_dmi_jtag(
  input         clk_i,
                rst_ni,
  output        dmi_rst_no,
  output [40:0] dmi_req_o,
  output        dmi_req_valid_o,
  input         dmi_req_ready_i,
  input  [33:0] dmi_resp_i,
  output        dmi_resp_ready_o,
  input         dmi_resp_valid_i,
                tck_i,
                tms_i,
                trst_ni,
                td_i,
  output        td_o,
                tdo_oe_o
);

  wire        _i_dmi_cdc_jtag_dmi_ready_o;
  wire [33:0] _i_dmi_cdc_jtag_dmi_resp_o;
  wire        _i_dmi_cdc_jtag_dmi_valid_o;
  wire        _i_dmi_jtag_tap_tck_o;
  wire        _i_dmi_jtag_tap_trst_no;
  wire        _i_dmi_jtag_tap_update_o;
  wire        _i_dmi_jtag_tap_capture_o;
  wire        _i_dmi_jtag_tap_shift_o;
  wire        _i_dmi_jtag_tap_tdi_o;
  wire        _i_dmi_jtag_tap_dtmcs_select_o;
  wire        _i_dmi_jtag_tap_dmi_select_o;
  wire        dmi_resp_ready = 1'h1;
  wire        _data_q_T = ~_i_dmi_jtag_tap_trst_no;
  reg  [31:0] dtmcs_q;
  reg  [1:0]  error_q;
  reg  [2:0]  state_q;
  reg  [40:0] dr_q;
  reg  [6:0]  address_q;
  reg  [31:0] data_q;
  wire        _dmi_req_op_T = state_q == 3'h3;
  wire        _GEN = error_q == 2'h0;
  wire        _GEN_0 = state_q == 3'h1;
  wire        _GEN_1 = state_q == 3'h2;
  wire        error_dmi_busy =
    _i_dmi_jtag_tap_capture_o & (_GEN_0 | _GEN_1) | _i_dmi_jtag_tap_update_o & (|state_q);
  wire [40:0] dr_d =
    _i_dmi_jtag_tap_shift_o & _i_dmi_jtag_tap_dmi_select_o
      ? {_i_dmi_jtag_tap_tdi_o, dr_q[40:1]}
      : _i_dmi_jtag_tap_capture_o & _i_dmi_jtag_tap_dmi_select_o
          ? (_GEN & ~error_dmi_busy
               ? {address_q, data_q, 2'h0}
               : (&error_q) | error_dmi_busy ? {address_q, data_q, 2'h3} : dr_q)
          : dr_q;
  wire        _GEN_2 = _i_dmi_jtag_tap_capture_o & _i_dmi_jtag_tap_dtmcs_select_o;
  wire        _GEN_3 = _i_dmi_jtag_tap_shift_o & _i_dmi_jtag_tap_dtmcs_select_o;
  wire        _GEN_4 = _i_dmi_jtag_tap_dmi_select_o & _i_dmi_jtag_tap_update_o & _GEN;
  always @(posedge _i_dmi_jtag_tap_tck_o or posedge _data_q_T) begin
    if (_data_q_T) begin
      dtmcs_q <= 32'h0;
      error_q <= 2'h0;
      state_q <= 3'h0;
      dr_q <= 41'h0;
      address_q <= 7'h0;
      data_q <= 32'h0;
    end
    else begin
      dtmcs_q <=
        {_GEN_3
           ? {_i_dmi_jtag_tap_tdi_o, dtmcs_q[31:19]}
           : _GEN_2 ? 14'h0 : dtmcs_q[31:18],
         _GEN_3 ? dtmcs_q[18] : ~_GEN_2 & dtmcs_q[17],
         _GEN_3 ? dtmcs_q[17] : ~_GEN_2 & dtmcs_q[16],
         _GEN_3 ? dtmcs_q[16] : ~_GEN_2 & dtmcs_q[15],
         _GEN_3 ? dtmcs_q[15:13] : _GEN_2 ? 3'h1 : dtmcs_q[14:12],
         _GEN_3 ? dtmcs_q[12:11] : _GEN_2 ? error_q : dtmcs_q[11:10],
         _GEN_3 ? dtmcs_q[10:5] : _GEN_2 ? 6'h7 : dtmcs_q[9:4],
         _GEN_3 ? dtmcs_q[4:1] : _GEN_2 ? 4'h1 : dtmcs_q[3:0]};
      if (_i_dmi_jtag_tap_update_o & dtmcs_q[16] & _i_dmi_jtag_tap_dtmcs_select_o)
        error_q <= 2'h0;
      else if (error_dmi_busy)
        error_q <= 2'h3;
      if (|state_q) begin
        if (_GEN_0) begin
          if (_i_dmi_cdc_jtag_dmi_ready_o)
            state_q <= 3'h2;
          else if (_i_dmi_cdc_jtag_dmi_valid_o)
            state_q <= 3'h0;
        end
        else if (_GEN_1 | ~(_dmi_req_op_T & _i_dmi_cdc_jtag_dmi_ready_o)) begin
          if (_i_dmi_cdc_jtag_dmi_valid_o)
            state_q <= 3'h0;
        end
        else
          state_q <= 3'h4;
        if (_GEN_0 | ~(_GEN_1 & _i_dmi_cdc_jtag_dmi_valid_o)) begin
        end
        else
          data_q <= _i_dmi_cdc_jtag_dmi_resp_o[33:2];
      end
      else if (_GEN_4) begin
        if (dr_q[1:0] == 2'h1)
          state_q <= 3'h1;
        else if (dr_q[1:0] == 2'h2)
          state_q <= 3'h3;
        else if (_i_dmi_cdc_jtag_dmi_valid_o)
          state_q <= 3'h0;
        data_q <= dr_q[33:2];
      end
      else if (_i_dmi_cdc_jtag_dmi_valid_o)
        state_q <= 3'h0;
      dr_q <= dr_d;
      if (~(|state_q) & _GEN_4)
        address_q <= dr_q[40:34];
    end
  end  
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif  
    initial begin
      if (_data_q_T) begin
        dtmcs_q = 32'h0;
        error_q = 2'h0;
        state_q = 3'h0;
        dr_q = 41'h0;
        address_q = 7'h0;
        data_q = 32'h0;
      end
    end  
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif  
  `endif  
  chisel_dmi_jtag_tap i_dmi_jtag_tap (
    .tck_i          (tck_i),
    .tms_i          (tms_i),
    .trst_ni        (trst_ni),
    .td_i           (td_i),
    .td_o           (td_o),
    .tdo_oe_o       (tdo_oe_o),
    .tck_o          (_i_dmi_jtag_tap_tck_o),
    .trst_no        (_i_dmi_jtag_tap_trst_no),
    .update_o       (_i_dmi_jtag_tap_update_o),
    .capture_o      (_i_dmi_jtag_tap_capture_o),
    .shift_o        (_i_dmi_jtag_tap_shift_o),
    .tdi_o          (_i_dmi_jtag_tap_tdi_o),
    .dtmcs_select_o (_i_dmi_jtag_tap_dtmcs_select_o),
    .dtmcs_tdo_i    (dtmcs_q[0]),
    .dmi_select_o   (_i_dmi_jtag_tap_dmi_select_o),
    .dmi_tdo_i      (dr_q[0])
  );
  chisel_dmi_cdc i_dmi_cdc (
    .tck_i            (_i_dmi_jtag_tap_tck_o),
    .trst_ni          (_i_dmi_jtag_tap_trst_no),
    .jtag_dmi_req_i   ({address_q, _dmi_req_op_T ? 2'h2 : 2'h1, data_q}),
    .jtag_dmi_ready_o (_i_dmi_cdc_jtag_dmi_ready_o),
    .jtag_dmi_valid_i ((|state_q) & (_GEN_0 | ~_GEN_1 & _dmi_req_op_T)),
    .jtag_dmi_resp_o  (_i_dmi_cdc_jtag_dmi_resp_o),
    .jtag_dmi_valid_o (_i_dmi_cdc_jtag_dmi_valid_o),
    .jtag_dmi_ready_i (dmi_resp_ready),
    .clk_i            (clk_i),
    .rst_ni           (rst_ni),
    .core_dmi_req_o   (dmi_req_o),
    .core_dmi_valid_o (dmi_req_valid_o),
    .core_dmi_ready_i (dmi_req_ready_i),
    .core_dmi_resp_i  (dmi_resp_i),
    .core_dmi_ready_o (dmi_resp_ready_o),
    .core_dmi_valid_i (dmi_resp_valid_i)
  );
  assign dmi_rst_no = rst_ni;
endmodule


module FIFO_interface_icache(
  input         clock,
                reset,
                io_push_i,
  input  [63:0] io_data_i,
  input         io_pop_i,
  output [63:0] io_data_o,
  output        io_empty_o
);

  wire        io_full_o;
  wire        _slot_T_1 = ~reset;
  reg  [63:0] slot_0;
  reg  [63:0] slot_1;
  wire        _push_point_T_1 = ~reset;
  reg  [1:0]  push_point;
  wire        _pop_point_T_1 = ~reset;
  reg  [1:0]  pop_point;
  wire        _push_add1_point_T_1 = ~reset;
  reg  [1:0]  push_add1_point;
  wire        _GEN = io_push_i & ~io_full_o;
  wire        io_empty_o_0 =
    push_point[0] == pop_point[0] & push_point[1] == pop_point[1];
  assign io_full_o = push_point[0] == pop_point[0] & push_point[1] != pop_point[1];
  always @(posedge clock or posedge _slot_T_1) begin
    if (_slot_T_1) begin
      slot_0 <= 64'h0;
      slot_1 <= 64'h0;
    end
    else begin
      if (_GEN & ~(push_point[0]))
        slot_0 <= io_data_i;
      else if (_GEN & ~(push_add1_point[0]))
        slot_0 <= io_data_i + 64'h20;
      if (_GEN & push_point[0])
        slot_1 <= io_data_i;
      else if (_GEN & push_add1_point[0])
        slot_1 <= io_data_i + 64'h20;
    end
  end  
  always @(posedge clock or posedge _push_point_T_1) begin
    if (_push_point_T_1)
      push_point <= 2'h0;
    else if (_GEN)
      push_point <= push_point - 2'h2;
  end  
  always @(posedge clock or posedge _pop_point_T_1) begin
    if (_pop_point_T_1)
      pop_point <= 2'h0;
    else if (io_pop_i & ~io_empty_o_0)
      pop_point <= pop_point + 2'h1;
  end  
  always @(posedge clock or posedge _push_add1_point_T_1) begin
    if (_push_add1_point_T_1)
      push_add1_point <= 2'h1;
    else if (_GEN)
      push_add1_point <= push_add1_point - 2'h2;
  end  
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif  
    initial begin
      if (_slot_T_1) begin
        slot_0 = 64'h0;
        slot_1 = 64'h0;
      end
      if (_push_point_T_1)
        push_point = 2'h0;
      if (_pop_point_T_1)
        pop_point = 2'h0;
      if (_push_add1_point_T_1)
        push_add1_point = 2'h1;
    end  
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif  
  `endif  
  assign io_data_o = pop_point[0] ? slot_1 : slot_0;
  assign io_empty_o = io_empty_o_0;
endmodule


module axim_interface_w(
  input         clock,
