      : pp_ff_hist;
  assign io_alu_out_bits_predict_toffset = pp_ff_toffset;
  assign io_alu_out_bits_predict_index = pp_ff_index;
  assign io_alu_out_bits_predict_bank = pp_ff_bank;
  assign io_alu_out_bits_predict_valid = pp_ff_valid;
  assign io_alu_out_bits_predict_br_error = pp_ff_br_error;
  assign io_alu_out_bits_predict_br_start_error = pp_ff_br_start_error;
