module Mul(
  input         clock,
                reset,
                io_flushIn,
                io_mulIn_valid,
  input  [63:0] io_mulIn_bits_rs1,
                io_mulIn_bits_rs2,
  input  [3:0]  io_mulIn_bits_tag,
  input         io_mulIn_bits_pkg_rs1_sign,
                io_mulIn_bits_pkg_rs2_sign,
                io_mulIn_bits_pkg_low,
                io_mulIn_bits_pkg_word,
  output        io_mulOut_valid,
  output [3:0]  io_mulOut_bits_tag,
  output [63:0] io_mulOut_bits_result
);

  wire         _valid_e2_T_1 = ~reset;
  reg          valid_e2;
  reg          low_e2;
  reg          word_e2;
  reg  [64:0]  a_ff_e2;
  reg  [64:0]  b_ff_e2;
  reg  [3:0]   tag_e2;
  wire         _valid_e3_T_1 = ~reset;
  reg          valid_e3;
  reg          low_e3;
  reg  [129:0] prod_e3;
  reg  [3:0]   tag_e3;
  reg          word_e3;
  wire [63:0]  raw_result = low_e3 ? prod_e3[63:0] : prod_e3[127:64];
  always @(posedge clock or posedge _valid_e2_T_1) begin
    if (_valid_e2_T_1)
      valid_e2 <= 1'h0;
    else
      valid_e2 <= ~io_flushIn & io_mulIn_valid;
  end  
  wire [63:0]  a_e1 =
    io_mulIn_bits_pkg_word
      ? {{32{io_mulIn_bits_rs1[31]}}, io_mulIn_bits_rs1[31:0]}
      : io_mulIn_bits_rs1;
  wire [63:0]  b_e1 =
    io_mulIn_bits_pkg_word
      ? {{32{io_mulIn_bits_rs2[31]}}, io_mulIn_bits_rs2[31:0]}
      : io_mulIn_bits_rs2;
  always @(posedge clock) begin
    low_e2 <= io_mulIn_bits_pkg_low;
    word_e2 <= io_mulIn_bits_pkg_word;
    a_ff_e2 <= {(io_mulIn_bits_pkg_rs1_sign | io_mulIn_bits_pkg_word) & a_e1[63], a_e1};
    b_ff_e2 <= {(io_mulIn_bits_pkg_rs2_sign | io_mulIn_bits_pkg_word) & b_e1[63], b_e1};
    tag_e2 <= io_mulIn_bits_tag;
    low_e3 <= low_e2;
    prod_e3 <= {{65{a_ff_e2[64]}}, a_ff_e2} * {{65{b_ff_e2[64]}}, b_ff_e2};
    tag_e3 <= tag_e2;
    word_e3 <= word_e2;
  end  
  always @(posedge clock or posedge _valid_e3_T_1) begin
    if (_valid_e3_T_1)
      valid_e3 <= 1'h0;
    else
      valid_e3 <= ~io_flushIn & valid_e2;
  end  
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif  
    initial begin
      if (_valid_e2_T_1)
        valid_e2 = 1'h0;
      if (_valid_e3_T_1)
        valid_e3 = 1'h0;
    end  
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif  
  `endif  
  assign io_mulOut_valid = valid_e3;
  assign io_mulOut_bits_tag = tag_e3;
  assign io_mulOut_bits_result =
    word_e3 ? {{32{raw_result[31]}}, raw_result[31:0]} : raw_result;
endmodule


