module FIFO_interface_1w1r_2(
  input        clock,
               reset,
               io_push_i,
  input  [3:0] io_data_i,
  input        io_pop_i,
  output [3:0] io_data_o
);

  wire            io_full_o;
  wire            _slot_T_1 = ~reset;
  reg  [3:0]      slot_0;
  reg  [3:0]      slot_1;
  reg  [3:0]      slot_2;
  reg  [3:0]      slot_3;
  reg  [3:0]      slot_4;
  reg  [3:0]      slot_5;
  reg  [3:0]      slot_6;
  reg  [3:0]      slot_7;
  wire            _push_point_T_1 = ~reset;
  reg  [3:0]      push_point;
  wire            _pop_point_T_1 = ~reset;
  reg  [3:0]      pop_point;
