  reg  [1:0]  s2Req_privMode;
  reg  [2:0]  s2Req_missId;
  reg  [7:0]  s2Req_epoch;
  reg  [1:0]  s2Req_source;
  reg         s2OffMode;
  wire        s2FlushActive =
    s2Valid & (s2Req_source == 2'h1 ? io_flush_itlb_i : io_flush_dtlb_i);
  assign s2Ready = ~s2Valid | s2Fire | s2FlushActive;
