  assign s2Fire = s2Valid & ~s2FlushActive & s3Ready & ~replayPending_q;
  assign s3Ready = ~s3Valid | s3Fire | s3FlushActive;
  wire        tlbHitVecS3_0 =
    s3MetaResp_0_valid & ~s3TagUncorrectable_0 & ~s3DataUncorrectable_0
    & s3TagResp_0_tag == s3Req_vpn
    & (s3DataResp_0_asid == s3Req_asid | s3DataResp_0_perm_global);
  wire        tlbHitVecS3_1 =
    s3MetaResp_1_valid & ~s3TagUncorrectable_1 & ~s3DataUncorrectable_1
    & s3TagResp_1_tag == s3Req_vpn
    & (s3DataResp_1_asid == s3Req_asid | s3DataResp_1_perm_global);
  wire        tlbHitVecS3_2 =
    s3MetaResp_2_valid & ~s3TagUncorrectable_2 & ~s3DataUncorrectable_2
    & s3TagResp_2_tag == s3Req_vpn
    & (s3DataResp_2_asid == s3Req_asid | s3DataResp_2_perm_global);
  wire        tlbHitVecS3_3 =
    s3MetaResp_3_valid & ~s3TagUncorrectable_3 & ~s3DataUncorrectable_3
    & s3TagResp_3_tag == s3Req_vpn
    & (s3DataResp_3_asid == s3Req_asid | s3DataResp_3_perm_global);
  wire        tlbMatchHitS3 =
    tlbHitVecS3_0 | tlbHitVecS3_1 | tlbHitVecS3_2 | tlbHitVecS3_3;
  wire        tlbDataSelectS3_perm_accessed =
    tlbHitVecS3_0 & s3DataResp_0_perm_accessed | tlbHitVecS3_1
    & s3DataResp_1_perm_accessed | tlbHitVecS3_2 & s3DataResp_2_perm_accessed
    | tlbHitVecS3_3 & s3DataResp_3_perm_accessed;
  wire        tlbDataSelectS3_perm_dirty =
    tlbHitVecS3_0 & s3DataResp_0_perm_dirty | tlbHitVecS3_1 & s3DataResp_1_perm_dirty
    | tlbHitVecS3_2 & s3DataResp_2_perm_dirty | tlbHitVecS3_3 & s3DataResp_3_perm_dirty;
  wire        tlbDataSelectS3_perm_user =
    tlbHitVecS3_0 & s3DataResp_0_perm_user | tlbHitVecS3_1 & s3DataResp_1_perm_user
    | tlbHitVecS3_2 & s3DataResp_2_perm_user | tlbHitVecS3_3 & s3DataResp_3_perm_user;
  wire        tlbDataSelectS3_perm_exec =
    tlbHitVecS3_0 & s3DataResp_0_perm_exec | tlbHitVecS3_1 & s3DataResp_1_perm_exec
    | tlbHitVecS3_2 & s3DataResp_2_perm_exec | tlbHitVecS3_3 & s3DataResp_3_perm_exec;
  wire        tlbDataSelectS3_perm_write =
    tlbHitVecS3_0 & s3DataResp_0_perm_write | tlbHitVecS3_1 & s3DataResp_1_perm_write
    | tlbHitVecS3_2 & s3DataResp_2_perm_write | tlbHitVecS3_3 & s3DataResp_3_perm_write;
  wire        tlbDataSelectS3_perm_read =
    tlbHitVecS3_0 & s3DataResp_0_perm_read | tlbHitVecS3_1 & s3DataResp_1_perm_read
    | tlbHitVecS3_2 & s3DataResp_2_perm_read | tlbHitVecS3_3 & s3DataResp_3_perm_read;
  wire        _tlbPermCheckS3_adAllowed_T = s3Req_cmd == 2'h1;
  wire        tlbPermCheckS3 =
    (s3Req_privMode == 2'h0
       ? tlbDataSelectS3_perm_user
       : ~(s3Req_privMode == 2'h1 & tlbDataSelectS3_perm_user & ~io_sum_i))
    & (s3Req_cmd == 2'h2
       & (tlbDataSelectS3_perm_read | io_mxr_i & tlbDataSelectS3_perm_exec)
       | _tlbPermCheckS3_adAllowed_T & tlbDataSelectS3_perm_write | s3Req_cmd == 2'h0
       & tlbDataSelectS3_perm_exec | (&s3Req_cmd) & tlbDataSelectS3_perm_read
       & tlbDataSelectS3_perm_write) & tlbDataSelectS3_perm_accessed
    & (~(_tlbPermCheckS3_adAllowed_T | (&s3Req_cmd)) | tlbDataSelectS3_perm_dirty);
  wire        hitRespValid = s3Valid & tlbMatchHitS3;
  wire        missCandidate = s3Valid & ~tlbMatchHitS3 & ~s3OffMode;
  reg         replayAfterRefill_q;
  assign replayReq =
    missCandidate
    & (io_prefetchMatch_i | io_refill_i | replayAfterRefill_q | ~io_miss_o_ready)
