  wire [2:0]  io_tagRd_req_o_bits_0 =
    replayReq ? s3Req_vpn[2:0] : io_l2Tlb_req_i_bits_vpn[2:0];
  wire        io_l2Tlb_resp_o_valid_0 =
    (s3Valid & s3OffMode | hitRespValid) & ~s3FlushActive;
  wire        io_miss_o_valid_0 =
    missCandidate & ~io_prefetchMatch_i & ~io_refill_i & ~replayAfterRefill_q
