      s3Req_vpn <= 44'h0;
      s3Req_asid <= 16'h0;
      s3Req_cmd <= 2'h0;
      s3Req_privMode <= 2'h0;
      s3Req_missId <= 3'h0;
      s3Req_epoch <= 8'h0;
      s3Req_source <= 2'h0;
