    else begin
      s2Valid <= s1Fire | ~(s2FlushActive | s2Fire) & s2Valid;
      if (s1Fire) begin
        s2Req_vpn <= io_l2Tlb_req_i_bits_vpn;
        s2Req_asid <= io_l2Tlb_req_i_bits_asid;
        s2Req_cmd <= io_l2Tlb_req_i_bits_cmd;
        s2Req_privMode <= io_l2Tlb_req_i_bits_privMode;
        s2Req_missId <= io_l2Tlb_req_i_bits_missId;
        s2Req_epoch <= io_l2Tlb_req_i_bits_epoch;
        s2Req_source <= io_l2Tlb_req_i_bits_source;
        s2OffMode <= io_satpMode_i == 4'h0;
