        s3Req_asid <= s2Req_asid;
        s3Req_cmd <= s2Req_cmd;
        s3Req_privMode <= s2Req_privMode;
        s3Req_missId <= s2Req_missId;
        s3Req_epoch <= s2Req_epoch;
        s3Req_source <= s2Req_source;
