      s3DataResp_1_perm_write <= io_dataRd_resp_i_1_perm_write;
      s3DataResp_1_perm_exec <= io_dataRd_resp_i_1_perm_exec;
      s3DataResp_1_perm_user <= io_dataRd_resp_i_1_perm_user;
