      s3DataResp_3_perm_accessed <= io_dataRd_resp_i_3_perm_accessed;
      s3DataResp_3_level <= io_dataRd_resp_i_3_level;
      s3DataResp_3_leaf <= io_dataRd_resp_i_3_leaf;
      s3TagUncorrectable_0 <= io_tagRd_uncorrectable_i_0;
      s3TagUncorrectable_1 <= io_tagRd_uncorrectable_i_1;
