  assign io_l2Tlb_resp_o_bits_perm_exec = ~s3OffMode & tlbDataSelectS3_perm_exec;
  assign io_l2Tlb_resp_o_bits_perm_user = ~s3OffMode & tlbDataSelectS3_perm_user;
  assign io_l2Tlb_resp_o_bits_perm_global =
