  assign io_l2Tlb_resp_o_bits_perm_dirty = ~s3OffMode & tlbDataSelectS3_perm_dirty;
  assign io_l2Tlb_resp_o_bits_perm_accessed = ~s3OffMode & tlbDataSelectS3_perm_accessed;
  assign io_l2Tlb_resp_o_bits_level =
