        | (tlbHitVecS3_1 ? s3DataResp_1_level : 2'h0)
        | (tlbHitVecS3_2 ? s3DataResp_2_level : 2'h0)
        | (tlbHitVecS3_3 ? s3DataResp_3_level : 2'h0);
  assign io_l2Tlb_resp_o_bits_leaf =
    s3OffMode | tlbHitVecS3_0 & s3DataResp_0_leaf | tlbHitVecS3_1 & s3DataResp_1_leaf
    | tlbHitVecS3_2 & s3DataResp_2_leaf | tlbHitVecS3_3 & s3DataResp_3_leaf;
  assign io_l2Tlb_resp_o_bits_err = ~s3OffMode & ~tlbPermCheckS3;
  assign io_l2Tlb_resp_o_bits_cause = {~(s3OffMode | tlbPermCheckS3), 1'h0};
  assign io_l2Tlb_resp_o_bits_missId = s3Req_missId;
  assign io_l2Tlb_resp_o_bits_epoch = s3Req_epoch;
  assign io_l2Tlb_resp_o_bits_source = s3Req_source;
  assign io_tagRd_req_o_valid = arrayReqValid;
  assign io_tagRd_req_o_bits = io_tagRd_req_o_bits_0;
  assign io_metaRd_req_o_valid = arrayReqValid;
  assign io_metaRd_req_o_bits = io_tagRd_req_o_bits_0;
  assign io_dataRd_req_o_valid = arrayReqValid;
  assign io_dataRd_req_o_bits = io_tagRd_req_o_bits_0;
  assign io_miss_o_valid = io_miss_o_valid_0;
  assign io_miss_o_bits_vpn = s3Req_vpn;
  assign io_miss_o_bits_asid = s3Req_asid;
  assign io_miss_o_bits_cmd = s3Req_cmd;
  assign io_miss_o_bits_privMode = s3Req_privMode;
  assign io_miss_o_bits_missId = s3Req_missId;
  assign io_miss_o_bits_epoch = s3Req_epoch;
  assign io_miss_o_bits_source = s3Req_source;
  assign io_hit_o_valid = hitRespValid & ~s3OffMode;
  assign io_hit_o_setIdx = s3Req_vpn[2:0];
  assign io_hit_o_wayIdx =
    {|{tlbHitVecS3_3, tlbHitVecS3_2}, tlbHitVecS3_3 | tlbHitVecS3_1};
endmodule


