module FIFO_interface_1w1r_13(
  input         clock,
                reset,
                io_push_i,
  input  [76:0] io_data_i,
  output        io_full_o,
  input         io_pop_i,
  output [76:0] io_data_o,
  output        io_empty_o
);

  wire             io_full_o_0;
  wire             _slot_T_1 = ~reset;
  reg  [76:0]      slot_0;
  reg  [76:0]      slot_1;
  reg  [76:0]      slot_2;
  reg  [76:0]      slot_3;
  reg  [76:0]      slot_4;
  reg  [76:0]      slot_5;
  reg  [76:0]      slot_6;
  reg  [76:0]      slot_7;
  wire             _push_point_T_1 = ~reset;
  reg  [3:0]       push_point;
  wire             _pop_point_T_1 = ~reset;
  reg  [3:0]       pop_point;
  wire             _GEN = io_push_i & ~io_full_o_0;
  wire [7:0][76:0] _GEN_0 =
    {{slot_7}, {slot_6}, {slot_5}, {slot_4}, {slot_3}, {slot_2}, {slot_1}, {slot_0}};
  wire             io_empty_o_0 =
    push_point[2:0] == pop_point[2:0] & push_point[3] == pop_point[3];
  assign io_full_o_0 = push_point[2:0] == pop_point[2:0] & push_point[3] != pop_point[3];
  always @(posedge clock or posedge _slot_T_1) begin
    if (_slot_T_1) begin
      slot_0 <= 77'h0;
      slot_1 <= 77'h0;
      slot_2 <= 77'h0;
      slot_3 <= 77'h0;
      slot_4 <= 77'h0;
      slot_5 <= 77'h0;
      slot_6 <= 77'h0;
      slot_7 <= 77'h0;
    end
    else begin
      if (_GEN & push_point[2:0] == 3'h0)
        slot_0 <= io_data_i;
      if (_GEN & push_point[2:0] == 3'h1)
        slot_1 <= io_data_i;
      if (_GEN & push_point[2:0] == 3'h2)
        slot_2 <= io_data_i;
      if (_GEN & push_point[2:0] == 3'h3)
        slot_3 <= io_data_i;
      if (_GEN & push_point[2:0] == 3'h4)
        slot_4 <= io_data_i;
      if (_GEN & push_point[2:0] == 3'h5)
        slot_5 <= io_data_i;
      if (_GEN & push_point[2:0] == 3'h6)
        slot_6 <= io_data_i;
      if (_GEN & (&(push_point[2:0])))
        slot_7 <= io_data_i;
    end
  end  
  always @(posedge clock or posedge _push_point_T_1) begin
    if (_push_point_T_1)
      push_point <= 4'h0;
    else if (_GEN)
      push_point <= push_point + 4'h1;
  end  
  always @(posedge clock or posedge _pop_point_T_1) begin
    if (_pop_point_T_1)
      pop_point <= 4'h0;
    else if (io_pop_i & ~io_empty_o_0)
      pop_point <= pop_point + 4'h1;
  end  
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif  
    initial begin
      if (_slot_T_1) begin
        slot_0 = 77'h0;
        slot_1 = 77'h0;
        slot_2 = 77'h0;
        slot_3 = 77'h0;
        slot_4 = 77'h0;
        slot_5 = 77'h0;
        slot_6 = 77'h0;
        slot_7 = 77'h0;
      end
      if (_push_point_T_1)
        push_point = 4'h0;
      if (_pop_point_T_1)
        pop_point = 4'h0;
    end  
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif  
  `endif  
  assign io_full_o = io_full_o_0;
  assign io_data_o = _GEN_0[pop_point[2:0]];
  assign io_empty_o = io_empty_o_0;
endmodule


