module FifoValidE5_2(
  input          clock,
                 reset,
                 io_push_i,
                 io_pop_i,
                 io_flush_i,
                 io_valid_i,
  input  [168:0] io_data_i,
  output         io_valid_o,
  output [168:0] io_data_o,
  output         io_empty_o,
                 io_full_o
);

  wire         _fifoValid_q_T_1 = ~reset;
  reg          fifoValid_q_0;
  reg          fifoValid_q_1;
  wire         _fifoData_q_T_1 = ~reset;
  reg  [168:0] fifoData_q_0;
  reg  [168:0] fifoData_q_1;
  wire         _fifo_wPtr_T_1 = ~reset;
  reg          fifo_wPtr_flag;
  reg          fifo_wPtr_bits;
  wire         _fifo_rPtr_T_1 = ~reset;
  reg          fifo_rPtr_flag;
  reg          fifo_rPtr_bits;
  wire         _GEN = io_push_i & ~fifo_wPtr_bits;
  wire         _GEN_0 = io_push_i & fifo_wPtr_bits;
  wire         _GEN_1 = io_pop_i & fifo_rPtr_bits;
  wire         _fifo_Full_d_T_1 = fifo_wPtr_bits == fifo_rPtr_bits;
  always @(posedge clock or posedge _fifoValid_q_T_1) begin
    if (_fifoValid_q_T_1) begin
      fifoValid_q_0 <= 1'h0;
      fifoValid_q_1 <= 1'h0;
    end
    else begin
      fifoValid_q_0 <=
        ~(io_flush_i | io_pop_i & ~fifo_rPtr_bits) & (_GEN ? io_valid_i : fifoValid_q_0);
      fifoValid_q_1 <= ~(io_flush_i | _GEN_1) & (_GEN_0 ? io_valid_i : fifoValid_q_1);
    end
  end  
  always @(posedge clock or posedge _fifoData_q_T_1) begin
    if (_fifoData_q_T_1) begin
      fifoData_q_0 <= 169'h0;
      fifoData_q_1 <= 169'h0;
    end
    else begin
      if (_GEN)
        fifoData_q_0 <= io_data_i;
      if (_GEN_0)
        fifoData_q_1 <= io_data_i;
    end
  end  
  always @(posedge clock or posedge _fifo_wPtr_T_1) begin
    if (_fifo_wPtr_T_1) begin
      fifo_wPtr_flag <= 1'h0;
      fifo_wPtr_bits <= 1'h0;
    end
    else begin
      fifo_wPtr_flag <= io_flush_i ? fifo_rPtr_flag : _GEN_0 ^ fifo_wPtr_flag;
      if (io_flush_i)
        fifo_wPtr_bits <= fifo_rPtr_bits;
      else if (io_push_i)
        fifo_wPtr_bits <= ~fifo_wPtr_bits & fifo_wPtr_bits - 1'h1;
    end
  end  
  always @(posedge clock or posedge _fifo_rPtr_T_1) begin
    if (_fifo_rPtr_T_1) begin
      fifo_rPtr_flag <= 1'h0;
      fifo_rPtr_bits <= 1'h0;
    end
    else begin
      fifo_rPtr_flag <= ~io_flush_i & _GEN_1 ^ fifo_rPtr_flag;
      if (io_flush_i | ~io_pop_i) begin
      end
      else
        fifo_rPtr_bits <= ~fifo_rPtr_bits & fifo_rPtr_bits - 1'h1;
    end
  end  
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif  
    initial begin
      if (_fifoValid_q_T_1) begin
        fifoValid_q_0 = 1'h0;
        fifoValid_q_1 = 1'h0;
      end
      if (_fifoData_q_T_1) begin
        fifoData_q_0 = 169'h0;
        fifoData_q_1 = 169'h0;
      end
      if (_fifo_wPtr_T_1) begin
        fifo_wPtr_flag = 1'h0;
        fifo_wPtr_bits = 1'h0;
      end
      if (_fifo_rPtr_T_1) begin
        fifo_rPtr_flag = 1'h0;
        fifo_rPtr_bits = 1'h0;
      end
    end  
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif  
  `endif  
  assign io_valid_o = fifo_rPtr_bits ? fifoValid_q_1 : fifoValid_q_0;
  assign io_data_o = fifo_rPtr_bits ? fifoData_q_1 : fifoData_q_0;
  assign io_empty_o = fifo_wPtr_flag == fifo_rPtr_flag & _fifo_Full_d_T_1;
  assign io_full_o = fifo_wPtr_flag != fifo_rPtr_flag & _fifo_Full_d_T_1;
endmodule


