  input  [43:0] io_miss_2_req_i_bits_vpn,
  input  [15:0] io_miss_2_req_i_bits_asid,
  input  [1:0]  io_miss_2_req_i_bits_cmd,
                io_miss_2_req_i_bits_privMode,
  input  [2:0]  io_miss_2_req_i_bits_missId,
  input  [7:0]  io_miss_2_req_i_bits_epoch,
  input         io_miss_2_resp_o_ready,
  output        io_miss_2_resp_o_valid,
  output [43:0] io_miss_2_resp_o_bits_ppn,
  output        io_miss_2_resp_o_bits_err,
  output [1:0]  io_miss_2_resp_o_bits_cause,
  input         io_missStatus_i_0_waitResp,
  input  [7:0]  io_missStatus_i_0_epoch,
  input         io_missStatus_i_1_waitResp,
  input  [7:0]  io_missStatus_i_1_epoch,
  input         io_missStatus_i_2_waitResp,
  input  [7:0]  io_missStatus_i_2_epoch,
  input         io_l2TLB_req_o_ready,
  output        io_l2TLB_req_o_valid,
  output [43:0] io_l2TLB_req_o_bits_vpn,
  output [15:0] io_l2TLB_req_o_bits_asid,
  output [1:0]  io_l2TLB_req_o_bits_cmd,
                io_l2TLB_req_o_bits_privMode,
  output [2:0]  io_l2TLB_req_o_bits_missId,
  output [7:0]  io_l2TLB_req_o_bits_epoch,
  output        io_l2TLB_resp_i_ready,
  input         io_l2TLB_resp_i_valid,
  input  [43:0] io_l2TLB_resp_i_bits_ppn,
  input         io_l2TLB_resp_i_bits_err,
  input  [1:0]  io_l2TLB_resp_i_bits_cause,
  input  [2:0]  io_l2TLB_resp_i_bits_missId,
  input  [7:0]  io_l2TLB_resp_i_bits_epoch,
  input         io_flush_i,
                io_retFlush_i,
                io_blockForward_i,
  output        io_refillFire_o
);

  wire [2:0]  _anyMissIssue_T =
    {io_miss_2_req_i_valid, io_miss_1_req_i_valid, io_miss_0_req_i_valid};
  reg  [1:0]  rrBase_q;
  wire        _grantVec_2_T = rrBase_q == 2'h0;
  wire        _grantVec_2_T_3 = rrBase_q == 2'h1;
  wire        _grantVec_2_T_6 = rrBase_q == 2'h2;
  wire [2:0]  rotatedGrantOH =
    (_grantVec_2_T_6
       ? io_miss_2_req_i_valid
       : _grantVec_2_T_3 ? io_miss_1_req_i_valid : io_miss_0_req_i_valid)
      ? 3'h1
      : (_grantVec_2_T_6
           ? io_miss_0_req_i_valid
           : _grantVec_2_T_3 ? io_miss_2_req_i_valid : io_miss_1_req_i_valid)
          ? 3'h2
          : {_grantVec_2_T_6
               ? io_miss_1_req_i_valid
               : _grantVec_2_T_3 ? io_miss_0_req_i_valid : io_miss_2_req_i_valid,
             2'h0};
  wire        grantVec_0 =
    _grantVec_2_T & rotatedGrantOH[0] | _grantVec_2_T_3 & rotatedGrantOH[2]
    | _grantVec_2_T_6 & rotatedGrantOH[1];
  wire        grantVec_1 =
    _grantVec_2_T & rotatedGrantOH[1] | _grantVec_2_T_3 & rotatedGrantOH[0]
    | _grantVec_2_T_6 & rotatedGrantOH[2];
  wire        grantVec_2 =
    _grantVec_2_T & rotatedGrantOH[2] | _grantVec_2_T_3 & rotatedGrantOH[1]
    | _grantVec_2_T_6 & rotatedGrantOH[0];
  wire        blockForward = io_flush_i | io_retFlush_i | io_blockForward_i;
  wire        io_l2TLB_req_o_valid_0 = (|_anyMissIssue_T) & ~blockForward;
  wire        _io_miss_2_req_i_ready_T = ~blockForward & io_l2TLB_req_o_ready;
  wire        respPortValid = io_l2TLB_resp_i_bits_missId < 3'h3;
  reg         respBufValid_q_0;
  reg         respBufValid_q_1;
  reg         respBufValid_q_2;
  reg  [43:0] respBufBits_q_0_ppn;
  reg         respBufBits_q_0_err;
  reg  [1:0]  respBufBits_q_0_cause;
  reg  [43:0] respBufBits_q_1_ppn;
  reg         respBufBits_q_1_err;
  reg  [1:0]  respBufBits_q_1_cause;
  reg  [43:0] respBufBits_q_2_ppn;
  reg         respBufBits_q_2_err;
  reg  [1:0]  respBufBits_q_2_cause;
  wire        _respCaptureReady_T_3 = io_l2TLB_resp_i_bits_missId == 3'h0;
  wire        respForwardVec_0 =
    respPortValid & _respCaptureReady_T_3 & io_missStatus_i_0_waitResp
    & io_missStatus_i_0_epoch == io_l2TLB_resp_i_bits_epoch & ~respBufValid_q_0;
  wire        _respCaptureReady_T_5 = io_l2TLB_resp_i_bits_missId == 3'h1;
  wire        respForwardVec_1 =
    respPortValid & _respCaptureReady_T_5 & io_missStatus_i_1_waitResp
    & io_missStatus_i_1_epoch == io_l2TLB_resp_i_bits_epoch & ~respBufValid_q_1;
  wire        _respCaptureReady_T_7 = io_l2TLB_resp_i_bits_missId == 3'h2;
  wire        respForwardVec_2 =
    respPortValid & _respCaptureReady_T_7 & io_missStatus_i_2_waitResp
    & io_missStatus_i_2_epoch == io_l2TLB_resp_i_bits_epoch & ~respBufValid_q_2;
  wire [2:0]  _respForward_T = {respForwardVec_2, respForwardVec_1, respForwardVec_0};
  wire        io_l2TLB_resp_i_ready_0 =
    blockForward | ~(|_respForward_T)
    | (_respCaptureReady_T_7
         ? ~respBufValid_q_2
         : _respCaptureReady_T_5
             ? ~respBufValid_q_1
             : ~_respCaptureReady_T_3 | ~respBufValid_q_0);
  wire        io_miss_0_resp_o_valid_0 =
    (respBufValid_q_0 | io_l2TLB_resp_i_valid & respForwardVec_0 & ~blockForward)
    & ~blockForward;
  wire        _io_refillFire_o_T = io_l2TLB_resp_i_ready_0 & io_l2TLB_resp_i_valid;
  wire        io_miss_1_resp_o_valid_0 =
    (respBufValid_q_1 | io_l2TLB_resp_i_valid & respForwardVec_1 & ~blockForward)
    & ~blockForward;
  wire        io_miss_2_resp_o_valid_0 =
    (respBufValid_q_2 | io_l2TLB_resp_i_valid & respForwardVec_2 & ~blockForward)
    & ~blockForward;
  wire        _GEN =
    _io_refillFire_o_T & respForwardVec_0 & ~blockForward & ~io_miss_0_resp_o_ready;
  wire        _GEN_0 =
    _io_refillFire_o_T & respForwardVec_1 & ~blockForward & ~io_miss_1_resp_o_ready;
  wire        _GEN_1 =
    _io_refillFire_o_T & respForwardVec_2 & ~blockForward & ~io_miss_2_resp_o_ready;
  always @(posedge clock) begin
    if (reset) begin
      rrBase_q <= 2'h0;
      respBufValid_q_0 <= 1'h0;
      respBufValid_q_1 <= 1'h0;
      respBufValid_q_2 <= 1'h0;
    end
    else begin
      if (io_l2TLB_req_o_ready & io_l2TLB_req_o_valid_0)
        rrBase_q <=
          {grantVec_2, grantVec_1} == 2'h2 ? 2'h0 : {grantVec_2, grantVec_1} + 2'h1;
      respBufValid_q_0 <=
        _GEN | ~(blockForward | io_miss_0_resp_o_ready & io_miss_0_resp_o_valid_0)
        & respBufValid_q_0;
      respBufValid_q_1 <=
        _GEN_0 | ~(blockForward | io_miss_1_resp_o_ready & io_miss_1_resp_o_valid_0)
        & respBufValid_q_1;
      respBufValid_q_2 <=
        _GEN_1 | ~(blockForward | io_miss_2_resp_o_ready & io_miss_2_resp_o_valid_0)
        & respBufValid_q_2;
    end
    if (_GEN) begin
      respBufBits_q_0_ppn <= io_l2TLB_resp_i_bits_ppn;
      respBufBits_q_0_err <= io_l2TLB_resp_i_bits_err;
      respBufBits_q_0_cause <= io_l2TLB_resp_i_bits_cause;
    end
    if (_GEN_0) begin
      respBufBits_q_1_ppn <= io_l2TLB_resp_i_bits_ppn;
      respBufBits_q_1_err <= io_l2TLB_resp_i_bits_err;
      respBufBits_q_1_cause <= io_l2TLB_resp_i_bits_cause;
    end
    if (_GEN_1) begin
      respBufBits_q_2_ppn <= io_l2TLB_resp_i_bits_ppn;
      respBufBits_q_2_err <= io_l2TLB_resp_i_bits_err;
      respBufBits_q_2_cause <= io_l2TLB_resp_i_bits_cause;
    end
  end
  assign io_miss_0_req_i_ready = _io_miss_2_req_i_ready_T & grantVec_0;
  assign io_miss_0_resp_o_valid = io_miss_0_resp_o_valid_0;
  assign io_miss_0_resp_o_bits_ppn =
    respBufValid_q_0 ? respBufBits_q_0_ppn : io_l2TLB_resp_i_bits_ppn;
  assign io_miss_0_resp_o_bits_err =
    respBufValid_q_0 ? respBufBits_q_0_err : io_l2TLB_resp_i_bits_err;
  assign io_miss_0_resp_o_bits_cause =
    respBufValid_q_0 ? respBufBits_q_0_cause : io_l2TLB_resp_i_bits_cause;
  assign io_miss_1_req_i_ready = _io_miss_2_req_i_ready_T & grantVec_1;
  assign io_miss_1_resp_o_valid = io_miss_1_resp_o_valid_0;
  assign io_miss_1_resp_o_bits_ppn =
    respBufValid_q_1 ? respBufBits_q_1_ppn : io_l2TLB_resp_i_bits_ppn;
  assign io_miss_1_resp_o_bits_err =
    respBufValid_q_1 ? respBufBits_q_1_err : io_l2TLB_resp_i_bits_err;
  assign io_miss_1_resp_o_bits_cause =
    respBufValid_q_1 ? respBufBits_q_1_cause : io_l2TLB_resp_i_bits_cause;
  assign io_miss_2_req_i_ready = _io_miss_2_req_i_ready_T & grantVec_2;
  assign io_miss_2_resp_o_valid = io_miss_2_resp_o_valid_0;
  assign io_miss_2_resp_o_bits_ppn =
    respBufValid_q_2 ? respBufBits_q_2_ppn : io_l2TLB_resp_i_bits_ppn;
  assign io_miss_2_resp_o_bits_err =
    respBufValid_q_2 ? respBufBits_q_2_err : io_l2TLB_resp_i_bits_err;
  assign io_miss_2_resp_o_bits_cause =
    respBufValid_q_2 ? respBufBits_q_2_cause : io_l2TLB_resp_i_bits_cause;
  assign io_l2TLB_req_o_valid = io_l2TLB_req_o_valid_0;
  assign io_l2TLB_req_o_bits_vpn =
    (|_anyMissIssue_T)
      ? (grantVec_0 ? io_miss_0_req_i_bits_vpn : 44'h0)
        | (grantVec_1 ? io_miss_1_req_i_bits_vpn : 44'h0)
        | (grantVec_2 ? io_miss_2_req_i_bits_vpn : 44'h0)
      : 44'h0;
  assign io_l2TLB_req_o_bits_asid =
    (|_anyMissIssue_T)
      ? (grantVec_0 ? io_miss_0_req_i_bits_asid : 16'h0)
        | (grantVec_1 ? io_miss_1_req_i_bits_asid : 16'h0)
        | (grantVec_2 ? io_miss_2_req_i_bits_asid : 16'h0)
      : 16'h0;
  assign io_l2TLB_req_o_bits_cmd =
    (|_anyMissIssue_T)
      ? (grantVec_0 ? io_miss_0_req_i_bits_cmd : 2'h0)
        | (grantVec_1 ? io_miss_1_req_i_bits_cmd : 2'h0)
        | (grantVec_2 ? io_miss_2_req_i_bits_cmd : 2'h0)
      : 2'h0;
  assign io_l2TLB_req_o_bits_privMode =
    (|_anyMissIssue_T)
      ? (grantVec_0 ? io_miss_0_req_i_bits_privMode : 2'h0)
        | (grantVec_1 ? io_miss_1_req_i_bits_privMode : 2'h0)
        | (grantVec_2 ? io_miss_2_req_i_bits_privMode : 2'h0)
      : 2'h0;
  assign io_l2TLB_req_o_bits_missId =
    (|_anyMissIssue_T)
      ? (grantVec_0 ? io_miss_0_req_i_bits_missId : 3'h0)
        | (grantVec_1 ? io_miss_1_req_i_bits_missId : 3'h0)
        | (grantVec_2 ? io_miss_2_req_i_bits_missId : 3'h0)
      : 3'h0;
  assign io_l2TLB_req_o_bits_epoch =
    (|_anyMissIssue_T)
      ? (grantVec_0 ? io_miss_0_req_i_bits_epoch : 8'h0)
        | (grantVec_1 ? io_miss_1_req_i_bits_epoch : 8'h0)
        | (grantVec_2 ? io_miss_2_req_i_bits_epoch : 8'h0)
      : 8'h0;
  assign io_l2TLB_resp_i_ready = io_l2TLB_resp_i_ready_0;
  assign io_refillFire_o = _io_refillFire_o_T & (|_respForward_T) & ~blockForward;
endmodule


module LsuConfigRangeCheck(
  input  [51:0] io_config_i_startAddr,
  input  [4:0]  io_config_i_size,
  input  [63:0] io_addr_i,
  output        io_in_range_o
);

  wire [94:0] mask_bits_d = 95'hFFFFFFFFFFFFFFFF << io_config_i_size + 5'hA;
  assign io_in_range_o =
    (io_addr_i
     & mask_bits_d[63:0]) == ({io_config_i_startAddr, 12'h0} & mask_bits_d[63:0]);
endmodule


module csrr_reset_value#(
  parameter	integer WIDTH = 32
)(
  input         clock,
  input         reset_ni,
  input  [WIDTH-1:0] reset_value_i,
  input  [WIDTH-1:0] wr_data_i, 
  input         wr_en_i, 
  output [WIDTH-1:0] rd_data_o
);
  reg [WIDTH-1:0] rdata_q; 
  assign rd_data_o = rdata_q; 
  always @(posedge clock or negedge reset_ni) begin
    if (!reset_ni) begin 
      rdata_q <= reset_value_i; 
    end else if (wr_en_i) begin
      rdata_q <= wr_data_i;
    end
  end
endmodule
