);

  wire        _probe_handshake_f2_T_1 = ~reset;
  reg         probe_handshake_f2;
  wire        _probe_handshake_f3_T_1 = ~reset;
  reg         probe_handshake_f3;
  wire        _probe_address_T_1 = ~reset;
  reg  [47:0] probe_address;
  wire        _probe_address_add_T_1 = ~reset;
  reg  [47:0] probe_address_add;
  wire        _flag_T_1 = ~reset;
  reg         flag;
  wire        _tlc_valid_T_1 = ~reset;
  reg         tlc_valid;
  wire        _tlc_opcode_T_1 = ~reset;
  reg  [2:0]  tlc_opcode;
  wire        probe_handshake_f1 =
    io_tl_cb_valid & (io_tl_cb_bits_opcode == 3'h6 | (&io_tl_cb_bits_opcode)) & ~flag;
  wire        io_meta_wr_valid_0 = probe_handshake_f2 | probe_handshake_f3;
  wire [51:0] _GEN = {43'h0, probe_address_add[12:4]};
  wire        _GEN_0 = tlc_valid & io_tl_cc_ready;
  always @(posedge clock or posedge _probe_handshake_f2_T_1) begin
    if (_probe_handshake_f2_T_1)
      probe_handshake_f2 <= 1'h0;
    else
      probe_handshake_f2 <= probe_handshake_f1;
  end  
  always @(posedge clock or posedge _probe_handshake_f3_T_1) begin
    if (_probe_handshake_f3_T_1)
      probe_handshake_f3 <= 1'h0;
    else
      probe_handshake_f3 <= probe_handshake_f2;
  end  
  always @(posedge clock or posedge _probe_address_T_1) begin
    if (_probe_address_T_1)
      probe_address <= 48'h0;
    else if (probe_handshake_f1)
      probe_address <= {io_tl_cb_bits_address[47:5], 5'h0};
  end  
  always @(posedge clock or posedge _probe_address_add_T_1) begin
    if (_probe_address_add_T_1)
      probe_address_add <= 48'h0;
    else if (probe_handshake_f1)
      probe_address_add <= {io_tl_cb_bits_address[47:5], 5'h10};
  end  
  always @(posedge clock or posedge _flag_T_1) begin
    if (_flag_T_1)
      flag <= 1'h0;
    else
      flag <= probe_handshake_f1 | ~probe_handshake_f3 & flag;
  end  
  always @(posedge clock or posedge _tlc_valid_T_1) begin
    if (_tlc_valid_T_1)
      tlc_valid <= 1'h0;
    else
      tlc_valid <= probe_handshake_f1 | ~_GEN_0 & tlc_valid;
  end  
  always @(posedge clock or posedge _tlc_opcode_T_1) begin
    if (_tlc_opcode_T_1)
      tlc_opcode <= 3'h0;
    else if (probe_handshake_f1)
      tlc_opcode <= 3'h4;
    else if (_GEN_0)
      tlc_opcode <= 3'h0;
  end  
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif  
    initial begin
      if (_probe_handshake_f2_T_1)
        probe_handshake_f2 = 1'h0;
      if (_probe_handshake_f3_T_1)
        probe_handshake_f3 = 1'h0;
      if (_probe_address_T_1)
        probe_address = 48'h0;
      if (_probe_address_add_T_1)
        probe_address_add = 48'h0;
      if (_flag_T_1)
        flag = 1'h0;
      if (_tlc_valid_T_1)
        tlc_valid = 1'h0;
      if (_tlc_opcode_T_1)
        tlc_opcode = 3'h0;
    end  
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif  
  `endif  
  assign io_tl_cb_ready = ~flag;
  assign io_tl_cc_valid = tlc_valid;
  assign io_tl_cc_bits_opcode = tlc_opcode;
  assign io_meta_rd_req_o_valid = io_meta_wr_valid_0;
  assign io_meta_rd_req_o_bits_addr =
    probe_handshake_f2 ? probe_address[12:4] : probe_address_add[12:4];
  assign io_tag_rd_req_o_valid = io_meta_wr_valid_0;
  assign io_tag_rd_req_o_bits_addr =
