  assign io_meta_wr_valid = io_meta_wr_valid_0;
  assign io_meta_wr_bits_addr =
    probe_handshake_f2 ? probe_address[12:4] : probe_address_add[12:4];
  assign io_meta_wr_bits_way_en_0 =
