  assign io_meta_wr_bits_way_en_1 =
    probe_handshake_f2
      ? probe_handshake_f2 & io_meta_rd_resp_i_meta_1
        & io_tag_rd_resp_i_enctag_1[51:0] == _GEN
      : probe_handshake_f3 & io_meta_rd_resp_i_meta_1
        & io_tag_rd_resp_i_enctag_1[51:0] == _GEN;
  assign io_meta_wr_bits_way_en_2 =
    probe_handshake_f2
      ? probe_handshake_f2 & io_meta_rd_resp_i_meta_2
        & io_tag_rd_resp_i_enctag_2[51:0] == _GEN
      : probe_handshake_f3 & io_meta_rd_resp_i_meta_2
        & io_tag_rd_resp_i_enctag_2[51:0] == _GEN;
  assign io_meta_wr_bits_way_en_3 =
    probe_handshake_f2
      ? probe_handshake_f2 & io_meta_rd_resp_i_meta_3
        & io_tag_rd_resp_i_enctag_3[51:0] == _GEN
