      if (io_hittedReq_i_index[3:1] == 3'h2)
        lru_q_9 <= ~(io_hittedReq_i_index[0]);
      else if (missUpdatedState_onPath_8)
        lru_q_9 <= ~missUpdatedState_goRight_7;
      if (io_hittedReq_i_index[3:1] == 3'h3)
        lru_q_10 <= ~(io_hittedReq_i_index[0]);
      else if (missUpdatedState_onPath_9)
