module FIFO_interface_1w1r_14(
  input        clock,
               reset,
               io_push_i,
  input  [6:0] io_data_i,
  output       io_full_o,
  input        io_pop_i,
  output [6:0] io_data_o,
  output       io_empty_o
);

  wire       io_full_o_0;
  wire       _slot_T_1 = ~reset;
  reg  [6:0] slot_0;
  reg  [6:0] slot_1;
  wire       _push_point_T_1 = ~reset;
  reg  [1:0] push_point;
  wire       _pop_point_T_1 = ~reset;
  reg  [1:0] pop_point;
  wire       _GEN = io_push_i & ~io_full_o_0;
  wire       io_empty_o_0 = push_point[0] == pop_point[0] & push_point[1] == pop_point[1];
  assign io_full_o_0 = push_point[0] == pop_point[0] & push_point[1] != pop_point[1];
  always @(posedge clock or posedge _slot_T_1) begin
    if (_slot_T_1) begin
      slot_0 <= 7'h0;
      slot_1 <= 7'h0;
    end
    else begin
      if (_GEN & ~(push_point[0]))
        slot_0 <= io_data_i;
      if (_GEN & push_point[0])
        slot_1 <= io_data_i;
    end
  end  
  always @(posedge clock or posedge _push_point_T_1) begin
    if (_push_point_T_1)
      push_point <= 2'h0;
    else if (_GEN)
      push_point <= push_point + 2'h1;
  end  
  always @(posedge clock or posedge _pop_point_T_1) begin
    if (_pop_point_T_1)
      pop_point <= 2'h0;
    else if (io_pop_i & ~io_empty_o_0)
      pop_point <= pop_point + 2'h1;
  end  
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif  
    initial begin
      if (_slot_T_1) begin
        slot_0 = 7'h0;
        slot_1 = 7'h0;
      end
      if (_push_point_T_1)
        push_point = 2'h0;
      if (_pop_point_T_1)
        pop_point = 2'h0;
    end  
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif  
  `endif  
  assign io_full_o = io_full_o_0;
  assign io_data_o = pop_point[0] ? slot_1 : slot_0;
  assign io_empty_o = io_empty_o_0;
endmodule


