  end
  10'b1000111111: 
  begin
    total_qt_rt_next[QT_WIDTH-1:0]       = total_qt_rt_minus[QT_WIDTH-1:0]
                                            |qt_rt_const_q13[QT_WIDTH-1:0];
    total_qt_rt_minus_next[QT_WIDTH-1:0] = total_qt_rt_minus[QT_WIDTH-1:0]
                                            |qt_rt_const_q12[QT_WIDTH-1:0];
  end
  10'b1000011111: 
  begin
    total_qt_rt_next[QT_WIDTH-1:0]       = total_qt_rt_minus[QT_WIDTH-1:0]
