always @( cur_rem_2[60:0]
       or remainder_shift[60:0]
       or bound_cmp_sign[8:0]
       or cur_rem_6[60:0]
       or cur_rem_8[60:0]
       or cur_rem_3[60:0]
       or cur_rem_7[60:0]
       or cur_rem_4[60:0]
       or cur_rem_5[60:0]
       or cur_rem_9[60:0]
       or cur_rem_1[60:0])
begin
case(bound_cmp_sign[8:0])
  9'b111111111: cur_rem[REM_WIDTH-1:0]   = remainder_shift[REM_WIDTH-1:0];  
  9'b011111111: cur_rem[REM_WIDTH-1:0]   = cur_rem_1[REM_WIDTH-1:0];        
  9'b001111111: cur_rem[REM_WIDTH-1:0]   = cur_rem_2[REM_WIDTH-1:0];        
  9'b000111111: cur_rem[REM_WIDTH-1:0]   = cur_rem_3[REM_WIDTH-1:0];        
  9'b000011111: cur_rem[REM_WIDTH-1:0]   = cur_rem_4[REM_WIDTH-1:0];        
  9'b000001111: cur_rem[REM_WIDTH-1:0]   = cur_rem_5[REM_WIDTH-1:0];        
  9'b000000111: cur_rem[REM_WIDTH-1:0]   = cur_rem_6[REM_WIDTH-1:0];        
  9'b000000011: cur_rem[REM_WIDTH-1:0]   = cur_rem_7[REM_WIDTH-1:0];        
  9'b000000001: cur_rem[REM_WIDTH-1:0]   = cur_rem_8[REM_WIDTH-1:0];        
  9'b000000000: cur_rem[REM_WIDTH-1:0]   = cur_rem_9[REM_WIDTH-1:0];        
  default :     cur_rem[REM_WIDTH-1:0]   = {REM_WIDTH{1'bx}};
endcase
 
end
assign srt_remainder_nxt[REM_WIDTH-1:0]   = cur_rem[REM_WIDTH-1:0];
 
assign srt_remainder_sign                 = srt_remainder_nxt[REM_WIDTH-1];

 
 
 
always @(posedge srt_qt_rem_clk or negedge cpurst_b)
begin
  if(!cpurst_b)begin
    srt_remainder_minus[REM_WIDTH-1:0]  <= {REM_WIDTH{1'b0}};
  end
  else if(srt_sm_on)begin
    srt_remainder_minus[REM_WIDTH-1:0]  <= srt_remainder_minus_nxt[REM_WIDTH-1:0];
  end
  else begin
    srt_remainder_minus[REM_WIDTH-1:0]  <= srt_remainder_minus[REM_WIDTH-1:0];
  end
end

assign srt_remainder_out[REM_WIDTH-2:0] = srt_remainder[REM_WIDTH-1] ? srt_remainder_minus[REM_WIDTH-2:0]
                                                                     : srt_remainder[REM_WIDTH-2:0];

assign remainder_minus_shift[REM_WIDTH-1:0] = {srt_remainder_minus[REM_WIDTH-5:0],4'b0};
 
assign rem_minus_minus_6[REM_WIDTH-1:0]      = $unsigned($signed(remainder_minus_shift[REM_WIDTH-1:0])
                                             - $signed({div_qt_r4_rem_add_op1[REM_WIDTH-1:0]})
                                             - $signed({div_qt_r2_rem_add_op1[REM_WIDTH-1:0]}));
 
 
 

 
 

 
assign remainder_minus_nor_nxt_0[REM_WIDTH-1:0]  = rem_sign ? cur_rem_1[REM_WIDTH-1:0]
						            : remainder_minus_shift[REM_WIDTH-1:0];
assign remainder_minus_nor_nxt_1[REM_WIDTH-1:0]  = rem_sign ? cur_rem_2[REM_WIDTH-1:0]
                                                            : remainder_shift[REM_WIDTH-1:0];
assign remainder_minus_nor_nxt_2[REM_WIDTH-1:0]  = rem_sign ? cur_rem_3[REM_WIDTH-1:0]
                                                            : cur_rem_1[REM_WIDTH-1:0];
assign remainder_minus_nor_nxt_3[REM_WIDTH-1:0]  = rem_sign ? cur_rem_4[REM_WIDTH-1:0]
                                                            : cur_rem_2[REM_WIDTH-1:0];
assign remainder_minus_nor_nxt_4[REM_WIDTH-1:0]  = rem_sign ? cur_rem_5[REM_WIDTH-1:0]
                                                            : cur_rem_3[REM_WIDTH-1:0];
assign remainder_minus_nor_nxt_5[REM_WIDTH-1:0]  = rem_sign ? cur_rem_6[REM_WIDTH-1:0]
                                                            : cur_rem_4[REM_WIDTH-1:0];
assign remainder_minus_nor_nxt_6[REM_WIDTH-1:0]  = rem_sign ? cur_rem_7[REM_WIDTH-1:0]
                                                            : cur_rem_5[REM_WIDTH-1:0];
assign remainder_minus_nor_nxt_7[REM_WIDTH-1:0]  = rem_sign ? cur_rem_8[REM_WIDTH-1:0]
                                                            : cur_rem_6[REM_WIDTH-1:0];
assign remainder_minus_nor_nxt_8[REM_WIDTH-1:0]  = rem_sign ? cur_rem_9[REM_WIDTH-1:0]
                                                            : cur_rem_7[REM_WIDTH-1:0];
assign remainder_minus_nor_nxt_9[REM_WIDTH-1:0]  = rem_sign ? rem_minus_minus_6[REM_WIDTH-1:0]
                                                            : cur_rem_8[REM_WIDTH-1:0];
 
always @( bound_cmp_sign[8:0]
       or remainder_minus_nor_nxt_7[60:0]
       or remainder_minus_nor_nxt_1[60:0]
       or remainder_minus_nor_nxt_4[60:0]
       or remainder_minus_nor_nxt_5[60:0]
       or remainder_minus_nor_nxt_2[60:0]
       or remainder_minus_nor_nxt_9[60:0]
       or remainder_minus_nor_nxt_8[60:0]
       or remainder_minus_nor_nxt_0[60:0]
       or remainder_minus_nor_nxt_3[60:0]
       or remainder_minus_nor_nxt_6[60:0])
begin
case({bound_cmp_sign[8:0]})
  9'b111111111: srt_remainder_minus_nxt[REM_WIDTH-1:0] = remainder_minus_nor_nxt_0[REM_WIDTH-1:0]; 
  9'b011111111: srt_remainder_minus_nxt[REM_WIDTH-1:0] = remainder_minus_nor_nxt_1[REM_WIDTH-1:0]; 
  9'b001111111: srt_remainder_minus_nxt[REM_WIDTH-1:0] = remainder_minus_nor_nxt_2[REM_WIDTH-1:0]; 
  9'b000111111: srt_remainder_minus_nxt[REM_WIDTH-1:0] = remainder_minus_nor_nxt_3[REM_WIDTH-1:0]; 
  9'b000011111: srt_remainder_minus_nxt[REM_WIDTH-1:0] = remainder_minus_nor_nxt_4[REM_WIDTH-1:0]; 
  9'b000001111: srt_remainder_minus_nxt[REM_WIDTH-1:0] = remainder_minus_nor_nxt_5[REM_WIDTH-1:0]; 
  9'b000000111: srt_remainder_minus_nxt[REM_WIDTH-1:0] = remainder_minus_nor_nxt_6[REM_WIDTH-1:0]; 
  9'b000000011: srt_remainder_minus_nxt[REM_WIDTH-1:0] = remainder_minus_nor_nxt_7[REM_WIDTH-1:0]; 
  9'b000000001: srt_remainder_minus_nxt[REM_WIDTH-1:0] = remainder_minus_nor_nxt_8[REM_WIDTH-1:0]; 
  9'b000000000: srt_remainder_minus_nxt[REM_WIDTH-1:0] = remainder_minus_nor_nxt_9[REM_WIDTH-1:0]; 
  default :     srt_remainder_minus_nxt[REM_WIDTH-1:0] = {REM_WIDTH{1'bx}};
endcase
 
end

 
endmodule



 
 
 
 
 
 
 
 
 
 
 
 

package defs_div_sqrt_mvp;

    
   localparam C_RM                  = 3;
   localparam C_RM_NEAREST          = 3'h0;
   localparam C_RM_TRUNC            = 3'h1;
   localparam C_RM_PLUSINF          = 3'h2;
   localparam C_RM_MINUSINF         = 3'h3;
   localparam C_PC                  = 6;  
   localparam C_FS                  = 2;  
   localparam C_IUNC                = 2;  
   localparam Iteration_unit_num_S  = 2'b10;

    
   localparam C_OP_FP64             = 64;
   localparam C_MANT_FP64           = 52;
   localparam C_EXP_FP64            = 11;
   localparam C_BIAS_FP64           = 1023;
   localparam C_BIAS_AONE_FP64      = 11'h400;
   localparam C_HALF_BIAS_FP64      = 511;
   localparam C_EXP_ZERO_FP64       = 11'h000;
   localparam C_EXP_ONE_FP64        = 13'h001;  
   localparam C_EXP_INF_FP64        = 11'h7FF;
   localparam C_MANT_ZERO_FP64      = 52'h0;
   localparam C_MANT_NAN_FP64       = 52'h8_0000_0000_0000;
   localparam C_PZERO_FP64          = 64'h0000_0000_0000_0000;
   localparam C_MZERO_FP64          = 64'h8000_0000_0000_0000;
   localparam C_QNAN_FP64           = 64'h7FF8_0000_0000_0000;

    
   localparam C_OP_FP32             = 32;
   localparam C_MANT_FP32           = 23;
   localparam C_EXP_FP32            = 8;
   localparam C_BIAS_FP32           = 127;
   localparam C_BIAS_AONE_FP32      = 8'h80;
   localparam C_HALF_BIAS_FP32      = 63;
   localparam C_EXP_ZERO_FP32       = 8'h00;
   localparam C_EXP_INF_FP32        = 8'hFF;
   localparam C_MANT_ZERO_FP32      = 23'h0;
   localparam C_PZERO_FP32          = 32'h0000_0000;
   localparam C_MZERO_FP32          = 32'h8000_0000;
   localparam C_QNAN_FP32           = 32'h7FC0_0000;

    
   localparam C_OP_FP16             = 16;
   localparam C_MANT_FP16           = 10;
   localparam C_EXP_FP16            = 5;
   localparam C_BIAS_FP16           = 15;
   localparam C_BIAS_AONE_FP16      = 5'h10;
   localparam C_HALF_BIAS_FP16      = 7;
   localparam C_EXP_ZERO_FP16       = 5'h00;
   localparam C_EXP_INF_FP16        = 5'h1F;
   localparam C_MANT_ZERO_FP16      = 10'h0;
   localparam C_PZERO_FP16          = 16'h0000;
   localparam C_MZERO_FP16          = 16'h8000;
   localparam C_QNAN_FP16           = 16'h7E00;

    
   localparam C_OP_FP16ALT           = 16;
   localparam C_MANT_FP16ALT         = 7;
   localparam C_EXP_FP16ALT          = 8;
   localparam C_BIAS_FP16ALT         = 127;
   localparam C_BIAS_AONE_FP16ALT    = 8'h80;
   localparam C_HALF_BIAS_FP16ALT    = 63;
   localparam C_EXP_ZERO_FP16ALT     = 8'h00;
   localparam C_EXP_INF_FP16ALT      = 8'hFF;
   localparam C_MANT_ZERO_FP16ALT    = 7'h0;
   localparam C_QNAN_FP16ALT         = 16'h7FC0;

endpackage : defs_div_sqrt_mvp

module ex_fpu_divsqrt
#(parameter VLEN           = `VLEN,
  parameter DIRTY_WIDTH    = 2 ,
  parameter TAG_WIDTH      = `TAG_WIDTH 
)
(
    input logic clk,
    input logic rst_l,

     
     
    input logic         rs_fpu_valid,
    input fpu_pkt_t     rs_fpu_p,                    
    input logic  [63:0] rs_fpu_rs1_d,                
    input logic  [63:0] rs_fpu_rs2_d,                
    input logic  [63:0] rs_fpu_fs1_d,                
    input logic  [63:0] rs_fpu_fs2_d,                
    input logic  [63:0] rs_fpu_fs3_d,                
    input logic  [TAG_WIDTH-1:0] rs_fpu_tag,
    input logic  [7:0]  rs_fflags,
    input logic  [2:0]  rs_frm,
    input logic  [2:0]  rs_rm,

     
    output logic        fpu_fu_ready,

     
    input logic exu_flush_final,

     
     
    output logic                 exu_fpu_valid,  
    input logic                  exu_fpu_ready,        
    output logic [63:0]          exu_fpu_result,
    output logic                 exu_fpu_result_x,
    output logic                 exu_fpu_result_f,
    output logic [4:0]           exu_fpu_csr,
    output logic [TAG_WIDTH-1:0] exu_fpu_tag                                       
);

localparam int unsigned NUM_OPERANDS = 3 ;
localparam int unsigned WIDTH        = 64;

logic [NUM_OPERANDS-1:0][WIDTH-1:0] operands_i;
E6FPU_pkg::roundmode_e              rnd_mode_i;
E6FPU_pkg::operation_e              op_i;
logic                               op_mod_i;
E6FPU_pkg::fp_format_e              src_fmt_i;
E6FPU_pkg::fp_format_e              dst_fmt_i;
E6FPU_pkg::int_format_e             int_fmt_i;
logic                               vectorial_op_i;
logic [TAG_WIDTH+1:0]               tag_i;       
logic                               simd_mask_i;
   
logic                              in_valid_i;
logic                              in_ready_o;
logic                              flush_i;
   
logic [WIDTH-1:0]                  result_o;
E6FPU_pkg::status_t                status_o;
logic [TAG_WIDTH+1:0]              tag_o;
   
logic                              out_valid_o;
logic                              out_ready_i;
   
logic                              busy_o;

logic                              fw_out_valid_o;
logic [WIDTH-1:0]                  fw_result_o;
E6FPU_pkg::status_t                fw_status_o;
logic [TAG_WIDTH+1:0]              fw_tag_o;

E6FPU_pkg::roundmode_e rm_true ;

fpu_pkt_t              fp;                    
logic  [63:0]          rs1;                
logic  [63:0]          rs2;                
logic  [63:0]          fs1;                
logic  [63:0]          fs2;                
logic  [63:0]          fs3;                
logic                  ex_fpu_rd, ex_fpu_fd;

logic [7:0]   fflags  ;
logic [2:0]   frm     ;
logic [2:0]   rm      ;

logic fs1_nan;
logic fs2_nan;
logic [63:0] nan;
logic [2:0]nan_switch_flag;

assign fflags  = rs_fflags;
assign frm     = rs_frm;
assign rm      = rs_rm;
assign fpu_fu_ready     = in_ready_o;

assign rm_true = rm == 3'b111 ? E6FPU_pkg::roundmode_e'(frm) : E6FPU_pkg::roundmode_e'(rm) ;


assign fp           = rs_fpu_p     ;
assign rs1          = rs_fpu_rs1_d ;
assign rs2          = rs_fpu_rs2_d ;
 
 
 

 
 
 
 
 
 
 

assign    fs1          = (src_fmt_i == E6FPU_pkg::FP64) | fp.fp_fmv ? rs_fpu_fs1_d :
                         (src_fmt_i == E6FPU_pkg::FP32)             ? (rs_fpu_fs1_d[63:32] == 32'hffffffff)     ? rs_fpu_fs1_d : 64'hffffffff7fc00000 :
                                                                      (rs_fpu_fs1_d[63:16] == 48'hffffffffffff) ? rs_fpu_fs1_d : 64'hffffffffffff7e00 ;
assign    fs2          = (src_fmt_i == E6FPU_pkg::FP64) | fp.fp_fmv ? rs_fpu_fs2_d :
                         (src_fmt_i == E6FPU_pkg::FP32)             ? (rs_fpu_fs2_d[63:32] == 32'hffffffff)     ? rs_fpu_fs2_d : 64'hffffffff7fc00000 :
                                                                      (rs_fpu_fs2_d[63:16] == 48'hffffffffffff) ? rs_fpu_fs2_d : 64'hffffffffffff7e00 ;
assign    fs3          = (src_fmt_i == E6FPU_pkg::FP64) | fp.fp_fmv ? rs_fpu_fs3_d :
                         (src_fmt_i == E6FPU_pkg::FP32)             ? (rs_fpu_fs3_d[63:32] == 32'hffffffff)     ? rs_fpu_fs3_d : 64'hffffffff7fc00000 :
                                                                      (rs_fpu_fs3_d[63:16] == 48'hffffffffffff) ? rs_fpu_fs3_d : 64'hffffffffffff7e00 ;

 
 
 

 
 

assign fs1_nan = (fs1[62:52] == {11{1'b1}} & fs1[51:0] != '0  &  src_fmt_i == E6FPU_pkg::FP64) | 
                 (fs1[30:23] == {8{1'b1}}  & fs1[22:0] != '0  &  src_fmt_i == E6FPU_pkg::FP32) |
                 (fs1[14:10] == {5{1'b1}}  & fs1[9:0]  != '0  &  src_fmt_i == E6FPU_pkg::FP16) ;

assign fs2_nan = (fs2[62:52] == {11{1'b1}} & fs2[51:0] != '0  &  src_fmt_i == E6FPU_pkg::FP64) | 
                 (fs2[30:23] == {8{1'b1}}  & fs2[22:0] != '0  &  src_fmt_i == E6FPU_pkg::FP32) |
                 (fs2[14:10] == {5{1'b1}}  & fs2[9:0]  != '0  &  src_fmt_i == E6FPU_pkg::FP16) ;

assign nan = src_fmt_i == E6FPU_pkg::FP64 ? 64'h7ff8000000000000 : 64'hffffffff7fc00000 ;
assign nan_switch_flag = {(src_fmt_i == E6FPU_pkg::FP64) , fs2_nan, fs1_nan};
always_comb begin
  operands_i[0][WIDTH-1:0] = '0;
  operands_i[1][WIDTH-1:0] = '0;
  operands_i[2][WIDTH-1:0] = '0;
  rnd_mode_i = E6FPU_pkg::roundmode_e'(rm_true) ;
  op_i       = E6FPU_pkg::ADD;
  op_mod_i   = 1'b0;
  src_fmt_i  = E6FPU_pkg::FP64;
  dst_fmt_i  = E6FPU_pkg::FP64;
  int_fmt_i  = E6FPU_pkg::INT32;
  vectorial_op_i = 1'b0;
  tag_i      = {fp.rd,  fp.fd , rs_fpu_tag};
  simd_mask_i = 1'b0;

  if(fp.f_extension)begin
    src_fmt_i  = E6FPU_pkg::FP32;
    dst_fmt_i  = E6FPU_pkg::FP32;
  end else if(fp.fp16_extension) begin
    src_fmt_i  = E6FPU_pkg::FP16;
    dst_fmt_i  = E6FPU_pkg::FP16;
  end else if(fp.d_extension) begin
    if(fp.fp_fcvt_s_d) begin
      src_fmt_i  = E6FPU_pkg::FP64;
      dst_fmt_i  = E6FPU_pkg::FP32;
    end else if(fp.fp_fcvt_d_s) begin
      src_fmt_i  = E6FPU_pkg::FP32;
      dst_fmt_i  = E6FPU_pkg::FP64;
    end else begin
      src_fmt_i  = E6FPU_pkg::FP64;
      dst_fmt_i  = E6FPU_pkg::FP64;
    end
  end

   
   
   
   
   

   
   
   
   
   
   

   
   
   
   
   
   

   
   
   
   
   
   

   
   
   
   
   
   

   
   
   
   
   
   

   
   
   
   
   
   

   
   
   
  if(fp.fp_fdiv) begin
    operands_i[0][WIDTH-1:0] = fs1;
    operands_i[1][WIDTH-1:0] = fs2;
    operands_i[2][WIDTH-1:0] = '0;

    op_i                     = E6FPU_pkg::DIV;
    op_mod_i                 = 1'b0;

     
     
       
     

     
       
     

  end else if(fp.fp_fsqrt) begin
    operands_i[0][WIDTH-1:0] = fs1;
    operands_i[1][WIDTH-1:0] = '0;
    operands_i[2][WIDTH-1:0] = '0;

    op_i                     = E6FPU_pkg::SQRT;
    op_mod_i                 = 1'b0;

     
     
     
     

   
   
   
   

   
   
   
   
   
   
   
   

   
   
   
   
   
   
   
   

   
   
   
   
   
   
   
   

   
   
   
   
   
   
   
   

   
   
   
   
   
   
   
   

   
   
   
   
   
   
   
   

   
   
   
   
   
   
   
   

   
   
   
   
   
   
   
   

   
   
   
   
   
   

   
   
   
   
   
   
   

   
   
   
   
   
   
   

   
   
   
   
   
   
   
   

   
   
   
   
   
   
   

   
   
   
   
   
   
   

   
   
   
   
   
   

   
   
   
   
   

   
   
   
   
   
   
   

   
   
   
   
   
   
   

   
   
   
   
   
   
   

   
   
   
   
   
   
   

   
   
   
   
   
   
   

   
   
   
  end
   
   
end

assign in_valid_i  = rs_fpu_valid;
assign flush_i     = exu_flush_final;
assign out_ready_i = exu_fpu_ready;

fpnew_top #(
  .Features       ( E6FPU_pkg::RV64D_Xsflt              ),
  .Implementation ( E6FPU_pkg::DIVSQRT_4Reg        ),
  .TagType        ( logic[TAG_WIDTH+1:0]          ),
  .DivSqrtSel     ( E6FPU_pkg::THMULTI            )
) i_fpnew_top (
  .*,
  .clk_i(clk),
  .rst_ni(rst_l),
  .nan_switch_flag(nan_switch_flag)
);


assign exu_fpu_valid = out_valid_o;
assign {ex_fpu_rd, ex_fpu_fd, exu_fpu_tag}   = tag_o;
assign exu_fpu_result   = result_o;
assign exu_fpu_result_x = ex_fpu_rd;
assign exu_fpu_result_f = ex_fpu_fd;
assign exu_fpu_csr      = status_o;

endmodule
 
 
 
 
 
 
 
 
 
 
 
 

 

`include "E6.svh"

module fpnew_opgroup_multifmt_slice #(
  parameter E6FPU_pkg::opgroup_e      OpGroup       = E6FPU_pkg::CONV,
  parameter int unsigned              Width         = 64,
   
  parameter E6FPU_pkg::fmt_logic_t    FpFmtConfig   = '1,
  parameter E6FPU_pkg::ifmt_logic_t   IntFmtConfig  = '1,
  parameter logic                     EnableVectors = 1'b1,
  parameter E6FPU_pkg::divsqrt_unit_t DivSqrtSel    = E6FPU_pkg::THMULTI,
  parameter int unsigned              NumPipeRegs   = 0,
  parameter E6FPU_pkg::pipe_config_t  PipeConfig    = E6FPU_pkg::BEFORE,
  parameter logic                     ExtRegEna     = 1'b0,
  parameter type                      TagType       = logic,
   
  localparam int unsigned NUM_OPERANDS = E6FPU_pkg::num_operands(OpGroup),
  localparam int unsigned NUM_FORMATS  = E6FPU_pkg::NUM_FP_FORMATS,
  localparam int unsigned NUM_SIMD_LANES = E6FPU_pkg::max_num_lanes(Width, FpFmtConfig, EnableVectors),
  localparam type         MaskType     = logic [NUM_SIMD_LANES-1:0],
  localparam int unsigned ExtRegEnaWidth = NumPipeRegs == 0 ? 1 : NumPipeRegs
) (
  input logic                                     clk_i,
  input logic                                     rst_ni,
   
  input logic [NUM_OPERANDS-1:0][Width-1:0]       operands_i,
  input logic [2:0]                               nan_switch_flag,
  input logic [NUM_FORMATS-1:0][NUM_OPERANDS-1:0] is_boxed_i,
  input E6FPU_pkg::roundmode_e                    rnd_mode_i,
  input E6FPU_pkg::operation_e                    op_i,
  input logic                                     op_mod_i,
  input E6FPU_pkg::fp_format_e                    src_fmt_i,
  input E6FPU_pkg::fp_format_e                    dst_fmt_i,
  input E6FPU_pkg::int_format_e                   int_fmt_i,
  input logic                                     vectorial_op_i,
  input TagType                                   tag_i,
  input MaskType                                  simd_mask_i,
   
  input  logic                                    in_valid_i,
  output logic                                    in_ready_o,
  input  logic                                    flush_i,
   
  output logic [Width-1:0]                        result_o,
  output E6FPU_pkg::status_t                      status_o,
  output logic                                    extension_bit_o,
  output TagType                                  tag_o,
   
  output logic                                    out_valid_o,
  input  logic                                    out_ready_i,
   
  output logic                                    busy_o,
   
  output logic                                    fw_out_valid_o,
  output logic [Width-1:0]                        fw_result_o,
  output E6FPU_pkg::status_t                      fw_status_o,
  output TagType                                  fw_tag_o,
   
  input  logic [ExtRegEnaWidth-1:0]               reg_ena_i
);

  if ((OpGroup == E6FPU_pkg::DIVSQRT)) begin
    if ((DivSqrtSel == E6FPU_pkg::TH32) && !((FpFmtConfig[0] == 1) && (FpFmtConfig[1:NUM_FORMATS-1] == '0))) begin
      $fatal(1, "T-Head-based DivSqrt unit supported only in FP32-only configurations. \
Set DivSqrtSel = THMULTI or DivSqrtSel = PULP to use a multi-format divider");
    end else if ((DivSqrtSel == E6FPU_pkg::THMULTI) && (FpFmtConfig[3] == 1'b1)) begin
      $warning("The DivSqrt unit of C910 (instantiated by DivSqrtSel = THMULTI) does not support \
FP8. Please use the PULP DivSqrt unit when in need of div/sqrt operations on FP8.");
    end
  end

  localparam int unsigned MAX_FP_WIDTH   = E6FPU_pkg::max_fp_width(FpFmtConfig);
  localparam int unsigned MAX_INT_WIDTH  = E6FPU_pkg::max_int_width(IntFmtConfig);
  localparam int unsigned NUM_LANES = E6FPU_pkg::max_num_lanes(Width, FpFmtConfig, 1'b1);
  localparam int unsigned NUM_DIVSQRT_LANES = E6FPU_pkg::num_divsqrt_lanes(Width, FpFmtConfig, 1'b1, DivSqrtSel);
  localparam int unsigned NUM_INT_FORMATS = E6FPU_pkg::NUM_INT_FORMATS;
   
  localparam int unsigned FMT_BITS =
      E6FPU_pkg::maximum($clog2(NUM_FORMATS), $clog2(NUM_INT_FORMATS));
  localparam int unsigned AUX_BITS = FMT_BITS + 2;  

  logic [NUM_LANES-1:0] lane_in_ready, lane_out_valid, divsqrt_done, divsqrt_ready;  
  logic                 vectorial_op;
  logic [FMT_BITS-1:0]  dst_fmt;  
  logic [AUX_BITS-1:0]  aux_data;

   
  logic       dst_fmt_is_int, dst_is_cpk;
  logic [1:0] dst_vec_op;  
  logic [2:0] target_aux_d;
  logic       is_up_cast, is_down_cast;

  logic [NUM_FORMATS-1:0][Width-1:0]     fmt_slice_result;
  logic [NUM_INT_FORMATS-1:0][Width-1:0] ifmt_slice_result;

  logic [Width-1:0] conv_target_d, conv_target_q;  

  E6FPU_pkg::status_t [NUM_LANES-1:0]   lane_status;
  logic   [NUM_LANES-1:0]               lane_ext_bit;  
  TagType [NUM_LANES-1:0]               lane_tags;  
  logic   [NUM_LANES-1:0]               lane_masks;
  logic   [NUM_LANES-1:0][AUX_BITS-1:0] lane_aux;  
  logic   [NUM_LANES-1:0]               lane_busy;  
  
  logic   [NUM_LANES-1:0]               fw_out_valid;
  logic   [NUM_LANES-1:0][Width-1:0]    fw_result;
  E6FPU_pkg::status_t [NUM_LANES-1:0]   fw_status;
  TagType [NUM_LANES-1:0]               fw_tag;


  logic                result_is_vector;
  logic [FMT_BITS-1:0] result_fmt;
  logic                result_fmt_is_int, result_is_cpk;
  logic [1:0]          result_vec_op;  

  logic simd_synch_rdy, simd_synch_done;

   
   
   
  assign in_ready_o   = lane_in_ready[0];  
  assign vectorial_op = vectorial_op_i & EnableVectors;  

   
  assign dst_fmt_is_int = (OpGroup == E6FPU_pkg::CONV) & (op_i == E6FPU_pkg::F2I);
  assign dst_is_cpk     = (OpGroup == E6FPU_pkg::CONV) & (op_i == E6FPU_pkg::CPKAB ||
                                                          op_i == E6FPU_pkg::CPKCD);
  assign dst_vec_op     = (OpGroup == E6FPU_pkg::CONV) & {(op_i == E6FPU_pkg::CPKCD), op_mod_i};

  assign is_up_cast   = (E6FPU_pkg::fp_width(dst_fmt_i) > E6FPU_pkg::fp_width(src_fmt_i));
  assign is_down_cast = (E6FPU_pkg::fp_width(dst_fmt_i) < E6FPU_pkg::fp_width(src_fmt_i));

   
  assign dst_fmt    = dst_fmt_is_int ? int_fmt_i : dst_fmt_i;

   
  assign aux_data      = {dst_fmt_is_int, vectorial_op, dst_fmt};
  assign target_aux_d  = {dst_vec_op, dst_is_cpk};

   
  if (OpGroup == E6FPU_pkg::CONV) begin : conv_target
    assign conv_target_d = dst_is_cpk ? operands_i[2] : operands_i[1];
  end else begin : not_conv_target
    assign conv_target_d = '0;
  end

   
  logic [NUM_FORMATS-1:0]      is_boxed_1op;
  logic [NUM_FORMATS-1:0][1:0] is_boxed_2op;

  always_comb begin : boxed_2op
    for (int fmt = 0; fmt < NUM_FORMATS; fmt++) begin
      is_boxed_1op[fmt] = is_boxed_i[fmt][0];
      is_boxed_2op[fmt] = is_boxed_i[fmt][1:0];
    end
  end

   
   
   
  for (genvar lane = 0; lane < int'(NUM_LANES); lane++) begin : gen_num_lanes
    localparam int unsigned LANE = unsigned'(lane);  
     
    localparam E6FPU_pkg::fmt_logic_t ACTIVE_FORMATS =
        E6FPU_pkg::get_lane_formats(Width, FpFmtConfig, LANE);
    localparam E6FPU_pkg::ifmt_logic_t ACTIVE_INT_FORMATS =
        E6FPU_pkg::get_lane_int_formats(Width, FpFmtConfig, IntFmtConfig, LANE);
    localparam int unsigned MAX_WIDTH = E6FPU_pkg::max_fp_width(ACTIVE_FORMATS);

     
    localparam E6FPU_pkg::fmt_logic_t CONV_FORMATS =
        E6FPU_pkg::get_conv_lane_formats(Width, FpFmtConfig, LANE);
    localparam E6FPU_pkg::ifmt_logic_t CONV_INT_FORMATS =
        E6FPU_pkg::get_conv_lane_int_formats(Width, FpFmtConfig, IntFmtConfig, LANE);
    localparam int unsigned CONV_WIDTH = E6FPU_pkg::max_fp_width(CONV_FORMATS);

     
    localparam E6FPU_pkg::fmt_logic_t LANE_FORMATS = (OpGroup == E6FPU_pkg::CONV)
                                                     ? CONV_FORMATS : ACTIVE_FORMATS;
    localparam int unsigned LANE_WIDTH = (OpGroup == E6FPU_pkg::CONV) ? CONV_WIDTH : MAX_WIDTH;

    logic [LANE_WIDTH-1:0] local_result;  

     
    if ((lane == 0) || (EnableVectors & (!(OpGroup == E6FPU_pkg::DIVSQRT && (lane >= NUM_DIVSQRT_LANES))))) begin : active_lane
      logic in_valid, out_valid, out_ready;  

      logic [NUM_OPERANDS-1:0][LANE_WIDTH-1:0] local_operands;   
      logic [LANE_WIDTH-1:0]                   op_result;        
      E6FPU_pkg::status_t                      op_status;

      assign in_valid = in_valid_i & ((lane == 0) | vectorial_op);  

       
      always_comb begin : prepare_input
        for (int unsigned i = 0; i < NUM_OPERANDS; i++) begin
          if (i == 2) begin
            local_operands[i] = operands_i[i] >> LANE*E6FPU_pkg::fp_width(op_i == E6FPU_pkg::ADDS ? src_fmt_i : dst_fmt_i);
          end else begin
            local_operands[i] = operands_i[i] >> LANE*E6FPU_pkg::fp_width(src_fmt_i);
          end
        end

         
        if (OpGroup == E6FPU_pkg::CONV) begin
           
          if (op_i == E6FPU_pkg::I2F) begin
            local_operands[0] = operands_i[0] >> LANE*E6FPU_pkg::int_width(int_fmt_i);
           
          end else if (op_i == E6FPU_pkg::F2F) begin
            if (vectorial_op && op_mod_i && is_up_cast) begin  
              local_operands[0] = operands_i[0] >> LANE*E6FPU_pkg::fp_width(src_fmt_i) +
                                                   MAX_FP_WIDTH/2;
            end
           
          end else if (dst_is_cpk) begin
            if (lane == 1) begin
              local_operands[0] = operands_i[1][LANE_WIDTH-1:0];  
            end
          end
        end
      end

       
      if (OpGroup == E6FPU_pkg::ADDMUL) begin : lane_instance
        fpnew_fma_multi #(
          .FpFmtConfig ( LANE_FORMATS         ),
          .NumPipeRegs ( NumPipeRegs          ),
          .PipeConfig  ( PipeConfig           ),
          .TagType     ( TagType              ),
          .AuxType     ( logic [AUX_BITS-1:0] )
        ) i_fpnew_fma_multi (
          .clk_i,
          .rst_ni,
          .operands_i      ( local_operands                                  ),
          .is_boxed_i,
          .rnd_mode_i,
          .op_i,
          .op_mod_i,
          .src_fmt_i,
          .src2_fmt_i      ( op_i == E6FPU_pkg::ADDS ? src_fmt_i : dst_fmt_i ),
          .dst_fmt_i,
          .tag_i,
          .mask_i          ( simd_mask_i[lane]                               ),
          .aux_i           ( aux_data                                        ),
          .in_valid_i      ( in_valid                                        ),
          .in_ready_o      ( lane_in_ready[lane]                             ),
          .flush_i,
          .result_o        ( op_result                                       ),
          .status_o        ( op_status                                       ),
          .extension_bit_o ( lane_ext_bit[lane]                              ),
          .tag_o           ( lane_tags[lane]                                 ),
          .mask_o          ( lane_masks[lane]                                ),
          .aux_o           ( lane_aux[lane]                                  ),
          .out_valid_o     ( out_valid                                       ),
          .out_ready_i     ( out_ready                                       ),
          .fw_out_valid_o  ( fw_out_valid[lane]                              ),
          .fw_result_o     ( fw_result[lane]                                 ),
          .fw_status_o     ( fw_status[lane]                                 ),
          .fw_tag_o        ( fw_tag[lane]                                    ),
          .busy_o          ( lane_busy[lane]                                 ),
          .reg_ena_i
        );

      end else if (OpGroup == E6FPU_pkg::DIVSQRT) begin : lane_instance
         if (DivSqrtSel == E6FPU_pkg::TH32 && LANE_FORMATS[0] && (LANE_FORMATS[1:E6FPU_pkg::NUM_FP_FORMATS-1] == '0)) begin : gen_th32_e906_divsqrt
           
          fpnew_divsqrt_th_32 #(
            .NumPipeRegs ( NumPipeRegs          ),
            .PipeConfig  ( PipeConfig           ),
            .TagType     ( TagType              ),
            .AuxType     ( logic [AUX_BITS-1:0] )
          ) i_fpnew_divsqrt_multi_th (
            .clk_i,
            .rst_ni,
            .operands_i      ( local_operands[1:0] ),  
            .is_boxed_i      ( is_boxed_2op        ),  
            .rnd_mode_i,
            .op_i,
            .tag_i,
            .mask_i          ( simd_mask_i[lane]   ),
            .aux_i           ( aux_data            ),
            .in_valid_i      ( in_valid            ),
            .in_ready_o      ( lane_in_ready[lane] ),
            .flush_i,
            .result_o        ( op_result           ),
            .status_o        ( op_status           ),
            .extension_bit_o ( lane_ext_bit[lane]  ),
            .tag_o           ( lane_tags[lane]     ),
            .mask_o          ( lane_masks[lane]    ),
            .aux_o           ( lane_aux[lane]      ),
            .out_valid_o     ( out_valid           ),
            .out_ready_i     ( out_ready           ),
            .busy_o          ( lane_busy[lane]     ),
            .reg_ena_i
          );

        end else if(DivSqrtSel == E6FPU_pkg::THMULTI) begin : gen_thmulti_c910_divsqrt
          fpnew_divsqrt_th_64_multi #(
            .FpFmtConfig ( LANE_FORMATS         ),
            .NumPipeRegs ( NumPipeRegs          ),
            .PipeConfig  ( PipeConfig           ),
            .TagType     ( TagType              ),
            .AuxType     ( logic [AUX_BITS-1:0] )
          ) i_fpnew_divsqrt_th_64_c910 (
           .clk_i,
            .rst_ni,
            .operands_i       ( local_operands[1:0] ),  
            .is_boxed_i       ( is_boxed_2op        ),  
            .nan_switch_flag  ( nan_switch_flag                 ),
            .rnd_mode_i,
            .op_i,
            .dst_fmt_i,
            .tag_i,
            .mask_i           ( simd_mask_i[lane]   ),
            .aux_i            ( aux_data            ),
            .vectorial_op_i   ( vectorial_op        ),  
            .in_valid_i       ( in_valid            ),
            .in_ready_o       ( lane_in_ready[lane] ),
            .divsqrt_done_o   ( divsqrt_done[lane]  ),
            .simd_synch_done_i( simd_synch_done     ),
            .divsqrt_ready_o  ( divsqrt_ready[lane] ),
            .simd_synch_rdy_i ( simd_synch_rdy      ),
            .flush_i,
            .result_o         ( op_result           ),
            .status_o         ( op_status           ),
            .extension_bit_o  ( lane_ext_bit[lane]  ),
            .tag_o            ( lane_tags[lane]     ),
            .mask_o           ( lane_masks[lane]    ),
            .aux_o            ( lane_aux[lane]      ),
            .out_valid_o      ( out_valid           ),
            .out_ready_i      ( out_ready           ),
            .busy_o           ( lane_busy[lane]     ),
            .reg_ena_i
          );
        end else begin : gen_pulp_divsqrt
          fpnew_divsqrt_multi #(
            .FpFmtConfig ( LANE_FORMATS         ),
            .NumPipeRegs ( NumPipeRegs          ),
            .PipeConfig  ( PipeConfig           ),
            .TagType     ( TagType              ),
            .AuxType     ( logic [AUX_BITS-1:0] )
          ) i_fpnew_divsqrt_multi (
            .clk_i,
            .rst_ni,
            .operands_i       ( local_operands[1:0] ),  
            .is_boxed_i       ( is_boxed_2op        ),  
            .rnd_mode_i,
            .op_i,
            .dst_fmt_i,
            .tag_i,
            .mask_i           ( simd_mask_i[lane]   ),
            .aux_i            ( aux_data            ),
            .vectorial_op_i   ( vectorial_op        ),
            .in_valid_i       ( in_valid            ),
            .in_ready_o       ( lane_in_ready[lane] ),
            .divsqrt_done_o   ( divsqrt_done[lane]  ),
            .simd_synch_done_i( simd_synch_done     ),
            .divsqrt_ready_o  ( divsqrt_ready[lane] ),
            .simd_synch_rdy_i ( simd_synch_rdy      ),
            .flush_i,
            .result_o         ( op_result           ),
            .status_o         ( op_status           ),
            .extension_bit_o  ( lane_ext_bit[lane]  ),
            .tag_o            ( lane_tags[lane]     ),
            .mask_o           ( lane_masks[lane]    ),
            .aux_o            ( lane_aux[lane]      ),
            .out_valid_o      ( out_valid           ),
            .out_ready_i      ( out_ready           ),
            .busy_o           ( lane_busy[lane]     ),
            .reg_ena_i
          );
        end

        assign fw_out_valid[lane]   = 1'b0;
        assign fw_result[lane]      = '{default: E6FPU_pkg::DONT_CARE};
        assign fw_status[lane]      = '{default: E6FPU_pkg::DONT_CARE};
        assign fw_tag[lane]         = TagType'(E6FPU_pkg::DONT_CARE);

      end else if (OpGroup == E6FPU_pkg::NONCOMP) begin : lane_instance

        assign fw_out_valid[lane]   = 1'b0;
        assign fw_result[lane]      = '{default: E6FPU_pkg::DONT_CARE};
        assign fw_status[lane]      = '{default: E6FPU_pkg::DONT_CARE};
        assign fw_tag[lane]         = TagType'(E6FPU_pkg::DONT_CARE);

      end else if (OpGroup == E6FPU_pkg::CONV) begin : lane_instance
        fpnew_cast_multi #(
          .FpFmtConfig  ( LANE_FORMATS         ),
          .IntFmtConfig ( CONV_INT_FORMATS     ),
          .NumPipeRegs  ( NumPipeRegs          ),
          .PipeConfig   ( PipeConfig           ),
          .TagType      ( TagType              ),
          .AuxType      ( logic [AUX_BITS-1:0] )
        ) i_fpnew_cast_multi (
          .clk_i,
          .rst_ni,
          .operands_i      ( local_operands[0]   ),
          .is_boxed_i      ( is_boxed_1op        ),
          .rnd_mode_i,
          .op_i,
          .op_mod_i,
          .src_fmt_i,
          .dst_fmt_i,
          .int_fmt_i,
          .tag_i,
          .mask_i          ( simd_mask_i[lane]   ),
          .aux_i           ( aux_data            ),
          .in_valid_i      ( in_valid            ),
          .in_ready_o      ( lane_in_ready[lane] ),
          .flush_i,
          .result_o        ( op_result           ),
          .status_o        ( op_status           ),
          .extension_bit_o ( lane_ext_bit[lane]  ),
          .tag_o           ( lane_tags[lane]     ),
          .mask_o          ( lane_masks[lane]    ),
          .aux_o           ( lane_aux[lane]      ),
          .out_valid_o     ( out_valid           ),
          .out_ready_i     ( out_ready           ),
          .busy_o          ( lane_busy[lane]     ),
          .reg_ena_i
        );

        assign fw_out_valid[lane]   = 1'b0;
        assign fw_result[lane]      = '{default: E6FPU_pkg::DONT_CARE};
        assign fw_status[lane]      = '{default: E6FPU_pkg::DONT_CARE};
        assign fw_tag[lane]         = TagType'(E6FPU_pkg::DONT_CARE);

      end  

       
      assign out_ready            = out_ready_i & ((lane == 0) | result_is_vector);
      assign lane_out_valid[lane] = out_valid & ((lane == 0) | result_is_vector);

       
      assign local_result      = (lane_out_valid[lane] | ExtRegEna) ? op_result : '{default: lane_ext_bit[0]};
      assign lane_status[lane] = (lane_out_valid[lane] | ExtRegEna) ? op_status : '0;

     
    end else begin : inactive_lane
      assign lane_out_valid[lane] = 1'b0;  
      assign lane_in_ready[lane]  = 1'b0;  
      assign lane_aux[lane]       = 1'b0;  
      assign lane_masks[lane]     = 1'b1;  
      assign lane_tags[lane]      = 1'b0;  
      assign divsqrt_done[lane]   = 1'b0;  
      assign divsqrt_ready[lane]  = 1'b0;  
      assign lane_ext_bit[lane]   = 1'b1;  
      assign local_result         = {(LANE_WIDTH){lane_ext_bit[0]}};  
      assign lane_status[lane]    = '0;
      assign lane_busy[lane]      = 1'b0;
      assign fw_out_valid[lane]   = 1'b0;
      assign fw_result[lane]      = '{default: E6FPU_pkg::DONT_CARE};
      assign fw_status[lane]      = '{default: E6FPU_pkg::DONT_CARE};
      assign fw_tag[lane]         = TagType'(E6FPU_pkg::DONT_CARE);
    end

     
    for (genvar fmt = 0; fmt < NUM_FORMATS; fmt++) begin : pack_fp_result
       
      localparam int unsigned FP_WIDTH = E6FPU_pkg::fp_width(E6FPU_pkg::fp_format_e'(fmt));
       
      if (ACTIVE_FORMATS[fmt]) begin
        assign fmt_slice_result[fmt][(LANE+1)*FP_WIDTH-1:LANE*FP_WIDTH] =
            local_result[FP_WIDTH-1:0];
      end else if ((LANE+1)*FP_WIDTH <= Width) begin
        assign fmt_slice_result[fmt][(LANE+1)*FP_WIDTH-1:LANE*FP_WIDTH] =
            '{default: lane_ext_bit[LANE]};
      end else if (LANE*FP_WIDTH < Width) begin
        assign fmt_slice_result[fmt][Width-1:LANE*FP_WIDTH] =
            '{default: lane_ext_bit[LANE]};
      end
    end

     
    if (OpGroup == E6FPU_pkg::CONV) begin : int_results_enabled
      for (genvar ifmt = 0; ifmt < NUM_INT_FORMATS; ifmt++) begin : pack_int_result
         
        localparam int unsigned INT_WIDTH = E6FPU_pkg::int_width(E6FPU_pkg::int_format_e'(ifmt));
        if (ACTIVE_INT_FORMATS[ifmt]) begin
          assign ifmt_slice_result[ifmt][(LANE+1)*INT_WIDTH-1:LANE*INT_WIDTH] =
            local_result[INT_WIDTH-1:0];
        end else if ((LANE+1)*INT_WIDTH <= Width) begin
          assign ifmt_slice_result[ifmt][(LANE+1)*INT_WIDTH-1:LANE*INT_WIDTH] = '0;
        end else if (LANE*INT_WIDTH < Width) begin
          assign ifmt_slice_result[ifmt][Width-1:LANE*INT_WIDTH] = '0;
        end
      end
    end
  end

   
  for (genvar fmt = 0; fmt < NUM_FORMATS; fmt++) begin : extend_fp_result
     
    localparam int unsigned FP_WIDTH = E6FPU_pkg::fp_width(E6FPU_pkg::fp_format_e'(fmt));
    if (NUM_LANES*FP_WIDTH < Width)
      assign fmt_slice_result[fmt][Width-1:NUM_LANES*FP_WIDTH] = '{default: lane_ext_bit[0]};
  end

  for (genvar ifmt = 0; ifmt < NUM_INT_FORMATS; ifmt++) begin : extend_or_mute_int_result
     
    if (OpGroup != E6FPU_pkg::CONV) begin : mute_int_result
      assign ifmt_slice_result[ifmt] = '0;

     
    end else begin : extend_int_result
       
      localparam int unsigned INT_WIDTH = E6FPU_pkg::int_width(E6FPU_pkg::int_format_e'(ifmt));
      if (NUM_LANES*INT_WIDTH < Width)
        assign ifmt_slice_result[ifmt][Width-1:NUM_LANES*INT_WIDTH] = '0;
    end
  end

   
  if (OpGroup == E6FPU_pkg::CONV) begin : target_regs
     
    logic [0:NumPipeRegs][Width-1:0] byp_pipe_target_q;
    logic [0:NumPipeRegs][2:0]       byp_pipe_aux_q;
    logic [0:NumPipeRegs]            byp_pipe_valid_q;
     
    logic [0:NumPipeRegs] byp_pipe_ready;

     
    assign byp_pipe_target_q[0]  = conv_target_d;
    assign byp_pipe_aux_q[0]     = target_aux_d;
    assign byp_pipe_valid_q[0]   = in_valid_i & vectorial_op;
     
    for (genvar i = 0; i < NumPipeRegs; i++) begin : gen_bypass_pipeline
       
      logic reg_ena;
       
       
       
      assign byp_pipe_ready[i] = byp_pipe_ready[i+1] | ~byp_pipe_valid_q[i+1];
       
      `FFLARNC(byp_pipe_valid_q[i+1], byp_pipe_valid_q[i], byp_pipe_ready[i], flush_i, 1'b0, clk_i, rst_ni)
       
      assign reg_ena = (byp_pipe_ready[i] & byp_pipe_valid_q[i]) | reg_ena_i[i];
       
      `FFL(byp_pipe_target_q[i+1],  byp_pipe_target_q[i],  reg_ena, '0)
      `FFL(byp_pipe_aux_q[i+1],     byp_pipe_aux_q[i],     reg_ena, '0)
    end
     
    assign byp_pipe_ready[NumPipeRegs] = out_ready_i & result_is_vector;
     
    assign conv_target_q = byp_pipe_target_q[NumPipeRegs];

     
    assign {result_vec_op, result_is_cpk} = byp_pipe_aux_q[NumPipeRegs];
  end else begin : no_conv
    assign {result_vec_op, result_is_cpk} = '0;
    assign conv_target_q = '0;
  end

  if ((DivSqrtSel != E6FPU_pkg::TH32) && !ExtRegEna) begin
     
    assign simd_synch_rdy  = EnableVectors ? &divsqrt_ready[NUM_DIVSQRT_LANES-1:0] : divsqrt_ready[0];
    assign simd_synch_done = EnableVectors ? &divsqrt_done[NUM_DIVSQRT_LANES-1:0]  : divsqrt_done[0];
  end else begin
     
    assign simd_synch_rdy  = '0;
    assign simd_synch_done = '0;
  end

   
   
   
  assign {result_fmt_is_int, result_is_vector, result_fmt} = lane_aux[0];

  assign result_o = result_fmt_is_int
                    ? ifmt_slice_result[result_fmt]
                    : fmt_slice_result[result_fmt];

  assign extension_bit_o = lane_ext_bit[0];  
  assign tag_o           = lane_tags[0];     
  assign busy_o          = (| lane_busy);

  assign out_valid_o     = lane_out_valid[0];  

   
  always_comb begin : output_processing
     
    automatic E6FPU_pkg::status_t temp_status;
    temp_status = '0;
    for (int i = 0; i < int'(NUM_LANES); i++)
      temp_status |= lane_status[i] & {5{lane_masks[i]}};
    status_o = temp_status;
  end

  assign fw_out_valid_o   = fw_out_valid[0];
  assign fw_result_o      = fw_result[0];
  assign fw_status_o      = fw_status[0];
  assign fw_tag_o         = fw_tag[0];

endmodule

module ex_fpu_addmul
#(parameter VLEN           = `VLEN,
  parameter DIRTY_WIDTH    = 2 ,
  parameter TAG_WIDTH      = `TAG_WIDTH 
)
(
    input logic clk,
    input logic rst_l,

     
     
    input logic         rs_fpu_valid,
    input fpu_pkt_t     rs_fpu_p,                    
    input logic  [63:0] rs_fpu_rs1_d,                
    input logic  [63:0] rs_fpu_rs2_d,                
    input logic  [63:0] rs_fpu_fs1_d,                
    input logic  [63:0] rs_fpu_fs2_d,                
    input logic  [63:0] rs_fpu_fs3_d,                
    input logic  [TAG_WIDTH-1:0] rs_fpu_tag,
    input logic  [7:0]  rs_fflags,
    input logic  [2:0]  rs_frm,
    input logic  [2:0]  rs_rm,

     
    output logic        fpu_fu_ready,

     
    input logic exu_flush_final,

     
     
    output logic                 exu_fpu_valid,  
    input logic                  exu_fpu_ready,        
    output logic [63:0]          exu_fpu_result,
    output logic                 exu_fpu_result_x,
    output logic                 exu_fpu_result_f,
    output logic [4:0]           exu_fpu_csr,
    output logic [TAG_WIDTH-1:0] exu_fpu_tag,
    
     
    output logic                 fadd_fw_valid,        
    output logic [63:0]          fadd_fw_result,
    output logic                 fadd_fw_result_x,
    output logic                 fadd_fw_result_f,
    output logic [TAG_WIDTH-1:0] fadd_fw_tag                                   
);

localparam int unsigned NUM_OPERANDS = 3 ;
localparam int unsigned WIDTH        = 64;

logic [NUM_OPERANDS-1:0][WIDTH-1:0] operands_i;
E6FPU_pkg::roundmode_e              rnd_mode_i;
E6FPU_pkg::operation_e              op_i;
logic                               op_mod_i;
E6FPU_pkg::fp_format_e              src_fmt_i;
E6FPU_pkg::fp_format_e              dst_fmt_i;
