    operands_i[0][WIDTH-1:0] = fs1;
    operands_i[1][WIDTH-1:0] = fs2;
    operands_i[2][WIDTH-1:0] = fs3;

    op_i                     = E6FPU_pkg::FNMSUB;
    op_mod_i                 = 1'b0;
  end else if(fp.fp_fnmadd) begin
    operands_i[0][WIDTH-1:0] = fs1;
    operands_i[1][WIDTH-1:0] = fs2;
    operands_i[2][WIDTH-1:0] = fs3;

    op_i                     = E6FPU_pkg::FNMSUB;
