module ct_vfdsu_prepare(
  cp0_vfpu_icg_en,
  cp0_yy_clk_en,
  cpurst_b,
  nan_switch_flag,    
  ex1_div,
  ex1_divisor,
  ex1_double,
  ex1_pipedown,
  ex1_remainder,
  ex1_scalar,
  ex1_single,
  ex1_half,
  ex1_bfloat,
  ex1_sqrt,
  ex1_src0,
  ex1_src1,
  ex1_static_rm,
  forever_cpuclk,
  pad_yy_icg_scan_en,
  vfdsu_ex2_div,
  vfdsu_ex2_double,
  vfdsu_ex2_dz,
  vfdsu_ex2_expnt_add0,
  vfdsu_ex2_expnt_add1,
  vfdsu_ex2_nv,
  vfdsu_ex2_of_rm_lfn,
  vfdsu_ex2_op0_norm,
  vfdsu_ex2_op1_norm,
  vfdsu_ex2_qnan_f,
  vfdsu_ex2_qnan_sign,
  vfdsu_ex2_result_inf,
  vfdsu_ex2_result_qnan,
  vfdsu_ex2_result_sign,
  vfdsu_ex2_result_zero,
  vfdsu_ex2_rm,
  vfdsu_ex2_single,
  vfdsu_ex2_half,
  vfdsu_ex2_bfloat,
  vfdsu_ex2_sqrt,
  vfdsu_ex2_srt_skip,
  vfpu_yy_xx_dqnan,
  vfpu_yy_xx_rm
);

 
input           cp0_vfpu_icg_en;          
input           cp0_yy_clk_en;            
input           cpurst_b;                 
input  [2 :0]   nan_switch_flag;
input           ex1_div;                  
input           ex1_double;               
input           ex1_pipedown;             
input           ex1_scalar;               
input           ex1_single;               
input           ex1_half;
input           ex1_bfloat;
input           ex1_sqrt;                 
input   [63:0]  ex1_src0;                 
input   [63:0]  ex1_src1;                 
input   [2 :0]  ex1_static_rm;            
input           forever_cpuclk;           
input           pad_yy_icg_scan_en;       
input           vfpu_yy_xx_dqnan;         
input   [2 :0]  vfpu_yy_xx_rm;            
output  [52:0]  ex1_divisor;              
output  [59:0]  ex1_remainder;            
output          vfdsu_ex2_div;            
output          vfdsu_ex2_double;         
output          vfdsu_ex2_dz;             
output  [12:0]  vfdsu_ex2_expnt_add0;     
output  [12:0]  vfdsu_ex2_expnt_add1;     
output          vfdsu_ex2_nv;             
output          vfdsu_ex2_of_rm_lfn;      
output          vfdsu_ex2_op0_norm;       
output          vfdsu_ex2_op1_norm;       
output  [51:0]  vfdsu_ex2_qnan_f;         
output          vfdsu_ex2_qnan_sign;      
output          vfdsu_ex2_result_inf;     
output          vfdsu_ex2_result_qnan;    
output          vfdsu_ex2_result_sign;    
output          vfdsu_ex2_result_zero;    
output  [2 :0]  vfdsu_ex2_rm;             
output          vfdsu_ex2_single;         
output          vfdsu_ex2_half;
output          vfdsu_ex2_bfloat;
output          vfdsu_ex2_sqrt;           
output          vfdsu_ex2_srt_skip;       

 
reg     [12:0]  ex1_expnt_adder_op1;      
reg             ex1_of_result_lfn;        
reg     [51:0]  ex1_qnan_f;               
reg             ex1_qnan_sign;            
reg             vfdsu_ex2_div;            
reg             vfdsu_ex2_double;         
reg             vfdsu_ex2_dz;             
reg     [12:0]  vfdsu_ex2_expnt_add0;     
reg     [12:0]  vfdsu_ex2_expnt_add1;     
reg             vfdsu_ex2_nv;             
reg             vfdsu_ex2_of_rm_lfn;      
reg             vfdsu_ex2_op0_norm;       
reg             vfdsu_ex2_op1_norm;       
reg     [51:0]  vfdsu_ex2_qnan_f;         
reg             vfdsu_ex2_qnan_sign;      
reg             vfdsu_ex2_result_inf;     
reg             vfdsu_ex2_result_qnan;    
reg             vfdsu_ex2_result_sign;    
reg             vfdsu_ex2_result_zero;    
reg     [2 :0]  vfdsu_ex2_rm;             
reg             vfdsu_ex2_single;         
reg             vfdsu_ex2_half;
reg             vfdsu_ex2_bfloat;
reg             vfdsu_ex2_sqrt;           
reg             vfdsu_ex2_srt_skip;       

 
wire            cp0_vfpu_icg_en;          
wire            cp0_yy_clk_en;            
wire            cpurst_b;                 
wire            div_sign;                 
wire            ex1_div;                  
wire            ex1_div_dz;               
wire    [52:0]  ex1_div_noid_nor_srt_op0; 
wire    [52:0]  ex1_div_noid_nor_srt_op1; 
wire    [52:0]  ex1_div_nor_srt_op0;      
wire    [52:0]  ex1_div_nor_srt_op1;      
wire            ex1_div_nv;               
wire    [12:0]  ex1_div_op0_expnt;        
wire    [12:0]  ex1_div_op1_expnt;        
wire            ex1_div_rst_inf;          
wire            ex1_div_rst_qnan;         
wire            ex1_div_rst_zero;         
wire    [52:0]  ex1_div_srt_op0;          
wire    [52:0]  ex1_div_srt_op1;          
wire    [52:0]  ex1_divisor;              
wire            ex1_doub_expnt0_max;      
wire            ex1_doub_expnt0_zero;     
wire            ex1_doub_expnt1_max;      
wire            ex1_doub_expnt1_zero;     
wire            ex1_doub_frac0_all0;      
wire            ex1_doub_frac1_all0;      
wire            ex1_double;               
wire            ex1_dz;                   
wire            ex1_expnt0_max;           
wire            ex1_expnt0_zero;          
wire            ex1_expnt1_max;           
wire            ex1_expnt1_zero;          
wire    [12:0]  ex1_expnt_adder_op0;      
wire            ex1_frac0_all0;           
wire            ex1_frac0_msb;            
wire            ex1_frac1_all0;           
wire            ex1_frac1_msb;            
wire            ex1_half_expnt0_max;      
wire            ex1_half_expnt0_zero;     
wire            ex1_half_expnt1_max;      
wire            ex1_half_expnt1_zero;     
wire            ex1_half_frac0_all0;      
wire            ex1_half_frac1_all0;      
wire            ex1_bfloat_expnt0_max;
wire            ex1_bfloat_expnt1_max;
wire            ex1_bfloat_expnt0_zero;
wire            ex1_bfloat_expnt1_zero;
wire            ex1_bfloat_frac0_all0;
wire            ex1_bfloat_frac1_all0;
wire            ex1_nv;                   
wire            ex1_op0_cnan;             
wire    [51:0]  ex1_op0_f;                
wire            ex1_op0_id;               
wire            ex1_op0_id_nor;           
wire            ex1_op0_inf;              
wire            ex1_op0_is_qnan;          
wire            ex1_op0_is_snan;          
wire            ex1_op0_norm;             
wire            ex1_op0_qnan;             
wire            ex1_op0_sign;             
wire            ex1_op0_snan;             
wire            ex1_op0_tt_zero;          
wire            ex1_op0_zero;             
wire            ex1_op1_cnan;             
wire    [51:0]  ex1_op1_f;                
wire            ex1_op1_id;               
wire            ex1_op1_id_nor;           
wire            ex1_op1_inf;              
wire            ex1_op1_is_qnan;          
wire            ex1_op1_is_snan;          
wire            ex1_op1_norm;             
wire            ex1_op1_qnan;             
wire            ex1_op1_sign;             
wire            ex1_op1_snan;             
wire            ex1_op1_tt_zero;          
wire            ex1_op1_zero;             
wire    [63:0]  ex1_oper0;                
wire    [51:0]  ex1_oper0_frac;           
wire            ex1_oper0_high_all1;      
wire    [12:0]  ex1_oper0_id_expnt;       
wire    [51:0]  ex1_oper0_id_frac;        
wire    [63:0]  ex1_oper1;                
wire    [51:0]  ex1_oper1_frac;           
wire            ex1_oper1_high_all1;      
wire    [12:0]  ex1_oper1_id_expnt;       
wire    [51:0]  ex1_oper1_id_frac;        
wire            ex1_pipe_clk;             
wire            ex1_pipe_clk_en;          
wire            ex1_pipedown;             
wire    [59:0]  ex1_remainder;            
wire            ex1_result_inf;           
wire            ex1_result_qnan;          
wire            ex1_result_sign;          
wire            ex1_result_zero;          
wire    [2 :0]  ex1_rm;                   
wire            ex1_rst_default_qnan;     
wire            ex1_scalar;               
wire            ex1_sing_expnt0_max;      
wire            ex1_sing_expnt0_zero;     
wire            ex1_sing_expnt1_max;      
wire            ex1_sing_expnt1_zero;     
wire            ex1_sing_frac0_all0;      
wire            ex1_sing_frac1_all0;      
wire            ex1_single;               
wire            ex1_half;
wire            ex1_bfloat;
wire            ex1_sqrt;                 
wire            ex1_sqrt_expnt_odd;       
wire            ex1_sqrt_expnt_result_odd; 
wire            ex1_sqrt_nv;              
wire    [12:0]  ex1_sqrt_op1_expnt;       
wire            ex1_sqrt_rst_inf;         
wire            ex1_sqrt_rst_qnan;        
wire            ex1_sqrt_rst_zero;        
wire    [52:0]  ex1_sqrt_srt_op0;         
wire    [63:0]  ex1_src0;                 
wire    [63:0]  ex1_src1;                 
wire            ex1_srt_skip;             
wire    [2 :0]  ex1_static_rm;            
wire            forever_cpuclk;           
wire            pad_yy_icg_scan_en;       
wire    [59:0]  sqrt_remainder;           
wire            sqrt_sign;                
wire            vfpu_yy_xx_dqnan;         
wire    [2 :0]  vfpu_yy_xx_rm;            

 
wire    [63:0]  ex1_oper0_nan,ex1_oper1_nan,nan; 
wire    [2 :0]  nan_switch_flag; 
wire            ex1_opnan0_sign;
wire            ex1_opnan1_sign;

 
assign nan = ex1_double ? 64'h7ff8000000000000 : 
             ex1_single ? 64'hffffffff7fc00000 : 64'hffffffffffff7e00;

 
 

 
assign ex1_oper0[63:0]             = nan_switch_flag[0] ? nan[63:0] : ex1_src0[63:0];
assign ex1_oper1[63:0]             = nan_switch_flag[1] ? nan[63:0] : ex1_src1[63:0];

assign ex1_oper0_nan[63:0]         = ex1_src0[63:0];
assign ex1_oper1_nan[63:0]         = ex1_src1[63:0];

 
 


 
assign ex1_op0_sign                =  ex1_double ? ex1_oper0[63] :
                                      ex1_single ? ex1_oper0[31] :
                                      ex1_half   ? ex1_oper0[15] : ex1_oper0[15];
assign ex1_op1_sign                =  ex1_double ? ex1_oper1[63] :
                                      ex1_single ? ex1_oper1[31] :
                                      ex1_half   ? ex1_oper1[15] : ex1_oper1[15];
assign div_sign                    = ex1_op0_sign ^ ex1_op1_sign;
assign sqrt_sign                   = ex1_op0_sign;
assign ex1_result_sign             = (ex1_div)
                                   ? div_sign 
                                   : sqrt_sign;
 
assign ex1_doub_expnt0_max         = &ex1_oper0[62:52];
assign ex1_sing_expnt0_max         = &ex1_oper0[30:23];
assign ex1_doub_expnt1_max         = &ex1_oper1[62:52];
assign ex1_sing_expnt1_max         = &ex1_oper1[30:23];
assign ex1_half_expnt0_max         = &ex1_oper0[14:10];
assign ex1_half_expnt1_max         = &ex1_oper1[14:10];
assign ex1_bfloat_expnt0_max       = &ex1_oper0[14:7];
assign ex1_bfloat_expnt1_max       = &ex1_oper1[14:7];
assign ex1_expnt0_max              = ex1_double ? ex1_doub_expnt0_max :
                                     ex1_single ? ex1_sing_expnt0_max :
                                     ex1_half   ? ex1_half_expnt0_max : ex1_bfloat_expnt0_max;
assign ex1_expnt1_max              = ex1_double ? ex1_doub_expnt1_max :
                                     ex1_single ? ex1_sing_expnt1_max :
                                     ex1_half   ? ex1_half_expnt1_max : ex1_bfloat_expnt1_max;

             
 
assign ex1_doub_expnt0_zero        = ~|ex1_oper0[62:52];
assign ex1_sing_expnt0_zero        = ~|ex1_oper0[30:23];
assign ex1_doub_expnt1_zero        = ~|ex1_oper1[62:52];
assign ex1_sing_expnt1_zero        = ~|ex1_oper1[30:23];
assign ex1_half_expnt0_zero        = ~|ex1_oper0[14:10];
assign ex1_half_expnt1_zero        = ~|ex1_oper1[14:10];
assign ex1_bfloat_expnt0_zero      = ~|ex1_oper0[14:7];
assign ex1_bfloat_expnt1_zero      = ~|ex1_oper1[14:7];
assign ex1_expnt0_zero             = ex1_double ? ex1_doub_expnt0_zero :
                                     ex1_single ? ex1_sing_expnt0_zero :
                                     ex1_half   ? ex1_half_expnt0_zero : ex1_bfloat_expnt0_zero;
assign ex1_expnt1_zero             = ex1_double ? ex1_doub_expnt1_zero :
                                     ex1_single ? ex1_sing_expnt1_zero :
                                     ex1_half   ? ex1_half_expnt1_zero : ex1_bfloat_expnt1_zero;

 
assign ex1_doub_frac0_all0         = ~|ex1_oper0[51:0];
assign ex1_sing_frac0_all0         = ~|ex1_oper0[22:0];
assign ex1_doub_frac1_all0         = ~|ex1_oper1[51:0];
assign ex1_sing_frac1_all0         = ~|ex1_oper1[22:0];
assign ex1_half_frac0_all0         = ~|ex1_oper0[9:0];
assign ex1_half_frac1_all0         = ~|ex1_oper1[9:0];
assign ex1_bfloat_frac0_all0       = ~|ex1_oper0[6:0];
assign ex1_bfloat_frac1_all0       = ~|ex1_oper1[6:0];
assign ex1_frac0_all0              = ex1_double ? ex1_doub_frac0_all0 :
                                     ex1_single ? ex1_sing_frac0_all0 :
                                     ex1_half ?   ex1_half_frac0_all0 : ex1_bfloat_frac0_all0;
assign ex1_frac1_all0              = ex1_double ? ex1_doub_frac1_all0 :
                                     ex1_single ? ex1_sing_frac1_all0 :
                                     ex1_half ?   ex1_half_frac1_all0 : ex1_bfloat_frac1_all0;
assign ex1_frac0_msb               = ex1_double ? ex1_oper0[51] :
                                     ex1_single ? ex1_oper0[22] :
                                     ex1_half   ? ex1_oper0[9]  : ex1_oper0[6];
assign ex1_frac1_msb               = ex1_double ? ex1_oper1[51] :
                                     ex1_single ? ex1_oper1[22] :
                                     ex1_half   ? ex1_oper1[9]  : ex1_oper1[6];
assign ex1_oper0_high_all1         = ex1_single ? &ex1_oper0[63:32] : &ex1_oper0[63:16]; 
assign ex1_oper1_high_all1         = ex1_single ? &ex1_oper1[63:32] : &ex1_oper1[63:16];
 

 
wire ex1_frac0_msb_nan,ex1_frac1_msb_nan;
assign ex1_frac0_msb_nan               = ex1_double ? ex1_oper0_nan[51] :
                                         ex1_single ? ex1_oper0_nan[22] :
                                         ex1_half   ? ex1_oper0_nan[9]  : ex1_oper0_nan[6];
assign ex1_frac1_msb_nan               = ex1_double ? ex1_oper1_nan[51] :
                                         ex1_single ? ex1_oper1_nan[22] :
                                         ex1_half   ? ex1_oper1_nan[9]  : ex1_oper1_nan[6];
 
 
 

 
assign  ex1_op0_inf                = ex1_expnt0_max && 
                                     ex1_frac0_all0 &&
                                    ~ex1_op0_cnan;
assign  ex1_op1_inf                = ex1_expnt1_max && 
                                     ex1_frac1_all0 &&
                                    ~ex1_op1_cnan;
 
assign ex1_op0_zero                = ex1_expnt0_zero && 
                                     ex1_frac0_all0  &&
                                    ~ex1_op0_cnan;
assign ex1_op1_zero                = ex1_expnt1_zero && 
                                     ex1_frac1_all0  &&
                                    ~ex1_op1_cnan;
 
assign ex1_op0_id                  =  ex1_expnt0_zero && 
                                     ~ex1_frac0_all0  &&
                                     ~ex1_op0_cnan;
assign ex1_op1_id                  =  ex1_expnt1_zero && 
                                     ~ex1_frac1_all0  &&
                                     ~ex1_op1_cnan;
 
 
 
 
 
 
 
 
 
 
 
 
assign ex1_op0_id_nor              = ex1_op0_id;
assign ex1_op1_id_nor              = ex1_op1_id;

 
assign ex1_op0_cnan                =  ex1_scalar  &&
                                      !ex1_double &&
                                      !ex1_oper0_high_all1;
                                      
assign ex1_op1_cnan                =  ex1_scalar  && 
                                      !ex1_double &&
                                      !ex1_oper1_high_all1;

 
 
assign ex1_op0_snan                =  ex1_expnt0_max &&
                                     ~ex1_frac0_all0 &&
                                     ~ex1_frac0_msb_nan  &&
                                     ~ex1_op0_cnan;
assign ex1_op1_snan                =  ex1_expnt1_max &&
                                     ~ex1_frac1_all0 &&
                                     ~ex1_frac1_msb_nan  &&
                                     ~ex1_op1_cnan;

 
assign ex1_op0_qnan                = (ex1_expnt0_max && 
                                      ex1_frac0_msb) ||
                                      ex1_op0_cnan;
assign ex1_op1_qnan                = (ex1_expnt1_max && 
                                      ex1_frac1_msb) ||
                                      ex1_op1_cnan;
 
 
 
ct_vfdsu_ff1  x_frac0_expnt (
  .fanc_shift_num           (ex1_oper0_id_frac[51:0] ),
  .frac_bin_val             (ex1_oper0_id_expnt[12:0]),
  .frac_num                 (ex1_oper0_frac[51:0]    )
);

 
 
 

 
ct_vfdsu_ff1  x_frac1_expnt (
  .fanc_shift_num           (ex1_oper1_id_frac[51:0] ),
  .frac_bin_val             (ex1_oper1_id_expnt[12:0]),
  .frac_num                 (ex1_oper1_frac[51:0]    )
);

 
 
 
assign ex1_oper0_frac[51:0] = ex1_double ? ex1_oper0[51:0] :
                                           ex1_single ? {ex1_oper0[22:0],29'b0} :
                                           ex1_half   ? {ex1_oper0[9:0],42'b0}
                                                      : {ex1_oper0[6:0],45'b0};
assign ex1_oper1_frac[51:0] = ex1_double ? ex1_oper1[51:0] :
                                           ex1_single ? {ex1_oper1[22:0],29'b0} :
                                           ex1_half   ? {ex1_oper1[9:0],42'b0}
                                                      : {ex1_oper1[6:0],45'b0};
 
 
assign ex1_div_op0_expnt[12:0]     = ex1_double ? {2'b0,ex1_oper0[62:52]} : 
                                                  ex1_single ? {5'b0,ex1_oper0[30:23]} :
                                                  ex1_half   ? {8'b0,ex1_oper0[14:10]}
                                                             : {5'b0,ex1_oper0[14:7]};
assign ex1_expnt_adder_op0[12:0]   = ex1_op0_id_nor ? ex1_oper0_id_expnt[12:0]
                                                    : ex1_div_op0_expnt[12:0];
 
assign ex1_div_op1_expnt[12:0]  = ex1_double ? {2'b0,ex1_oper1[62:52]} :
                                               ex1_single ? {5'b0,ex1_oper1[30:23]} :
                                               ex1_half   ? {8'b0,ex1_oper1[14:10]}
                                                          : {5'b0,ex1_oper1[14:7]};
assign ex1_sqrt_op1_expnt[12:0] = ex1_double ? {3'b0,{10{1'b1}}} :  
                                               ex1_single ? {6'b0,{7{1'b1}}} : 
                                               ex1_half   ? {9'b0,{4{1'b1}}}   
                                                          : {6'b0,{7{1'b1}}};  
  
 
always @( ex1_oper1_id_expnt[12:0]
       or ex1_div
       or ex1_op1_id_nor
       or ex1_sqrt_op1_expnt[12:0]
       or ex1_sqrt
       or ex1_div_op1_expnt[12:0])
begin
case({ex1_div,ex1_sqrt})
  2'b10:   ex1_expnt_adder_op1[12:0] = ex1_op1_id_nor ? ex1_oper1_id_expnt[12:0]
                                                  : ex1_div_op1_expnt[12:0];
  2'b01:   ex1_expnt_adder_op1[12:0] = ex1_sqrt_op1_expnt[12:0];
  default: ex1_expnt_adder_op1[12:0] = 13'b0;
endcase
 
end
 
assign ex1_sqrt_expnt_result_odd =  ex1_expnt_adder_op0[0] ^ ex1_expnt_adder_op1[0];


 
 
 
 
 
 
 
 
 
 
 
 
 
assign ex1_nv      = ex1_div  && ex1_div_nv  || 
                     ex1_sqrt && ex1_sqrt_nv;
 
assign ex1_div_nv  = ex1_op0_snan || 
                     ex1_op1_snan || 
                    (ex1_op0_tt_zero && ex1_op1_tt_zero)|| 
                    (ex1_op0_inf && ex1_op1_inf);
assign ex1_op0_tt_zero = ex1_op0_zero;
assign ex1_op1_tt_zero = ex1_op1_zero;
 
assign ex1_sqrt_nv = ex1_op0_snan || 
                     ex1_op0_sign && 
                    (ex1_op0_norm || 
                     ex1_op0_inf );
assign ex1_op0_norm = !ex1_expnt0_zero && !ex1_expnt0_max && !ex1_op0_cnan || ex1_op0_id_nor ;
assign ex1_op1_norm = !ex1_expnt1_zero && !ex1_expnt1_max && !ex1_op1_cnan || ex1_op1_id_nor; 

 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
assign ex1_dz      = ex1_div && ex1_div_dz;
assign ex1_div_dz  = ex1_op1_tt_zero && ex1_op0_norm;

 
 
 
 
 
 
 
assign ex1_sqrt_expnt_odd          = ex1_sqrt_expnt_result_odd;

 
 
 
 
 
 
 
assign ex1_result_zero   = ex1_div_rst_zero  && ex1_div  || 
                           ex1_sqrt_rst_zero && ex1_sqrt;
assign ex1_div_rst_zero  = (ex1_op0_tt_zero && ex1_op1_norm ) || 
                           (!ex1_expnt0_max && !ex1_op0_cnan && ex1_op1_inf);
assign ex1_sqrt_rst_zero = ex1_op0_tt_zero;

 
 
 
 
 
 
assign ex1_result_qnan   = ex1_div_rst_qnan  && ex1_div  || 
                           ex1_sqrt_rst_qnan && ex1_sqrt || 
                           ex1_nv;
assign ex1_div_rst_qnan  = ex1_op0_qnan || 
                           ex1_op1_qnan;
assign ex1_sqrt_rst_qnan = ex1_op0_qnan;

 
 
assign ex1_rst_default_qnan = (ex1_div && ex1_op0_zero && ex1_op1_zero) || 
                              (ex1_div && ex1_op0_inf  && ex1_op1_inf)  || 
                              (ex1_sqrt&& ex1_op0_sign && (ex1_op0_norm || ex1_op0_inf));

 
 
 
 
 
 
 
assign ex1_result_inf    = ex1_div_rst_inf  && ex1_div  || 
                           ex1_sqrt_rst_inf && ex1_sqrt || 
                           ex1_dz ;
assign ex1_div_rst_inf   = ex1_op0_inf && !ex1_expnt1_max && !ex1_op1_cnan;
assign ex1_sqrt_rst_inf  = ex1_op0_inf && !ex1_op0_sign;

 
 

assign ex1_rm[2:0]       = ((ex1_static_rm[2:0] == 3'b111)|| !ex1_scalar)
                         ? vfpu_yy_xx_rm[2:0]
                         : ex1_static_rm[2:0];
 
 
 
 
 
 
always @( ex1_rm[2:0]
       or ex1_result_sign)
begin
case(ex1_rm[2:0])
  3'b000  : ex1_of_result_lfn = 1'b0;
  3'b001  : ex1_of_result_lfn = 1'b1;
  3'b010  : ex1_of_result_lfn = !ex1_result_sign;
  3'b011  : ex1_of_result_lfn = ex1_result_sign;
  3'b100  : ex1_of_result_lfn = 1'b0;
  default: ex1_of_result_lfn = 1'b0;
endcase
 
end

 
 
 
assign ex1_remainder[59:0] = {60{ex1_div }} & {5'b0,ex1_div_srt_op0[52:0],2'b0} | 
                             {60{ex1_sqrt}} & sqrt_remainder[59:0];

 
 
assign ex1_divisor[52:0]   = ex1_div_srt_op1[52:0];

 
assign ex1_div_srt_op0[52:0]     = ex1_div_nor_srt_op0[52:0];
 
assign ex1_div_srt_op1[52:0]     =  ex1_div_nor_srt_op1[52:0];
 
assign ex1_div_noid_nor_srt_op0[52:0] = ex1_double ? {1'b1,ex1_oper0[51:0]} :
                                                     ex1_single ? {1'b1,ex1_oper0[22:0],29'b0} :
                                                     ex1_half   ? {1'b1,ex1_oper0[9:0],42'b0}
                                                                : {1'b1,ex1_oper0[6:0],45'b0};
assign ex1_div_noid_nor_srt_op1[52:0] = ex1_double ? {1'b1,ex1_oper1[51:0]} :
                                                     ex1_single ? {1'b1,ex1_oper1[22:0],29'b0} :
                                                     ex1_half   ? {1'b1,ex1_oper1[9:0],42'b0}
                                                                : {1'b1,ex1_oper1[6:0],45'b0};
assign ex1_div_nor_srt_op0[52:0] = ex1_op0_id_nor ? {ex1_oper0_id_frac[51:0],1'b0} 
                                                  : ex1_div_noid_nor_srt_op0[52:0];
 
assign ex1_div_nor_srt_op1[52:0] = ex1_op1_id_nor ? {ex1_oper1_id_frac[51:0],1'b0} 
                                                  : ex1_div_noid_nor_srt_op1[52:0];
 
assign sqrt_remainder[59:0]      = (ex1_sqrt_expnt_odd)
                                 ? {5'b0,ex1_sqrt_srt_op0[52:0],2'b0}
                                 : {6'b0,ex1_sqrt_srt_op0[52:0],1'b0};
 
assign ex1_sqrt_srt_op0[52:0]    = ex1_div_srt_op0[52:0];

 
assign ex1_op0_is_snan      = ex1_op0_snan;
assign ex1_op1_is_snan      = ex1_op1_snan && ex1_div;
assign ex1_op0_is_qnan      = ex1_op0_qnan;
assign ex1_op1_is_qnan      = ex1_op1_qnan && ex1_div;
assign ex1_op0_f[51:0]      = (ex1_op0_cnan) ? 52'b0: ex1_oper0[51:0];
assign ex1_op1_f[51:0]      = (ex1_op1_cnan) ? 52'b0: ex1_oper1[51:0];
 
always @( ex1_op0_is_snan
       or ex1_op0_is_qnan
       or ex1_op0_f[51:0]
       or ex1_rst_default_qnan
       or ex1_op1_f[51:0]
       or vfpu_yy_xx_dqnan
       or ex1_op1_is_snan
       or ex1_op1_is_qnan)
begin
if(ex1_rst_default_qnan)
  ex1_qnan_f[51:0] = {1'b1, 51'b0};
else if(ex1_op0_is_snan && vfpu_yy_xx_dqnan)
  ex1_qnan_f[51:0] = ex1_op0_f[51:0];
else if(ex1_op1_is_snan && vfpu_yy_xx_dqnan)
  ex1_qnan_f[51:0] = ex1_op1_f[51:0];
else if(ex1_op0_is_qnan && vfpu_yy_xx_dqnan)
  ex1_qnan_f[51:0] = ex1_op0_f[51:0];
else if(ex1_op1_is_qnan && vfpu_yy_xx_dqnan)
  ex1_qnan_f[51:0] = ex1_op1_f[51:0];
else
  ex1_qnan_f[51:0] = {1'b1, 51'b0};
 
end

 
always @( ex1_op0_is_snan
       or ex1_op0_cnan
       or ex1_op0_is_qnan
       or ex1_op1_sign
       or ex1_op0_sign
       or ex1_rst_default_qnan
       or vfpu_yy_xx_dqnan
       or ex1_op1_cnan
       or ex1_op1_is_snan
       or ex1_op1_is_qnan)
begin
 

 
 
 
 
 
 
 
 
 
 
 
 

  ex1_qnan_sign = 1'b0;
 
end


 
 
 
 
 
 
assign ex1_srt_skip = ex1_result_zero || 
                      ex1_result_qnan || 
                      ex1_result_inf;
 
 
gated_clk_cell  x_ex1_pipe_clk (
  .clk_in             (forever_cpuclk    ),
  .clk_out            (ex1_pipe_clk      ),
  .external_en        (1'b0              ),
  .global_en          (cp0_yy_clk_en     ),
  .local_en           (ex1_pipe_clk_en   ),
  .module_en          (cp0_vfpu_icg_en   ),
  .pad_yy_icg_scan_en (pad_yy_icg_scan_en)
);

 
 
 
 
 
 
 
assign ex1_pipe_clk_en = ex1_pipedown;

always @(posedge ex1_pipe_clk or negedge cpurst_b)
begin
  if(!cpurst_b)
  begin
    vfdsu_ex2_result_zero     <=  1'b0; 
    vfdsu_ex2_result_qnan     <=  1'b0; 
    vfdsu_ex2_result_inf      <=  1'b0; 
    vfdsu_ex2_result_sign     <=  1'b0; 
    vfdsu_ex2_op0_norm        <=  1'b0; 
    vfdsu_ex2_op1_norm        <=  1'b0; 
    vfdsu_ex2_expnt_add0[12:0] <= 13'b0; 
    vfdsu_ex2_expnt_add1[12:0] <= 13'b0; 
    vfdsu_ex2_nv              <=  1'b0; 
    vfdsu_ex2_dz              <=  1'b0; 
    vfdsu_ex2_srt_skip        <=  1'b0; 
    vfdsu_ex2_of_rm_lfn       <=  1'b0;
    vfdsu_ex2_qnan_sign       <=  1'b0;
    vfdsu_ex2_qnan_f[51:0]    <= 52'b0;
    vfdsu_ex2_rm[2:0]         <=  3'b0;
    vfdsu_ex2_div             <=  1'b0;
    vfdsu_ex2_sqrt            <=  1'b0;
    vfdsu_ex2_double          <=  1'b0;
    vfdsu_ex2_single          <=  1'b0;
    vfdsu_ex2_half            <=  1'b0;
    vfdsu_ex2_bfloat          <=  1'b0;
  end
  else if(ex1_pipedown)
  begin
    vfdsu_ex2_result_zero     <= ex1_result_zero; 
    vfdsu_ex2_result_qnan     <= ex1_result_qnan; 
    vfdsu_ex2_result_inf      <= ex1_result_inf; 
    vfdsu_ex2_result_sign     <= ex1_result_sign; 
    vfdsu_ex2_op0_norm        <= ex1_op0_norm; 
    vfdsu_ex2_op1_norm        <= ex1_op1_norm; 
    vfdsu_ex2_expnt_add0[12:0] <= ex1_expnt_adder_op0[12:0];
    vfdsu_ex2_expnt_add1[12:0] <= ex1_expnt_adder_op1[12:0];
    vfdsu_ex2_nv              <= ex1_nv; 
    vfdsu_ex2_dz              <= ex1_dz; 
    vfdsu_ex2_srt_skip        <= ex1_srt_skip; 
    vfdsu_ex2_of_rm_lfn       <= ex1_of_result_lfn;
    vfdsu_ex2_qnan_sign       <= ex1_qnan_sign;
    vfdsu_ex2_qnan_f[51:0]    <= ex1_qnan_f[51:0];
    vfdsu_ex2_rm[2:0]         <= ex1_rm[2:0];
    vfdsu_ex2_div             <= ex1_div;
    vfdsu_ex2_sqrt            <= ex1_sqrt;
    vfdsu_ex2_double          <= ex1_double;
    vfdsu_ex2_single          <= ex1_single;
    vfdsu_ex2_half            <= ex1_half;
    vfdsu_ex2_bfloat          <= ex1_bfloat;
  end
  else
  begin
    vfdsu_ex2_result_zero     <= vfdsu_ex2_result_zero; 
    vfdsu_ex2_result_qnan     <= vfdsu_ex2_result_qnan; 
    vfdsu_ex2_result_inf      <= vfdsu_ex2_result_inf; 
    vfdsu_ex2_result_sign     <= vfdsu_ex2_result_sign; 
    vfdsu_ex2_op0_norm        <= vfdsu_ex2_op0_norm; 
    vfdsu_ex2_op1_norm        <= vfdsu_ex2_op1_norm; 
    vfdsu_ex2_expnt_add0[12:0] <= vfdsu_ex2_expnt_add0[12:0]; 
    vfdsu_ex2_expnt_add1[12:0] <= vfdsu_ex2_expnt_add1[12:0]; 
    vfdsu_ex2_nv              <= vfdsu_ex2_nv; 
    vfdsu_ex2_dz              <= vfdsu_ex2_dz; 
    vfdsu_ex2_srt_skip        <= vfdsu_ex2_srt_skip; 
    vfdsu_ex2_of_rm_lfn       <= vfdsu_ex2_of_rm_lfn;
    vfdsu_ex2_qnan_sign       <= vfdsu_ex2_qnan_sign;
    vfdsu_ex2_qnan_f[51:0]    <= vfdsu_ex2_qnan_f[51:0];
    vfdsu_ex2_rm[2:0]         <= vfdsu_ex2_rm[2:0];
    vfdsu_ex2_div             <= vfdsu_ex2_div;
    vfdsu_ex2_sqrt            <= vfdsu_ex2_sqrt;
    vfdsu_ex2_double          <= vfdsu_ex2_double;
    vfdsu_ex2_single          <= vfdsu_ex2_single;
    vfdsu_ex2_half            <= vfdsu_ex2_half;
    vfdsu_ex2_bfloat          <= vfdsu_ex2_bfloat;
  end
end

 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 
 

 
endmodule



 
 
 
 
 
 
 
 
 
 
 
 

 

module fpnew_classifier #(
  parameter E6FPU_pkg::fp_format_e   FpFormat = E6FPU_pkg::fp_format_e'(0),
  parameter int unsigned             NumOperands = 1,
   
  localparam int unsigned WIDTH = E6FPU_pkg::fp_width(FpFormat)
) (
  input  logic                [NumOperands-1:0][WIDTH-1:0] operands_i,
  input  logic                [NumOperands-1:0]            is_boxed_i,
  output E6FPU_pkg::fp_info_t [NumOperands-1:0]            info_o
);

  localparam int unsigned EXP_BITS = E6FPU_pkg::exp_bits(FpFormat);
  localparam int unsigned MAN_BITS = E6FPU_pkg::man_bits(FpFormat);

   
  typedef struct packed {
    logic                sign;
    logic [EXP_BITS-1:0] exponent;
    logic [MAN_BITS-1:0] mantissa;
  } fp_t;

   
  for (genvar op = 0; op < int'(NumOperands); op++) begin : gen_num_values

    fp_t value;
    logic is_boxed;
    logic is_normal;
    logic is_inf;
    logic is_nan;
    logic is_signalling;
    logic is_quiet;
    logic is_zero;
    logic is_subnormal;

     
     
     
    always_comb begin : classify_input
      value         = operands_i[op];
      is_boxed      = is_boxed_i[op];
      is_normal     = is_boxed && (value.exponent != '0) && (value.exponent != '1);
      is_zero       = is_boxed && (value.exponent == '0) && (value.mantissa == '0);
      is_subnormal  = is_boxed && (value.exponent == '0) && !is_zero;
      is_inf        = is_boxed && ((value.exponent == '1) && (value.mantissa == '0));
      is_nan        = !is_boxed || ((value.exponent == '1) && (value.mantissa != '0));
      is_signalling = is_boxed && is_nan && (value.mantissa[MAN_BITS-1] == 1'b0);
      is_quiet      = is_nan && !is_signalling;
       
      info_o[op].is_normal     = is_normal;
      info_o[op].is_subnormal  = is_subnormal;
      info_o[op].is_zero       = is_zero;
      info_o[op].is_inf        = is_inf;
      info_o[op].is_nan        = is_nan;
      info_o[op].is_signalling = is_signalling;
      info_o[op].is_quiet      = is_quiet;
      info_o[op].is_boxed      = is_boxed;
    end
  end
endmodule

 
 
 
 
 
 
 
 
 
 
 
 

 

`include "E6.svh"

module fpnew_fma_multi #(
  parameter E6FPU_pkg::fmt_logic_t   FpFmtConfig = '1,
  parameter int unsigned             NumPipeRegs = 0,
  parameter E6FPU_pkg::pipe_config_t PipeConfig  = E6FPU_pkg::BEFORE,
  parameter type                     TagType     = logic,
  parameter type                     AuxType     = logic,
   
  localparam int unsigned WIDTH       = E6FPU_pkg::max_fp_width(FpFmtConfig),
  localparam int unsigned NUM_FORMATS = E6FPU_pkg::NUM_FP_FORMATS,
  localparam int unsigned ExtRegEnaWidth = NumPipeRegs == 0 ? 1 : NumPipeRegs
) (
  input  logic                        clk_i,
  input  logic                        rst_ni,
   
  input  logic [2:0][WIDTH-1:0]       operands_i,  
  input  logic [NUM_FORMATS-1:0][2:0] is_boxed_i,  
  input  E6FPU_pkg::roundmode_e       rnd_mode_i,
  input  E6FPU_pkg::operation_e       op_i,
  input  logic                        op_mod_i,
  input  E6FPU_pkg::fp_format_e       src_fmt_i,   
  input  E6FPU_pkg::fp_format_e       src2_fmt_i,  
  input  E6FPU_pkg::fp_format_e       dst_fmt_i,   
  input  TagType                      tag_i,
  input  logic                        mask_i,
  input  AuxType                      aux_i,
   
  input  logic                        in_valid_i,
  output logic                        in_ready_o,
  input  logic                        flush_i,
   
  output logic [WIDTH-1:0]            result_o,
  output E6FPU_pkg::status_t          status_o,
  output logic                        extension_bit_o,
  output TagType                      tag_o,
  output logic                        mask_o,
  output AuxType                      aux_o,
   
  output logic                        out_valid_o,
  input  logic                        out_ready_i,
   
  output logic                        busy_o,
   
  output logic                        fw_out_valid_o,
  output logic [WIDTH-1:0]            fw_result_o,
  output E6FPU_pkg::status_t          fw_status_o,
  output TagType                      fw_tag_o,

   
  input  logic [ExtRegEnaWidth-1:0]   reg_ena_i
);

   
   
   
   
  localparam E6FPU_pkg::fp_encoding_t SUPER_FORMAT = E6FPU_pkg::super_format(FpFmtConfig);

  localparam int unsigned SUPER_EXP_BITS = SUPER_FORMAT.exp_bits;
  localparam int unsigned SUPER_MAN_BITS = SUPER_FORMAT.man_bits;

   
  localparam int unsigned PRECISION_BITS = SUPER_MAN_BITS + 1;
   
  localparam int unsigned LOWER_SUM_WIDTH  = 2 * PRECISION_BITS + 3;
  localparam int unsigned LZC_RESULT_WIDTH = $clog2(LOWER_SUM_WIDTH);
   
   
   
  localparam int unsigned EXP_WIDTH = E6FPU_pkg::maximum(SUPER_EXP_BITS + 2, LZC_RESULT_WIDTH);
   
  localparam int unsigned SHIFT_AMOUNT_WIDTH = $clog2(3 * PRECISION_BITS + 5);
   
  localparam NUM_INP_REGS = PipeConfig == E6FPU_pkg::BEFORE
                            ? NumPipeRegs
                            : (PipeConfig == E6FPU_pkg::DISTRIBUTED
                               ? ((NumPipeRegs + 1) / 3)  
                               : 0);  
  localparam NUM_MID_REGS = PipeConfig == E6FPU_pkg::INSIDE
                          ? NumPipeRegs
                          : (PipeConfig == E6FPU_pkg::DISTRIBUTED
                             ? ((NumPipeRegs + 2) / 3)  
                             : 0);  
  localparam NUM_OUT_REGS = PipeConfig == E6FPU_pkg::AFTER
                            ? NumPipeRegs
                            : (PipeConfig == E6FPU_pkg::DISTRIBUTED
                               ? (NumPipeRegs / 3)  
                               : 0);  
  
   
  localparam SA_FADD_ENABLE = 1;

   
   
   
  typedef struct packed {
    logic                      sign;
    logic [SUPER_EXP_BITS-1:0] exponent;
    logic [SUPER_MAN_BITS-1:0] mantissa;
  } fp_t;

   
   
   
   
  logic [2:0][WIDTH-1:0] operands_q;
  E6FPU_pkg::fp_format_e src_fmt_q;
  E6FPU_pkg::fp_format_e src2_fmt_q;
  E6FPU_pkg::fp_format_e dst_fmt_q;

   
  logic                  [0:NUM_INP_REGS][2:0][WIDTH-1:0]       inp_pipe_operands_q;
  logic                  [0:NUM_INP_REGS][NUM_FORMATS-1:0][2:0] inp_pipe_is_boxed_q;
  E6FPU_pkg::roundmode_e [0:NUM_INP_REGS]                       inp_pipe_rnd_mode_q;
  E6FPU_pkg::operation_e [0:NUM_INP_REGS]                       inp_pipe_op_q;
  logic                  [0:NUM_INP_REGS]                       inp_pipe_op_mod_q;
  E6FPU_pkg::fp_format_e [0:NUM_INP_REGS]                       inp_pipe_src_fmt_q;
  E6FPU_pkg::fp_format_e [0:NUM_INP_REGS]                       inp_pipe_src2_fmt_q;
  E6FPU_pkg::fp_format_e [0:NUM_INP_REGS]                       inp_pipe_dst_fmt_q;
  TagType                [0:NUM_INP_REGS]                       inp_pipe_tag_q;
  logic                  [0:NUM_INP_REGS]                       inp_pipe_mask_q;
  AuxType                [0:NUM_INP_REGS]                       inp_pipe_aux_q;
  logic                  [0:NUM_INP_REGS]                       inp_pipe_valid_q;
   
  logic [0:NUM_INP_REGS] inp_pipe_ready;

   
  assign inp_pipe_operands_q[0] = operands_i;
  assign inp_pipe_is_boxed_q[0] = is_boxed_i;
  assign inp_pipe_rnd_mode_q[0] = rnd_mode_i;
  assign inp_pipe_op_q[0]       = op_i;
  assign inp_pipe_op_mod_q[0]   = op_mod_i;
  assign inp_pipe_src_fmt_q[0]  = src_fmt_i;
  assign inp_pipe_src2_fmt_q[0] = src2_fmt_i;
  assign inp_pipe_dst_fmt_q[0]  = dst_fmt_i;
  assign inp_pipe_tag_q[0]      = tag_i;
  assign inp_pipe_mask_q[0]     = mask_i;
  assign inp_pipe_aux_q[0]      = aux_i;
  assign inp_pipe_valid_q[0]    = in_valid_i;
   
  assign in_ready_o = inp_pipe_ready[0];
   
  for (genvar i = 0; i < NUM_INP_REGS; i++) begin : gen_input_pipeline
     
    logic reg_ena;
     
     
     
    assign inp_pipe_ready[i] = inp_pipe_ready[i+1] | ~inp_pipe_valid_q[i+1];
     
    `FFLARNC(inp_pipe_valid_q[i+1], inp_pipe_valid_q[i], inp_pipe_ready[i], flush_i, 1'b0, clk_i, rst_ni)
     
    assign reg_ena = (inp_pipe_ready[i] & inp_pipe_valid_q[i]) | reg_ena_i[i];
     
    `FFL(inp_pipe_operands_q[i+1], inp_pipe_operands_q[i], reg_ena, '0)
    `FFL(inp_pipe_is_boxed_q[i+1], inp_pipe_is_boxed_q[i], reg_ena, '0)
    `FFL(inp_pipe_rnd_mode_q[i+1], inp_pipe_rnd_mode_q[i], reg_ena, E6FPU_pkg::RNE)
    `FFL(inp_pipe_op_q[i+1],       inp_pipe_op_q[i],       reg_ena, E6FPU_pkg::FMADD)
    `FFL(inp_pipe_op_mod_q[i+1],   inp_pipe_op_mod_q[i],   reg_ena, '0)
    `FFL(inp_pipe_src_fmt_q[i+1],  inp_pipe_src_fmt_q[i],  reg_ena, E6FPU_pkg::fp_format_e'(0))
    `FFL(inp_pipe_src2_fmt_q[i+1], inp_pipe_src2_fmt_q[i], reg_ena, E6FPU_pkg::fp_format_e'(0))
    `FFL(inp_pipe_dst_fmt_q[i+1],  inp_pipe_dst_fmt_q[i],  reg_ena, E6FPU_pkg::fp_format_e'(0))
    `FFL(inp_pipe_tag_q[i+1],      inp_pipe_tag_q[i],      reg_ena, TagType'('0))
    `FFL(inp_pipe_mask_q[i+1],     inp_pipe_mask_q[i],     reg_ena, '0)
    `FFL(inp_pipe_aux_q[i+1],      inp_pipe_aux_q[i],      reg_ena, AuxType'('0))
  end
   
  assign operands_q = inp_pipe_operands_q[NUM_INP_REGS];
  assign src_fmt_q  = inp_pipe_src_fmt_q[NUM_INP_REGS];
  assign src2_fmt_q = inp_pipe_src2_fmt_q[NUM_INP_REGS];
  assign dst_fmt_q  = inp_pipe_dst_fmt_q[NUM_INP_REGS];

   
   
   
  logic        [NUM_FORMATS-1:0][2:0]                     fmt_sign;
  logic signed [NUM_FORMATS-1:0][2:0][SUPER_EXP_BITS-1:0] fmt_exponent;
  logic        [NUM_FORMATS-1:0][2:0][SUPER_MAN_BITS-1:0] fmt_mantissa;

  E6FPU_pkg::fp_info_t [NUM_FORMATS-1:0][2:0] info_q;

   
  for (genvar fmt = 0; fmt < int'(NUM_FORMATS); fmt++) begin : fmt_init_inputs
     
    localparam int unsigned FP_WIDTH = E6FPU_pkg::fp_width(E6FPU_pkg::fp_format_e'(fmt));
    localparam int unsigned EXP_BITS = E6FPU_pkg::exp_bits(E6FPU_pkg::fp_format_e'(fmt));
    localparam int unsigned MAN_BITS = E6FPU_pkg::man_bits(E6FPU_pkg::fp_format_e'(fmt));

    if (FpFmtConfig[fmt]) begin : active_format
      localparam E6FPU_pkg::fp_format_e FpFormat = E6FPU_pkg::fp_format_e'(fmt);
      logic [2:0][FP_WIDTH-1:0] trimmed_ops;

       
      fpnew_classifier #(
        .FpFormat    ( FpFormat ),
        .NumOperands ( 3        )
      ) i_fpnew_classifier (
        .operands_i ( trimmed_ops                            ),
        .is_boxed_i ( inp_pipe_is_boxed_q[NUM_INP_REGS][fmt] ),
        .info_o     ( info_q[fmt]                            )
      );
      for (genvar op = 0; op < 3; op++) begin : gen_operands
        assign trimmed_ops[op]       = operands_q[op][FP_WIDTH-1:0];
        assign fmt_sign[fmt][op]     = operands_q[op][FP_WIDTH-1];
        assign fmt_exponent[fmt][op] = signed'({1'b0, operands_q[op][MAN_BITS+:EXP_BITS]});
        assign fmt_mantissa[fmt][op] = {info_q[fmt][op].is_normal, operands_q[op][MAN_BITS-1:0]} <<
                                       (SUPER_MAN_BITS - MAN_BITS);  
      end
    end else begin : inactive_format
      assign info_q[fmt]                 = '{default: E6FPU_pkg::DONT_CARE};  
      assign fmt_sign[fmt]               = E6FPU_pkg::DONT_CARE;              
      assign fmt_exponent[fmt]           = '{default: E6FPU_pkg::DONT_CARE};  
      assign fmt_mantissa[fmt]           = '{default: E6FPU_pkg::DONT_CARE};  
    end
  end

  fp_t                 operand_a, operand_b, operand_c;
  E6FPU_pkg::fp_info_t info_a,    info_b,    info_c;

   
   
   
   
   
   
   
   
   
   
   
   
  always_comb begin : op_select

     
    operand_a = {fmt_sign[src_fmt_q ][0], fmt_exponent[src_fmt_q ][0], fmt_mantissa[src_fmt_q ][0]};
    operand_b = {fmt_sign[src_fmt_q ][1], fmt_exponent[src_fmt_q ][1], fmt_mantissa[src_fmt_q ][1]};
    operand_c = {fmt_sign[src2_fmt_q][2], fmt_exponent[src2_fmt_q][2], fmt_mantissa[src2_fmt_q][2]};
    info_a    = info_q[src_fmt_q ][0];
    info_b    = info_q[src_fmt_q ][1];
    info_c    = info_q[src2_fmt_q][2];

     
    operand_c.sign = operand_c.sign ^ inp_pipe_op_mod_q[NUM_INP_REGS];

    unique case (inp_pipe_op_q[NUM_INP_REGS])
      E6FPU_pkg::FMADD:  ;  
      E6FPU_pkg::FNMSUB: operand_a.sign = ~operand_a.sign;  
      E6FPU_pkg::ADD,
      E6FPU_pkg::ADDS: begin  
        operand_a = '{sign: 1'b0, exponent: E6FPU_pkg::bias(src_fmt_q), mantissa: '0};
        info_a    = '{is_normal: 1'b1, is_boxed: 1'b1, default: 1'b0};  
      end
      E6FPU_pkg::MUL: begin  
        if (inp_pipe_rnd_mode_q[NUM_INP_REGS] == E6FPU_pkg::RDN)
          operand_c = '{sign: 1'b0, exponent: '0, mantissa: '0};
        else
          operand_c = '{sign: 1'b1, exponent: '0, mantissa: '0};
        info_c    = '{is_zero: 1'b1, is_boxed: 1'b1, default: 1'b0};  
      end
      default: begin  
        operand_a  = '{default: E6FPU_pkg::DONT_CARE};
        operand_b  = '{default: E6FPU_pkg::DONT_CARE};
        operand_c  = '{default: E6FPU_pkg::DONT_CARE};
        info_a     = '{default: E6FPU_pkg::DONT_CARE};
        info_b     = '{default: E6FPU_pkg::DONT_CARE};
        info_c     = '{default: E6FPU_pkg::DONT_CARE};
      end
    endcase
  end

   
   
   
  logic any_operand_inf;
  logic any_operand_nan;
  logic signalling_nan;
  logic effective_subtraction;
  logic tentative_sign;

   
  assign any_operand_inf = (| {info_a.is_inf,        info_b.is_inf,        info_c.is_inf});
  assign any_operand_nan = (| {info_a.is_nan,        info_b.is_nan,        info_c.is_nan});
  assign signalling_nan  = (| {info_a.is_signalling, info_b.is_signalling, info_c.is_signalling});
   
  assign effective_subtraction = operand_a.sign ^ operand_b.sign ^ operand_c.sign;
   
  assign tentative_sign = operand_a.sign ^ operand_b.sign;

   
   
   
  logic [WIDTH-1:0]   special_result;
  E6FPU_pkg::status_t special_status;
  logic               result_is_special;

  logic [NUM_FORMATS-1:0][WIDTH-1:0]    fmt_special_result;
  E6FPU_pkg::status_t [NUM_FORMATS-1:0] fmt_special_status;
  logic [NUM_FORMATS-1:0]               fmt_result_is_special;


  for (genvar fmt = 0; fmt < int'(NUM_FORMATS); fmt++) begin : gen_special_results
     
    localparam int unsigned FP_WIDTH = E6FPU_pkg::fp_width(E6FPU_pkg::fp_format_e'(fmt));
    localparam int unsigned EXP_BITS = E6FPU_pkg::exp_bits(E6FPU_pkg::fp_format_e'(fmt));
    localparam int unsigned MAN_BITS = E6FPU_pkg::man_bits(E6FPU_pkg::fp_format_e'(fmt));

    localparam logic [EXP_BITS-1:0] QNAN_EXPONENT = '1;
    localparam logic [MAN_BITS-1:0] QNAN_MANTISSA = 2**(MAN_BITS-1);
    localparam logic [MAN_BITS-1:0] ZERO_MANTISSA = '0;

    if (FpFmtConfig[fmt]) begin : active_format
      always_comb begin : special_results
        logic [FP_WIDTH-1:0] special_res;

         
        special_res                = {1'b0, QNAN_EXPONENT, QNAN_MANTISSA};  
        fmt_special_status[fmt]    = '0;
        fmt_result_is_special[fmt] = 1'b0;

         
         
         
         
        if ((info_a.is_inf && info_b.is_zero) || (info_a.is_zero && info_b.is_inf)) begin
          fmt_result_is_special[fmt] = 1'b1;  
          fmt_special_status[fmt].NV = 1'b1;  
         
        end else if (any_operand_nan) begin
          fmt_result_is_special[fmt] = 1'b1;            
          fmt_special_status[fmt].NV = signalling_nan;  
         
        end else if (any_operand_inf) begin
          fmt_result_is_special[fmt] = 1'b1;  
           
          if ((info_a.is_inf || info_b.is_inf) && info_c.is_inf && effective_subtraction)
            fmt_special_status[fmt].NV = 1'b1;  
           
          else if (info_a.is_inf || info_b.is_inf) begin
             
            special_res = {operand_a.sign ^ operand_b.sign, QNAN_EXPONENT, ZERO_MANTISSA};
           
          end else if (info_c.is_inf) begin
             
            special_res = {operand_c.sign, QNAN_EXPONENT, ZERO_MANTISSA};
          end
        end
         
        fmt_special_result[fmt]               = '1;
        fmt_special_result[fmt][FP_WIDTH-1:0] = special_res;
      end
    end else begin : inactive_format
      assign fmt_special_result[fmt] = '{default: E6FPU_pkg::DONT_CARE};
      assign fmt_special_status[fmt] = '0;
      assign fmt_result_is_special[fmt] = 1'b0;
    end
  end

   
  assign result_is_special = fmt_result_is_special[dst_fmt_q];  
   
  assign special_status = fmt_special_status[dst_fmt_q];
   
  assign special_result = fmt_special_result[dst_fmt_q];  

   
   
   
   
  logic                inp_fadd_valid;
  fp_t                 fmul_operand_a, fmul_operand_b, fmul_operand_c;
  E6FPU_pkg::fp_info_t fmul_info_a,    fmul_info_b,    fmul_info_c;           
  logic [WIDTH-1:0]    fadd_operand_a, fadd_operand_b;
  E6FPU_pkg::fp_info_t fadd_info_a,    fadd_info_b;
  

   
  if (SA_FADD_ENABLE)
    assign inp_fadd_valid = inp_pipe_valid_q[NUM_INP_REGS] && (inp_pipe_op_q[NUM_INP_REGS] == E6FPU_pkg::ADD);
  else
    assign inp_fadd_valid = 1'b0;
  
   
   
   
   
   
   
   

  assign fmul_operand_a = operand_a;
  assign fmul_operand_b = operand_b;
  assign fmul_operand_c = operand_c;
  assign fmul_info_a    = info_a;
  assign fmul_info_b    = info_b;
  assign fmul_info_c    = info_c;

   
  assign fadd_operand_a = inp_fadd_valid ? operand_b : 'b0;
  assign fadd_operand_b = inp_fadd_valid ? operand_c : 'b0;
  assign fadd_info_a    = inp_fadd_valid ? info_b    : '{default: E6FPU_pkg::DONT_CARE};
  assign fadd_info_b    = inp_fadd_valid ? info_c    : '{default: E6FPU_pkg::DONT_CARE};

   
   
   
  logic signed [EXP_WIDTH-1:0] exponent_a, exponent_b, exponent_c;
  logic signed [EXP_WIDTH-1:0] exponent_addend, exponent_product, exponent_difference;
  logic signed [EXP_WIDTH-1:0] tentative_exponent;

   
   
   
   
  assign exponent_a = signed'({1'b0, fmul_operand_a.exponent});
  assign exponent_b = signed'({1'b0, fmul_operand_b.exponent});
  assign exponent_c = signed'({1'b0, fmul_operand_c.exponent});

   
   
   
   
   
   
  assign exponent_addend = fmul_info_c.is_zero ? 1  
                           : signed'(exponent_c + $signed({1'b0, ~fmul_info_c.is_normal})  
                                     - signed'(E6FPU_pkg::bias(src2_fmt_q))
                                     + signed'(E6FPU_pkg::bias(dst_fmt_q)));  

   
  assign exponent_product = (fmul_info_a.is_zero || fmul_info_b.is_zero)  
                            ? 2 - signed'(E6FPU_pkg::bias(dst_fmt_q))
                            : signed'(exponent_a + fmul_info_a.is_subnormal
                                      + exponent_b + fmul_info_b.is_subnormal
                                      - 2*signed'(E6FPU_pkg::bias(src_fmt_q))
                                      + signed'(E6FPU_pkg::bias(dst_fmt_q)));  

   
  assign exponent_difference = exponent_addend - exponent_product;

   
  logic [SHIFT_AMOUNT_WIDTH-1:0] addend_shamt;

  always_comb begin : addend_shift_amount
     
    if (exponent_difference <= signed'(-2 * PRECISION_BITS - 1))
      addend_shamt = 3 * PRECISION_BITS + 4;
     
    else if (exponent_difference <= signed'(PRECISION_BITS + 2))
      addend_shamt = unsigned'(signed'(PRECISION_BITS) + 3 - exponent_difference);
     
    else
      addend_shamt = 0;
  end

   
  logic        [$clog2(SUPER_MAN_BITS)-1:0] addend_lzc_count;
  logic        [$clog2(SUPER_MAN_BITS)  :0] addend_lzc_count_sgn;
  logic        [SHIFT_AMOUNT_WIDTH    -1:0] addend_normalize_shamt;

   
  lzc #(
    .WIDTH ( SUPER_MAN_BITS ),
    .MODE  ( 1              )  
  ) i_addend_lzc (
     
    .in_i    ( fmul_operand_c.mantissa ),
    .cnt_o   ( addend_lzc_count   ),
    .empty_o (                    )
  );

  assign addend_lzc_count_sgn = signed'({1'b0, addend_lzc_count});

   
  always_comb begin
     
     
    if (fmul_info_c.is_normal || fmul_info_c.is_zero) begin
      addend_normalize_shamt = 0;
     
    end else if (exponent_addend <= 1) begin
      addend_normalize_shamt = 0;
     
    end else if (addend_lzc_count_sgn + 1 < exponent_addend) begin
      addend_normalize_shamt = addend_lzc_count + 1;
     
    end else begin
      addend_normalize_shamt = exponent_addend - 1;
    end
  end

   
  assign tentative_exponent = (exponent_difference > 0) ? exponent_addend - addend_normalize_shamt : exponent_product;

   
   
   
  logic [PRECISION_BITS-1:0]   mantissa_a, mantissa_b, mantissa_c;
  logic [2*PRECISION_BITS-1:0] product;              
  logic [3*PRECISION_BITS+3:0] product_shifted;      

   
   
   
   
  assign mantissa_a = {fmul_info_a.is_normal, fmul_operand_a.mantissa};
  assign mantissa_b = {fmul_info_b.is_normal, fmul_operand_b.mantissa};
  assign mantissa_c = {fmul_info_c.is_normal, fmul_operand_c.mantissa};

   
  assign product = mantissa_a * mantissa_b;

  logic inp_mid_next_en;
  logic fmul_inp_mid_next_en;
  logic fadd_inp_mid_next_en;
  logic [2*PRECISION_BITS-1:0] product_next;              

  `FFL(product_next, product, fmul_inp_mid_next_en, '0)

   
   
   
   
  assign product_shifted = product_next << 2;  

   
   
   
  logic [3*PRECISION_BITS+3:0] addend_after_shift;   
  logic [PRECISION_BITS-1:0]   addend_sticky_bits;   
  logic                        sticky_before_add;    
  logic [3*PRECISION_BITS+3:0] addend_shifted;       
  logic                        inject_carry_in;      

   
   
   
   
   
   
   
   
  assign {addend_after_shift, addend_sticky_bits} =
      (mantissa_c << (3 * PRECISION_BITS + 4)) >> addend_shamt;

  assign sticky_before_add     = (| addend_sticky_bits);

   
  assign addend_shifted = (effective_subtraction) ? ~addend_after_shift : addend_after_shift;
  assign inject_carry_in = effective_subtraction & ~sticky_before_add;

  logic [3*PRECISION_BITS+3:0] addend_shifted_next ;       
  logic                        inject_carry_in_next;      
  `FFL(addend_shifted_next ,     addend_shifted ,     fmul_inp_mid_next_en, '0)
  `FFL(inject_carry_in_next,     inject_carry_in,     fmul_inp_mid_next_en, '0)

   
   
   
  logic [3*PRECISION_BITS+4:0] sum_pos, sum_neg;  
  logic                        sum_carry;         
  logic [3*PRECISION_BITS+3:0] sum;               
  logic                        final_sign;

   
   
  assign sum_pos = product_shifted + addend_shifted_next + inject_carry_in_next;
  assign sum_carry = sum_pos[3*PRECISION_BITS+4];

   
   
   
   
  logic [3*PRECISION_BITS+3:0] addend_after_shift_next;   
  `FFL(addend_after_shift_next ,     addend_after_shift ,     fmul_inp_mid_next_en, '0)
  assign sum_neg = addend_after_shift_next - product_shifted;

  logic effective_subtraction_next;
  logic tentative_sign_next;
  `FFL(effective_subtraction_next ,     effective_subtraction ,     fmul_inp_mid_next_en, '0)
  `FFL(tentative_sign_next        ,     tentative_sign        ,     fmul_inp_mid_next_en, '0)
   
   
  assign sum        = (effective_subtraction_next && ~sum_carry) ? sum_neg : sum_pos;

   
   
   
   
  assign final_sign = (effective_subtraction_next && (sum_carry == tentative_sign_next))
                    ? 1'b1
                    : (effective_subtraction_next ? 1'b0 : tentative_sign_next);

   
   
   
   
  logic                          effective_subtraction_q;
  logic signed [EXP_WIDTH-1:0]   exponent_product_q;
  logic signed [EXP_WIDTH-1:0]   exponent_difference_q;
  logic signed [EXP_WIDTH-1:0]   tentative_exponent_q;
  logic [SHIFT_AMOUNT_WIDTH-1:0] addend_shamt_q;
  logic                          sticky_before_add_q;
  logic [3*PRECISION_BITS+3:0]   sum_q;
  logic                          final_sign_q;
  E6FPU_pkg::fp_format_e         dst_fmt_q2;
  E6FPU_pkg::roundmode_e         rnd_mode_q;
  logic                          result_is_special_q;
  fp_t                           special_result_q;
  E6FPU_pkg::status_t            special_status_q;
  logic                          fadd_valid_q;
  logic [WIDTH-1:0]              fadd_result_q;
  E6FPU_pkg::status_t            fadd_status_q;

   
  logic                  [0:NUM_MID_REGS]                         mid_pipe_eff_sub_q;
  logic signed           [0:NUM_MID_REGS][EXP_WIDTH-1:0]          mid_pipe_exp_prod_q;
  logic signed           [0:NUM_MID_REGS][EXP_WIDTH-1:0]          mid_pipe_exp_diff_q;
  logic signed           [0:NUM_MID_REGS][EXP_WIDTH-1:0]          mid_pipe_tent_exp_q;
  logic                  [0:NUM_MID_REGS][SHIFT_AMOUNT_WIDTH-1:0] mid_pipe_add_shamt_q;
  logic                  [0:NUM_MID_REGS]                         mid_pipe_sticky_q;
  logic                  [0:NUM_MID_REGS][3*PRECISION_BITS+3:0]   mid_pipe_sum_q;
  logic                  [0:NUM_MID_REGS]                         mid_pipe_final_sign_q;
  E6FPU_pkg::roundmode_e [0:NUM_MID_REGS]                         mid_pipe_rnd_mode_q;
  E6FPU_pkg::fp_format_e [0:NUM_MID_REGS]                         mid_pipe_dst_fmt_q;
  logic                  [0:NUM_MID_REGS]                         mid_pipe_res_is_spec_q;
  fp_t                   [0:NUM_MID_REGS]                         mid_pipe_spec_res_q;
  E6FPU_pkg::status_t    [0:NUM_MID_REGS]                         mid_pipe_spec_stat_q;
  TagType                [0:NUM_MID_REGS]                         mid_pipe_tag_q;
  logic                  [0:NUM_MID_REGS]                         mid_pipe_mask_q;
  AuxType                [0:NUM_MID_REGS]                         mid_pipe_aux_q;
  logic                  [0:NUM_MID_REGS]                         mid_pipe_valid_q;
  logic                  [0:NUM_MID_REGS]                         mid_fadd_valid_q;
  logic                  [0:NUM_MID_REGS][WIDTH-1:0]              mid_fadd_result_q;
  E6FPU_pkg::status_t    [0:NUM_MID_REGS]                         mid_fadd_status_q;

   
  logic [0:NUM_MID_REGS] mid_pipe_ready;

   
   
   
   
   
   
   
   
   
   
   
   
   
   
   
   
   
   
   
   

  logic signed [EXP_WIDTH-1:0]        exponent_product_next;
  logic signed [EXP_WIDTH-1:0]        exponent_difference_next;
  logic signed [EXP_WIDTH-1:0]        tentative_exponent_next;
  logic [SHIFT_AMOUNT_WIDTH-1:0]      addend_shamt_next;
  logic [SHIFT_AMOUNT_WIDTH    -1:0]  addend_normalize_shamt_next;
  logic                               sticky_before_add_next;    
  E6FPU_pkg::roundmode_e              inp_pipe_rnd_mode_q_next;
  E6FPU_pkg::fp_format_e              dst_fmt_q_next;
  logic                               result_is_special_next;
  logic [WIDTH-1:0]                   special_result_next;
  E6FPU_pkg::status_t                 special_status_next;
  TagType                             inp_pipe_tag_q_next;
  logic                               inp_pipe_mask_q_next;
  AuxType                             inp_pipe_aux_q_next;
  logic                               inp_pipe_valid_q_next;
  logic                               inp_fadd_valid_next;

  logic [WIDTH-1:0]                   fadd_result;
  E6FPU_pkg::status_t                 fadd_status;


  `FFL(exponent_product_next       ,     exponent_product       ,     fmul_inp_mid_next_en, '0)
  `FFL(exponent_difference_next    ,     exponent_difference    ,     fmul_inp_mid_next_en, '0)
  `FFL(tentative_exponent_next     ,     tentative_exponent     ,     fmul_inp_mid_next_en, '0)
  `FFL(addend_shamt_next           ,     addend_shamt           ,     fmul_inp_mid_next_en, '0)
  `FFL(addend_normalize_shamt_next ,     addend_normalize_shamt ,     fmul_inp_mid_next_en, '0)
  `FFL(sticky_before_add_next      ,     sticky_before_add      ,     fmul_inp_mid_next_en, '0)
  `FFL(inp_pipe_rnd_mode_q_next    ,     inp_pipe_rnd_mode_q[NUM_INP_REGS]     ,     inp_mid_next_en, E6FPU_pkg::RNE)
  `FFL(dst_fmt_q_next              ,     dst_fmt_q              ,     inp_mid_next_en, E6FPU_pkg::FP32)
  `FFL(result_is_special_next      ,     result_is_special      ,     inp_mid_next_en, '0)
  `FFL(special_result_next         ,     special_result         ,     inp_mid_next_en, '0)
  `FFL(special_status_next         ,     special_status         ,     inp_mid_next_en, '0)
  `FFL(inp_pipe_tag_q_next         ,     inp_pipe_tag_q         ,     inp_mid_next_en, '0)
  `FFL(inp_pipe_mask_q_next        ,     inp_pipe_mask_q        ,     inp_mid_next_en, '0)
  `FFL(inp_pipe_aux_q_next         ,     inp_pipe_aux_q         ,     inp_mid_next_en, '0)
  `FFL(inp_pipe_valid_q_next       ,     inp_pipe_valid_q       ,     inp_mid_next_en, '0)

  if (SA_FADD_ENABLE)
    `FFL(inp_fadd_valid_next         ,     inp_fadd_valid         ,     inp_mid_next_en, '0)
  else
    assign inp_fadd_valid_next = 1'b0;

   
  assign mid_pipe_eff_sub_q[0]     = effective_subtraction_next;
  assign mid_pipe_exp_prod_q[0]    = exponent_product_next;
  assign mid_pipe_exp_diff_q[0]    = exponent_difference_next;
  assign mid_pipe_tent_exp_q[0]    = tentative_exponent_next;
  assign mid_pipe_add_shamt_q[0]   = addend_shamt_next + addend_normalize_shamt_next;
  assign mid_pipe_sticky_q[0]      = sticky_before_add_next;
  assign mid_pipe_sum_q[0]         = sum;
  assign mid_pipe_final_sign_q[0]  = final_sign;
  assign mid_pipe_rnd_mode_q[0]    = inp_pipe_rnd_mode_q_next;
  assign mid_pipe_dst_fmt_q[0]     = dst_fmt_q_next;
  assign mid_pipe_res_is_spec_q[0] = result_is_special_next;
  assign mid_pipe_spec_res_q[0]    = special_result_next;
  assign mid_pipe_spec_stat_q[0]   = special_status_next;
  assign mid_pipe_tag_q[0]         = inp_pipe_tag_q_next;
  assign mid_pipe_mask_q[0]        = inp_pipe_mask_q_next;
  assign mid_pipe_aux_q[0]         = inp_pipe_aux_q_next;
  assign mid_pipe_valid_q[0]       = inp_pipe_valid_q_next;
  assign mid_fadd_valid_q[0]       = inp_fadd_valid_next;
  assign mid_fadd_result_q[0]      = fadd_result;
  assign mid_fadd_status_q[0]      = fadd_status;
   
  assign inp_pipe_ready[NUM_INP_REGS] = mid_pipe_ready[0];
  assign inp_mid_next_en           = mid_pipe_ready[0];
   
  assign fmul_inp_mid_next_en      = mid_pipe_ready[0];
  assign fadd_inp_mid_next_en      = mid_pipe_ready[0] &  inp_fadd_valid;

   
  for (genvar i = 0; i < NUM_MID_REGS; i++) begin : gen_inside_pipeline
     
    logic reg_ena;
    logic fmul_reg_ena, fadd_reg_ena;
     
     
     
    assign mid_pipe_ready[i] = mid_pipe_ready[i+1] | ~mid_pipe_valid_q[i+1];
     
    `FFLARNC(mid_pipe_valid_q[i+1], mid_pipe_valid_q[i], mid_pipe_ready[i], flush_i, 1'b0, clk_i, rst_ni)
    if (SA_FADD_ENABLE)
      `FFLARNC(mid_fadd_valid_q[i+1], mid_fadd_valid_q[i], mid_pipe_ready[i], flush_i, 1'b0, clk_i, rst_ni)
    else
      assign mid_fadd_valid_q[i+1] = 1'b0;
     
    assign reg_ena = (mid_pipe_ready[i] & mid_pipe_valid_q[i]) | reg_ena_i[NUM_INP_REGS + i];
     
    assign fmul_reg_ena = reg_ena;
    assign fadd_reg_ena = reg_ena &  mid_fadd_valid_q[i];
     
    `FFL(mid_pipe_eff_sub_q[i+1],     mid_pipe_eff_sub_q[i],     fmul_reg_ena, '0)
    `FFL(mid_pipe_exp_prod_q[i+1],    mid_pipe_exp_prod_q[i],    fmul_reg_ena, '0)
    `FFL(mid_pipe_exp_diff_q[i+1],    mid_pipe_exp_diff_q[i],    fmul_reg_ena, '0)
    `FFL(mid_pipe_tent_exp_q[i+1],    mid_pipe_tent_exp_q[i],    fmul_reg_ena, '0)
    `FFL(mid_pipe_add_shamt_q[i+1],   mid_pipe_add_shamt_q[i],   fmul_reg_ena, '0)
    `FFL(mid_pipe_sticky_q[i+1],      mid_pipe_sticky_q[i],      fmul_reg_ena, '0)
    `FFL(mid_pipe_sum_q[i+1],         mid_pipe_sum_q[i],         fmul_reg_ena, '0)
    `FFL(mid_pipe_final_sign_q[i+1],  mid_pipe_final_sign_q[i],  fmul_reg_ena, '0)
    `FFL(mid_pipe_rnd_mode_q[i+1],    mid_pipe_rnd_mode_q[i],    reg_ena, E6FPU_pkg::RNE)
    `FFL(mid_pipe_dst_fmt_q[i+1],     mid_pipe_dst_fmt_q[i],     reg_ena, E6FPU_pkg::fp_format_e'(0))
    `FFL(mid_pipe_res_is_spec_q[i+1], mid_pipe_res_is_spec_q[i], reg_ena, '0)
    `FFL(mid_pipe_spec_res_q[i+1],    mid_pipe_spec_res_q[i],    reg_ena, '0)
    `FFL(mid_pipe_spec_stat_q[i+1],   mid_pipe_spec_stat_q[i],   reg_ena, '0)
    `FFL(mid_pipe_tag_q[i+1],         mid_pipe_tag_q[i],         reg_ena, TagType'('0))
    `FFL(mid_pipe_mask_q[i+1],        mid_pipe_mask_q[i],        reg_ena, '0)
    `FFL(mid_pipe_aux_q[i+1],         mid_pipe_aux_q[i],         reg_ena, AuxType'('0))
    `FFL(mid_fadd_result_q[i+1],      mid_fadd_result_q[i],      fadd_reg_ena, AuxType'('0))
    `FFL(mid_fadd_status_q[i+1],      mid_fadd_status_q[i],      fadd_reg_ena, AuxType'('0))
  end
   
  assign effective_subtraction_q = mid_pipe_eff_sub_q[NUM_MID_REGS];
  assign exponent_product_q      = mid_pipe_exp_prod_q[NUM_MID_REGS];
  assign exponent_difference_q   = mid_pipe_exp_diff_q[NUM_MID_REGS];
  assign tentative_exponent_q    = mid_pipe_tent_exp_q[NUM_MID_REGS];
  assign addend_shamt_q          = mid_pipe_add_shamt_q[NUM_MID_REGS];
  assign sticky_before_add_q     = mid_pipe_sticky_q[NUM_MID_REGS];
  assign sum_q                   = mid_pipe_sum_q[NUM_MID_REGS];
  assign final_sign_q            = mid_pipe_final_sign_q[NUM_MID_REGS];
  assign rnd_mode_q              = mid_pipe_rnd_mode_q[NUM_MID_REGS];
  assign dst_fmt_q2              = mid_pipe_dst_fmt_q[NUM_MID_REGS];
  assign result_is_special_q     = mid_pipe_res_is_spec_q[NUM_MID_REGS];
  assign special_result_q        = mid_pipe_spec_res_q[NUM_MID_REGS];
  assign special_status_q        = mid_pipe_spec_stat_q[NUM_MID_REGS];
  assign fadd_valid_q            = mid_fadd_valid_q[NUM_MID_REGS];
  assign fadd_result_q           = mid_fadd_result_q[NUM_MID_REGS];
  assign fadd_status_q           = mid_fadd_status_q[NUM_MID_REGS];
  
   
   
   
  logic        [LOWER_SUM_WIDTH-1:0]  sum_lower;               
  logic        [LZC_RESULT_WIDTH-1:0] leading_zero_count;      
  logic signed [LZC_RESULT_WIDTH:0]   leading_zero_count_sgn;  
  logic                               lzc_zeroes;              

  logic        [SHIFT_AMOUNT_WIDTH-1:0] norm_shamt;  
  logic signed [EXP_WIDTH-1:0]          normalized_exponent;

  logic [3*PRECISION_BITS+4:0] sum_shifted;        
  logic [PRECISION_BITS:0]     final_mantissa;     
  logic [2*PRECISION_BITS+2:0] sum_sticky_bits;    
  logic                        sticky_after_norm;  

  logic signed [EXP_WIDTH-1:0] final_exponent;

  assign sum_lower = sum_q[LOWER_SUM_WIDTH-1:0];

   
  lzc #(
    .WIDTH ( LOWER_SUM_WIDTH ),
    .MODE  ( 1               )  
  ) i_lzc (
    .in_i    ( sum_lower          ),
    .cnt_o   ( leading_zero_count ),
    .empty_o ( lzc_zeroes         )
  );

  assign leading_zero_count_sgn = signed'({1'b0, leading_zero_count});

   
  always_comb begin : norm_shift_amount
     
    if ((exponent_difference_q <= 0) || (effective_subtraction_q && (exponent_difference_q <= 2))) begin
       
      if ((exponent_product_q - leading_zero_count_sgn + 1 >= 0) && !lzc_zeroes) begin
         
        norm_shamt          = PRECISION_BITS + 2 + leading_zero_count;
        normalized_exponent = exponent_product_q - leading_zero_count_sgn + 1;  
       
      end else begin
         
        norm_shamt          = unsigned'(signed'(PRECISION_BITS + 2 + exponent_product_q));
        normalized_exponent = 0;  
      end
     
    end else begin
      norm_shamt          = addend_shamt_q;  
      normalized_exponent = tentative_exponent_q;
    end
  end

   
  assign sum_shifted       = sum_q << norm_shamt;

   
   
  always_comb begin : small_norm
     
    {final_mantissa, sum_sticky_bits} = sum_shifted;
    final_exponent                    = normalized_exponent;

     
    if (sum_shifted[3*PRECISION_BITS+4]) begin  
      {final_mantissa, sum_sticky_bits} = sum_shifted >> 1;
      final_exponent                    = normalized_exponent + 1;
     
    end else if (sum_shifted[3*PRECISION_BITS+3]) begin  
       
     
    end else if (normalized_exponent > 1) begin
      {final_mantissa, sum_sticky_bits} = sum_shifted << 1;
      final_exponent                    = normalized_exponent - 1;
     
    end else begin
      final_exponent = '0;
    end
  end

   
  assign sticky_after_norm = (| {sum_sticky_bits}) | sticky_before_add_q;

   
   
   
  logic                                     pre_round_sign;
  logic [SUPER_EXP_BITS+SUPER_MAN_BITS-1:0] pre_round_abs;  
  logic [1:0]                               round_sticky_bits;

  logic of_before_round, of_after_round;  
  logic uf_before_round, uf_after_round;  

  logic [NUM_FORMATS-1:0][SUPER_EXP_BITS+SUPER_MAN_BITS-1:0] fmt_pre_round_abs;  
  logic [NUM_FORMATS-1:0][1:0]                               fmt_round_sticky_bits;

  logic [NUM_FORMATS-1:0]                                    fmt_of_after_round;
  logic [NUM_FORMATS-1:0]                                    fmt_uf_after_round;

  logic                                     rounded_sign;
  logic [SUPER_EXP_BITS+SUPER_MAN_BITS-1:0] rounded_abs;  
  logic                                     result_zero;

   
  assign of_before_round = final_exponent >= 2**(E6FPU_pkg::exp_bits(dst_fmt_q2))-1;  
  assign uf_before_round = final_exponent == 0;                

   
  for (genvar fmt = 0; fmt < int'(NUM_FORMATS); fmt++) begin : gen_res_assemble
     
    localparam int unsigned EXP_BITS = E6FPU_pkg::exp_bits(E6FPU_pkg::fp_format_e'(fmt));
    localparam int unsigned MAN_BITS = E6FPU_pkg::man_bits(E6FPU_pkg::fp_format_e'(fmt));

    logic [EXP_BITS-1:0] pre_round_exponent;
    logic [MAN_BITS-1:0] pre_round_mantissa;

    if (FpFmtConfig[fmt]) begin : active_format

      assign pre_round_exponent = (of_before_round) ? 2**EXP_BITS-2 : final_exponent[EXP_BITS-1:0];
      assign pre_round_mantissa = (of_before_round) ? '1 : final_mantissa[SUPER_MAN_BITS-:MAN_BITS];
       
      assign fmt_pre_round_abs[fmt] = {pre_round_exponent, pre_round_mantissa};  

       
      assign fmt_round_sticky_bits[fmt][1] = final_mantissa[SUPER_MAN_BITS-MAN_BITS] |
                                             of_before_round;

       
      if (MAN_BITS < SUPER_MAN_BITS) begin : narrow_sticky
        assign fmt_round_sticky_bits[fmt][0] = (| final_mantissa[SUPER_MAN_BITS-MAN_BITS-1:0]) |
                                               sticky_after_norm | of_before_round;
      end else begin : normal_sticky
        assign fmt_round_sticky_bits[fmt][0] = sticky_after_norm | of_before_round;
      end
    end else begin : inactive_format
      assign fmt_pre_round_abs[fmt] = '{default: E6FPU_pkg::DONT_CARE};
      assign fmt_round_sticky_bits[fmt] = '{default: E6FPU_pkg::DONT_CARE};
    end
  end

   
  assign pre_round_sign     = final_sign_q;
  assign pre_round_abs      = fmt_pre_round_abs[dst_fmt_q2];

   
  assign round_sticky_bits  = fmt_round_sticky_bits[dst_fmt_q2];

   
  fpnew_rounding #(
    .AbsWidth ( SUPER_EXP_BITS + SUPER_MAN_BITS )
  ) i_fpnew_rounding (
    .abs_value_i             ( pre_round_abs           ),
    .sign_i                  ( pre_round_sign          ),
    .round_sticky_bits_i     ( round_sticky_bits       ),
    .rnd_mode_i              ( rnd_mode_q              ),
    .effective_subtraction_i ( effective_subtraction_q ),
    .abs_rounded_o           ( rounded_abs             ),
    .sign_o                  ( rounded_sign            ),
    .exact_zero_o            ( result_zero             )
  );

  logic [NUM_FORMATS-1:0][WIDTH-1:0] fmt_result;

  for (genvar fmt = 0; fmt < int'(NUM_FORMATS); fmt++) begin : gen_sign_inject
     
    localparam int unsigned FP_WIDTH = E6FPU_pkg::fp_width(E6FPU_pkg::fp_format_e'(fmt));
    localparam int unsigned EXP_BITS = E6FPU_pkg::exp_bits(E6FPU_pkg::fp_format_e'(fmt));
    localparam int unsigned MAN_BITS = E6FPU_pkg::man_bits(E6FPU_pkg::fp_format_e'(fmt));

    if (FpFmtConfig[fmt]) begin : active_format
      always_comb begin : post_process
         
         
         
         
         
        fmt_uf_after_round[fmt] = (rounded_abs[EXP_BITS+MAN_BITS-1:MAN_BITS] == '0)  
        || ((pre_round_abs[EXP_BITS+MAN_BITS-1:MAN_BITS] == '0) && (rounded_abs[EXP_BITS+MAN_BITS-1:MAN_BITS] == 1) && 
              ((round_sticky_bits != 2'b11) || (!sum_sticky_bits[MAN_BITS*2 + 4] && ((rnd_mode_q == E6FPU_pkg::RNE)))));
        fmt_of_after_round[fmt] = rounded_abs[EXP_BITS+MAN_BITS-1:MAN_BITS] == '1;  

         
        fmt_result[fmt]               = '1;
        fmt_result[fmt][FP_WIDTH-1:0] = {rounded_sign, rounded_abs[EXP_BITS+MAN_BITS-1:0]};
      end
    end else begin : inactive_format
      assign fmt_uf_after_round[fmt] = E6FPU_pkg::DONT_CARE;
      assign fmt_of_after_round[fmt] = E6FPU_pkg::DONT_CARE;
      assign fmt_result[fmt]         = '{default: E6FPU_pkg::DONT_CARE};
    end
  end

   
  assign uf_after_round = fmt_uf_after_round[dst_fmt_q2];
  assign of_after_round = fmt_of_after_round[dst_fmt_q2];


   
   
   
  logic [WIDTH-1:0]     regular_result;
  E6FPU_pkg::status_t   regular_status;

   
  assign regular_result = fmt_result[dst_fmt_q2];
  assign regular_status.NV = 1'b0;  
  assign regular_status.DZ = 1'b0;  
  assign regular_status.OF = of_before_round | of_after_round;    
  assign regular_status.UF = uf_after_round & regular_status.NX;  
  assign regular_status.NX = (| round_sticky_bits) | of_before_round | of_after_round;

   
  logic [WIDTH-1:0]   result_d;
  E6FPU_pkg::status_t status_d;

   
  assign result_d = result_is_special_q ? special_result_q : (fadd_valid_q ? fadd_result_q : regular_result);
  assign status_d = result_is_special_q ? special_status_q : (fadd_valid_q ? fadd_status_q : regular_status);

   
   
   
   
  logic               [0:NUM_OUT_REGS][WIDTH-1:0] out_pipe_result_q;
  E6FPU_pkg::status_t [0:NUM_OUT_REGS]            out_pipe_status_q;
  TagType             [0:NUM_OUT_REGS]            out_pipe_tag_q;
  logic               [0:NUM_OUT_REGS]            out_pipe_mask_q;
  AuxType             [0:NUM_OUT_REGS]            out_pipe_aux_q;
  logic               [0:NUM_OUT_REGS]            out_pipe_valid_q;
   
  logic [0:NUM_OUT_REGS] out_pipe_ready;

   
  assign out_pipe_result_q[0] = result_d;
  assign out_pipe_status_q[0] = status_d;

  assign out_pipe_tag_q[0]    = mid_pipe_tag_q[NUM_MID_REGS];
  assign out_pipe_mask_q[0]   = mid_pipe_mask_q[NUM_MID_REGS];
  assign out_pipe_aux_q[0]    = mid_pipe_aux_q[NUM_MID_REGS];
  assign out_pipe_valid_q[0]  = mid_pipe_valid_q[NUM_MID_REGS];
   
  assign mid_pipe_ready[NUM_MID_REGS] = out_pipe_ready[0];
   
  for (genvar i = 0; i < NUM_OUT_REGS; i++) begin : gen_output_pipeline
     
    logic reg_ena;
     
     
     
    assign out_pipe_ready[i] = out_pipe_ready[i+1] | ~out_pipe_valid_q[i+1];
     
    `FFLARNC(out_pipe_valid_q[i+1], out_pipe_valid_q[i], out_pipe_ready[i], flush_i, 1'b0, clk_i, rst_ni)
     
    assign reg_ena = (out_pipe_ready[i] & out_pipe_valid_q[i]) | reg_ena_i[NUM_INP_REGS + NUM_MID_REGS + i];
     
    `FFL(out_pipe_result_q[i+1], out_pipe_result_q[i], reg_ena, '0)
    `FFL(out_pipe_status_q[i+1], out_pipe_status_q[i], reg_ena, '0)
    `FFL(out_pipe_tag_q[i+1],    out_pipe_tag_q[i],    reg_ena, TagType'('0))
    `FFL(out_pipe_mask_q[i+1],   out_pipe_mask_q[i],   reg_ena, '0)
    `FFL(out_pipe_aux_q[i+1],    out_pipe_aux_q[i],    reg_ena, AuxType'('0))
  end
   
  assign out_pipe_ready[NUM_OUT_REGS] = out_ready_i;
   
  assign result_o        = out_pipe_result_q[NUM_OUT_REGS];
  assign status_o        = out_pipe_status_q[NUM_OUT_REGS];
  assign extension_bit_o = 1'b1;  
  assign tag_o           = out_pipe_tag_q[NUM_OUT_REGS];
  assign mask_o          = out_pipe_mask_q[NUM_OUT_REGS];
  assign aux_o           = out_pipe_aux_q[NUM_OUT_REGS];
  assign out_valid_o     = out_pipe_valid_q[NUM_OUT_REGS];
  assign busy_o          = (| {inp_pipe_valid_q, mid_pipe_valid_q, out_pipe_valid_q});

   
   
   
  if (SA_FADD_ENABLE) begin
     
    fpnew_fma_multi_fadd #(
      .FpFmtConfig ( FpFmtConfig         )
    ) i_fpnew_fma_multi_fadd (
      .clk_i            ( clk_i                     ),
      .rst_ni           ( rst_ni                    ),

       
      .mid_pipe_ready   ( fadd_inp_mid_next_en      ),

       
      .operand_a        ( fadd_operand_a            ),
      .operand_b        ( fadd_operand_b            ),
      .info_a           ( fadd_info_a               ),
      .info_b           ( fadd_info_b               ),
      .rnd_mode_q_next  ( inp_pipe_rnd_mode_q_next  ),
      .dst_fmt_q_next   ( dst_fmt_q_next            ),         
       
      .result_o         ( fadd_result               ),
      .status_o         ( fadd_status               )
    );
  end else begin
      assign fadd_result = 'b0;
      assign fadd_status = 'b0;
  end

   
  assign fw_out_valid_o = fadd_valid_q;
  assign fw_result_o    = result_is_special_q ? special_result_q : fadd_result_q;
  assign fw_status_o    = result_is_special_q ? special_status_q : fadd_status_q;
  assign fw_tag_o       = mid_pipe_tag_q[NUM_MID_REGS];

endmodule


